import spidev
import signal
import sys

MIN_CHANNEL = 0
MAX_CHANNEL = 7
SPI_PORT = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1_000_000

_spi = None


def _cleanup(signum=None, frame=None):
    global _spi
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None
    if signum is not None:
        sys.exit(0)


def read_adc_channel(channel):
    """Read a single-ended channel from the MCP3208 over hardware SPI.

    Returns normalized 0.0–1.0 (single-ended mode) or raw 0–4095, or -1 on error.
    """
    global _spi
    if not (MIN_CHANNEL <= channel <= MAX_CHANNEL):
        print(f"Error: channel {channel} out of range [{MIN_CHANNEL}, {MAX_CHANNEL}].", file=sys.stderr)
        return -1

    if _spi is None:
        try:
            _spi = spidev.SpiDev()
            _spi.open(SPI_PORT, SPI_DEVICE)
            _spi.max_speed_hz = SPI_SPEED_HZ
            _spi.mode = 0
            _spi.bits_per_word = 8
        except Exception as e:
            print(f"Error initializing SPI: {e}", file=sys.stderr)
            return -1

    try:
        # MCP3208 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then dummy byte
        cmd = 0x06 | ((channel & 0x07) << 1)
        tx = [0x01, cmd, 0x00]
        rx = _spi.xfer2(tx)
        if len(rx) < 3:
            print("Error: SPI transfer returned insufficient bytes.", file=sys.stderr)
            return -1

        # 12-bit result: bits 11-8 in rx[1] bits 7-4, bits 7-0 in rx[2] bits 7-0
        value = ((rx[1] & 0x0F) << 8) | rx[2]
        if value > 0x0FFF:
            print(f"Error: ADC value {value} exceeds 12-bit range.", file=sys.stderr)
            return -1

        return value / 4095.0

    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}", file=sys.stderr)
        return -1
    finally:
        if _spi is not None:
            try:
                _spi.close()
            except Exception:
                pass
            _spi = None


def read_adc_normalized(channel):
    """Read a single-ended channel and return normalized 0.0–1.0."""
    return read_adc_channel(channel)


def read_adc_raw(channel):
    """Read a single-ended channel and return raw integer 0–4095."""
    return read_adc_channel(channel)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    print("Reading MCP3208 channel 0 (normalized):", read_adc_normalized(0))
    print("Reading MCP3208 channel 0 (raw):", read_adc_raw(0))

