#!/usr/bin/env python3
"""Smart Irrigation System for Raspberry Pi.

Controls a solenoid valve based on capacitive soil moisture readings from
an MCP3008 ADC (SPI bus 0, CE0, channel 0) and exposes a JSON-RPC command
interface over TCP on port 8080.
"""

import argparse
import json
import logging
import signal
import socket
import sys
import time

import spidev
from gpiozero import OutputDevice

DEFAULT_MOISTURE_THRESHOLD = 30
DEFAULT_WEB_PORT = 8080
DEFAULT_LOG_FILE = "irrigation.log"
DEFAULT_VALVE_PIN = 17
DEFAULT_SPI_CHANNEL = 0

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_valve: OutputDevice | None = None
_spi: spidev.SpiDev | None = None
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global _running
    logging.info("Received signal %s – shutting down.", signum)
    _running = False


def _setup_logging(log_file: str) -> None:
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def _read_mcp3008(channel: int) -> int:
    """Read a single-ended channel (0-7) from the MCP3008.

    Returns the 10-bit ADC value (0-1023) or -1 on error.
    """
    if _spi is None:
        logging.error("SPI device is not initialised.")
        return -1
    if not 0 <= channel <= 7:
        logging.error("Invalid MCP3008 channel %d", channel)
        return -1
    try:
        # MCP3008 single-ended read: start bit, config byte, padding
        r = _spi.xfer2([1, (0x08 | channel) << 4, 0])
        return ((r[1] & 0x03) << 8) | r[2]
    except OSError as e:
        logging.error("SPI read error on channel %d: %s", channel, e)
        return -1


def _validate_moisture(value: int) -> bool:
    """Return True only when the 10-bit reading is within the valid range."""
    return 0 <= value <= 1023


def _cleanup() -> None:
    """Release all hardware resources."""
    global _valve, _spi
    if _valve is not None:
        try:
            _valve.close()
        except Exception:
            pass
        _valve = None
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None


def _handle_command(command: dict) -> dict:
    """Process a JSON-RPC command. Returns a status dict."""
    status = {"status": "error", "message": "Invalid command."}
    if command.get("action") == "get_status":
        status = _get_status()
    elif command.get("action") == "toggle_valve":
        status = _toggle_valve(command.get("value", "on"))
    else:
        status = {"status": "error", "message": "Unknown command."}
    return status


def _get_status() -> dict:
    moisture = _read_mcp3008(DEFAULT_SPI_CHANNEL)
    if moisture < 0:
        return {"status": "error", "message": "Sensor read failed."}
    if not _validate_moisture(moisture):
        return {"status": "error", "message": "Invalid moisture reading."}
    valve_state = "on" if _valve.is_active else "off"
    return {
        "moisture": moisture,
        "valve_state": valve_state,
        "threshold": DEFAULT_MOISTURE_THRESHOLD,
    }


def _toggle_valve(value: str) -> dict:
    global _valve
    if value == "on":
        if _valve is None or not _valve.is_active:
            _valve.on()
            return {"status": "ok", "message": "Valve turned ON."}
    elif value == "off":
        if _valve is not None and _valve.is_active:
            _valve.off()
            return {"status": "ok", "message": "Valve turned OFF."}
    return {"status": "error", "message": "Invalid value. Use 'on' or 'off'."}


def _run_web_server(web_port: int) -> None:
    """Run the JSON-RPC server until _running becomes False."""
    global _running
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        server_socket.bind(("", web_port))
        server_socket.listen(5)
        logging.info("Listening on port %d", web_port)
        while _running:
            try:
                conn, addr = server_socket.accept()
            except OSError:
                if _running:
                    continue
                break
            with conn:
                logging.info("Connection from %s", addr)
                try:
                    data = conn.recv(1024)
                except OSError:
                    continue
                if not data:
                    continue
                try:
                    command = json.loads(data.decode("utf-8"))
                except json.JSONDecodeError:
                    logging.warning("Invalid JSON received: %r", data)
                    continue
                if command.get("action") not in ("get_status", "toggle_valve"):
                    logging.warning("Unknown command: %r", command.get("action"))
                    continue
                status = _handle_command(command)
                response = json.dumps(status).encode("utf-8")
                conn.sendall(response)
    except OSError as e:
        logging.error("Web server error: %s", e)
    finally:
        server_socket.close()


def main() -> None:
    global _valve, _spi

    parser = argparse.ArgumentParser(
        description="Smart Irrigation System for Raspberry Pi"
    )
    parser.add_argument(
        "--moisture_threshold",
        type=int,
        default=DEFAULT_MOISTURE_THRESHOLD,
        help="Moisture threshold (0-1023) to trigger watering.",
    )
    parser.add_argument(
        "--web_port",
        type=int,
        default=DEFAULT_WEB_PORT,
        help="TCP port for the JSON-RPC web server.",
    )
    parser.add_argument(
        "--log_file",
        type=str,
        default=DEFAULT_LOG_FILE,
        help="Path to the log file.",
    )
    parser.add_argument(
        "--valve_pin",
        type=int,
        default=DEFAULT_VALVE_PIN,
        help="BCM GPIO pin for the solenoid valve.",
    )
    parser.add_argument(
        "--spi_channel",
        type=int,
        default=DEFAULT_SPI_CHANNEL,
        help="MCP3008 channel (0-7) for the soil moisture sensor.",
    )
    args = parser.parse_args()

    _setup_logging(args.log_file)
    logging.info("Starting Smart Irrigation System")
    logging.info(
        "Moisture threshold: %d, Web port: %d, Log file: %s, Valve pin: %d, SPI channel: %d",
        args.moisture_threshold,
        args.web_port,
        args.log_file,
        args.valve_pin,
        args.spi_channel,
    )

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _valve = OutputDevice(args.valve_pin, active_high=True, initial_value=False)
    except Exception as e:
        logging.error("Failed to initialise valve on GPIO %d: %s", args.valve_pin, e)
        sys.exit(1)

    try:
        _spi = spidev.SpiDev()
        _spi.open(0, args.spi_channel)
        _spi.max_speed_hz = 1_000_000
        _spi.mode = 0
    except OSError as e:
        logging.error("Failed to initialise SPI (bus 0, CE0, channel %d): %s",
                      args.spi_channel, e)
        _cleanup()
        sys.exit(1)

    try:
        _run_web_server(args.web_port)
    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        _cleanup()
        logging.info("Smart Irrigation System stopped.")


if __name__ == "__main__":
    main()

