import time
import signal
import sys
import smbus2
from gpiozero import OutputDevice
from gpiozero.pins.lgpio import LGPIOFactory

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
ADS1015_ADDR = 0x00
ADS1015_REG_CONFIG = 0x01
ADS1015_REG_CONVERSION = 0x00
ADS1015_CONFIG_OS_SINGLE = 0x8000
ADS1015_CONFIG_MUX_SINGLE_0 = 0x4000
ADS1015_CONFIG_PGA_4_096V = 0x0200
ADS1015_CONFIG_MODE_CONTINUOUS = 0x0000
ADS1015_CONFIG_DR_128SPS = 0x0080
ADS1015_CONFIG_CQUE_NONE = 0x0003

DIR_PIN = 20
STEP_PIN = 21
MS0_PIN = 14
MS1_PIN = 15

PWM_FREQ = 500

# --- Globals for cleanup -----------------------------------------------------
dir_pin = None
step_pin = None
ms0_pin = None
ms1_pin = None
pwm = None
i2c = None
running = True


def cleanup():
    global dir_pin, step_pin, ms0_pin, ms1_pin, pwm, i2c
    if pwm is not None:
        try:
            pwm.stop()
        except Exception:
            pass
    for pin in (dir_pin, step_pin, ms0_pin, ms1_pin):
        if pin is not None:
            try:
                pin.close()
            except Exception:
                pass
    if i2c is not None:
        try:
            i2c.close()
        except Exception:
            pass


def signal_handler(signum, frame):
    global running
    running = False


def init_driver():
    global dir_pin, step_pin, ms0_pin, ms1_pin
    try:
        dir_pin = OutputDevice(DIR_PIN)
        step_pin = OutputDevice(STEP_PIN)
        ms0_pin = OutputDevice(MS0_PIN)
        ms1_pin = OutputDevice(MS1_PIN)
        dir_pin.off()
        step_pin.off()
        ms0_pin.off()
        ms1_pin.off()
    except Exception as e:
        print(f"Failed to initialize GPIO driver: {e}")
        cleanup()
        sys.exit(1)


def init_i2c():
    global i2c
    try:
        i2c = smbus2.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Failed to initialize I2C bus {I2C_BUS}: {e}")
        cleanup()
        sys.exit(1)


def init_adc():
    try:
        i2c.write_word_data(ADS1015_ADDR, ADS1015_REG_CONFIG,
                            ADS1015_CONFIG_OS_SINGLE |
                            ADS1015_CONFIG_MUX_SINGLE_0 |
                            ADS1015_CONFIG_PGA_4_096V |
                            ADS1015_CONFIG_MODE_CONTINUOUS |
                            ADS1015_CONFIG_DR_128SPS |
                            ADS1015_CONFIG_CQUE_NONE)
    except Exception as e:
        print(f"Failed to configure ADS1015: {e}")
        cleanup()
        sys.exit(1)


def read_adc_raw(channel=0):
    if channel != 0:
        raise ValueError("Only channel 0 is supported by this driver")
    try:
        data = i2c.read_i2c_block_data(ADS1015_ADDR, ADS1015_REG_CONVERSION, 2)
        raw = (data[0] << 8) | data[1]
        if raw & 0x8000:
            raw -= 0x10000
        return raw
    except Exception as e:
        print(f"Error reading ADS1015: {e}")
        return None


def read_adc_voltage():
    raw = read_adc_raw()
    if raw is None:
        return None
    return raw * 4.096 / 32767.0


def set_pwm_duty(duty):
    if pwm is None:
        return
    duty = max(0, min(255, int(duty)))
    try:
        pwm.value = duty / 255.0
    except Exception as e:
        print(f"Error setting PWM duty cycle: {e}")


def read_accel_mag():
    try:
        data = i2c.read_i2c_block_data(0x3C, 0x00, 6)
        ax = (data[0] << 8) | data[1]
        ay = (data[2] << 8) | data[3]
        az = (data[4] << 8) | data[5]
        if ax & 0x8000:
            ax -= 0x10000
        if ay & 0x8000:
            ay -= 0x10000
        if az & 0x8000:
            az -= 0x10000
        return ax, ay, az
    except Exception as e:
        print(f"Error reading LSM303: {e}")
        return None, None, None


def read_heading():
    try:
        mag_x, mag_y, mag_z = i2c.read_i2c_block_data(0x3C, 0x06, 6)
        mx = (mag_x << 8) | mag_y
