    if channel != 0:
        raise ValueError("Only channel 0 is supported by this driver")
    try:
        data = i2c.read_i2c_block_data(ADS1015_ADDR, ADS1015_REG_CONVERSION, 2)
        raw = (data[0] << 8) | data[1]
        if raw & 0x8000:
            raw -= 0x10000
        return raw
    except Exception as e:
        print(f"Error reading ADS1015: {e}")
        return None


