import time
import logging
import argparse
import threading
import queue
import spidev
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.running = False
        self.debounce_time = 0.1
        self.last_event_time = 0
        self.lock = threading.Lock()
        self.event_detected = False

        if self.sensor_type == 'digital':
            if not isinstance(self.gpio_pins, list) or len(self.gpio_pins) != 1:
                raise ValueError("For digital sensors, exactly one GPIO pin must be specified.")
            try:
                GPIO.setmode(GPIO.BCM)
                GPIO.setup(self.gpio_pins[0], GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                logging.info(f"Digital sensor {self.sensor_id} configured on GPIO {self.gpio_pins[0]}")
            except Exception as e:
                logging.error(f"Failed to configure digital sensor {self.sensor_id}: {e}")
                raise
        elif self.sensor_type == 'analog':
            if self.channels is None or not isinstance(self.channels, int) or self.channels < 1 or self.channels > 7:
                raise ValueError("For analog sensors, a single channel (1-7) must be specified via the channels argument.")
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
                logging.info(f"Analog sensor {self.sensor_id} configured on SPI bus 0, device 0 at {self.spi_speed} Hz")
            except Exception as e:
                logging.error(f"Failed to configure analog sensor {self.sensor_id}: {e}")
                raise
        else:
            raise ValueError(f"Invalid sensor type: {self.sensor_type}")

    def read_sensor(self):
        try:
            if self.sensor_type == 'digital':
                with self.lock:
                    if GPIO.input(self.gpio_pins[0]) == GPIO.HIGH:
                        return True
            elif self.sensor_type == 'analog':
                adc_value = self.read_mcp3008(self.channels)
                if adc_value is not None and adc_value >= self.threshold:
                    return True
            return False
        except Exception as e:
            logging.error(f"Error reading sensor {self.sensor_id}: {e}")
            return False

    def read_mcp3008(self, channel):
        if self.spi is None:
            return None
        try:
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"Error reading MCP3008 channel {channel}: {e}")
            return None

    def debounce(self):
        time.sleep(self.debounce_time)

    def log_event(self):
        if self.log_queue:
            try:
                self.log_queue.put((self.sensor_id, "Event Detected"))
            except Exception as e:
                logging.error(f"Failed to put event into log queue: {e}")

    def run(self):
        self.running = True
        while self.running:
            try:
                if self.read_sensor():
                    current_time = time.time()
                    with self.lock:
                        if current_time - self.last_event_time > self.debounce_time:
                            self.last_event_time = current_time
                            self.event_detected = True
                    if self.event_detected:
                        self.log_event()
                        self.event_detected = False
                time.sleep(1 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error in sensor {self.sensor_id} thread: {e}")
                time.sleep(1)

    def stop(self):
        self.running = False
        if self.sensor_type == 'digital':
            try:
                GPIO.cleanup(self.gpio_pins[0])
                logging.info(f"GPIO {self.gpio_pins[0]} cleaned up for sensor {self.sensor_id}")
            except Exception as e:
                logging.error(f"Error cleaning up GPIO {self.gpio_pins[0]}: {e}")
        if self.spi:
            try:
                self.spi.close()
                logging.info(f"SPI closed for sensor {self.sensor_id}")
            except Exception as e:
                logging.error(f"Error closing SPI for sensor {self.sensor_id}: {e}")

def main():
    parser = argparse.ArgumentParser(description="Sound sensor monitoring system for Raspberry Pi.")
    parser.add_argument("--sensor_type", choices=['digital', 'analog'], required=True, help="Type of sound sensor (digital or analog).")
    parser.add_argument("--threshold", type=int, required=True, help="Sound level threshold (0-1023 for analog, 0/1 for digital).")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sampling rate in Hz.")
    parser.add_argument("--log_file", type=str, help="Path to the log file.")
    parser.add_argument("--gpio_pins", type=int, nargs='+', help="GPIO pins for digital sensors (BCM numbering).")
    parser.add_argument("--channels", type=int, help="MCP3008 channel for analog sensors (1-7).")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed for analog sensors in Hz.")
    parser.add_argument("--sensor_ids", type=str, nargs='+', help="Unique identifiers for each sensor.")

    args = parser.parse_args()

    log_queue = queue.Queue()
    sensors = []

    if args.sensor_type == 'digital':
        if not args.gpio_pins or len(args.gpio_pins) != 1:
            print("Error: Exactly one GPIO pin must be specified for digital sensors.")
            return
        sensors.append(SoundSensor(args.sensor_ids[0], 'digital', args.threshold, args.sample_rate, args.gpio_pins, [], args.spi_speed, log_queue))
    elif args.sensor_type == 'analog':
        if not args.channels:
            print("Error: A channel must be specified for analog sensors.")
            return
        sensors.append(SoundSensor(args.sensor_ids[0], 'analog', args.threshold, args.sample_rate, [], [args.channels], args.spi_speed, log_queue))
    else:
        print("Error: Invalid sensor type.")
        return

    threads = []
    for sensor in sensors:
        t = threading.Thread(target=sensor.run)
        t.daemon = True
        threads.append(t)
        t.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Exiting program.")
        for sensor in sensors:
            sensor.stop()
        for t in threads:
            t.join(timeout=2)
        if args.log_file:
            try:
                with open(args.log_file, 'a') as f:
                    while not log_queue.empty():
                        f.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - {msg}\n".format(**log_queue.get()))
            except Exception as e:
                logging.error(f"Error writing to log file: {e}")

if __name__ == "__main__":
    main()

