import json
import logging
import signal
import sys
import time

import numpy as np
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from tflite_runtime.interpreter import Interpreter
except ImportError:
    Interpreter = None

CONFIG_FILE = "config.json"

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

_running = True


def _signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False


def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}")
    return None


def initialize_camera():
    if Picamera2 is None:
        logging.error("picamera2 library not installed")
        return None
    try:
        cam = Picamera2()
        cam.configure(
            cam.create_preview_configuration(
                main={"size": (224, 224), "format": "RGB888"}
            )
        )
        cam.start()
        logging.info("Camera initialized successfully.")
        return cam
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None


def load_model(model_path):
    if Interpreter is None:
        logging.error("tflite_runtime library not installed")
        return None
    try:
        interpreter = Interpreter(model_path=model_path)
        interpreter.allocate_tensors()
        logging.info("Model loaded successfully.")
        return interpreter
    except Exception as e:
        logging.error(f"Error loading model: {e}")
        return None


def run_inference(interpreter, image):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        interpreter.set_tensor(input_details[0]["index"], image)
        interpreter.invoke()
        return interpreter.get_tensor(output_details[0]["index"])
    except Exception as e:
        logging.error(f"Inference error: {e}")
        return None


def indicate_bird(led_pin):
    try:
        led = OutputDevice(led_pin)
        led.on()
        time.sleep(1)
        led.off()
    except GPIOZeroError as e:
        logging.error(f"GPIO error controlling door: {e}")
    except Exception as e:
        logging.error(f"Unexpected error controlling door: {e}")


def process_frame(image, config, interpreter, led_pin, door_control):
    try:
        output = run_inference(interpreter, image)
        if output is None:
            return False
        bird_detected = float(output[0][0]) > 0.5
        if bird_detected:
            logging.info("Bird detected!")
            indicate_bird(led_pin)
            if door_control is not None:
                try:
                    door_control.on()
