import io
import time
import json
import signal
import sys
import threading
import queue
import logging
from threading import Condition

try:
    from picamera2 import Picamera2
    from picamera2.encoders import MJPEGEncoder
    from picamera2.outputs import FileOutput
except ImportError:
    logging.error("picamera2 library not found. Please install it.")
    sys.exit(1)

try:
    import RPi.GPIO as GPIO
except ImportError:
    logging.error("RPi.GPIO library not found. Please install it.")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DEFAULT_CONFIG = {
    "camera_resolution": "1280x720",
    "camera_framerate": 30,
    "max_queue_size": 10,
    "gpio_pin": 17,
    "led_activation_duration": 0.5,
    "motion_detection_threshold": 20,
    "config_file": "config.json"
}

class CameraApp:
    def __init__(self, config_file=DEFAULT_CONFIG["config_file"]):
        self.config_file = config_file
        self.config = self.load_config()
        self.camera = None
        self.frame_queue = queue.Queue(maxsize=self.config["max_queue_size"])
        self.running = True
        self.gpio_pin = self.config.get("gpio_pin", DEFAULT_CONFIG["gpio_pin"])
        self.led_activation_duration = self.config.get("led_activation_duration", DEFAULT_CONFIG["led_activation_duration"])
        self.motion_detection_threshold = self.config.get("motion_detection_threshold", DEFAULT_CONFIG["motion_detection_threshold"])
        self.previous_frame = None
        self.lock = threading.Lock()
        self.condition = threading.Condition(self.lock)
        self.initialize_gpio()

    def load_config(self):
        try:
            with open(self.config_file, "r") as f:
                config = json.load(f)
            required_keys = ["camera_resolution", "camera_framerate", "max_queue_size", "motion_detection_threshold"]
            for key in required_keys:
                if key not in config:
                    raise ValueError(f"Missing required config key: {key}")
            return config
        except FileNotFoundError:
            logging.warning(f"Config file not found: {self.config_file}. Using default configuration.")
            return DEFAULT_CONFIG.copy()
        except json.JSONDecodeError:
            logging.error(f"Error decoding JSON from {self.config_file}. Using default configuration.")
            return DEFAULT_CONFIG.copy()
        except ValueError as e:
            logging.error(f"Invalid configuration: {e}. Using default configuration.")
            return DEFAULT_CONFIG.copy()

    def initialize_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.OUT, initial=GPIO.LOW)
            logging.info(f"GPIO pin {self.gpio_pin} initialized for LED output.")
        except Exception as e:
            logging.error(f"Error initializing GPIO: {e}")
            raise

    def initialize_camera(self):
        try:
            self.camera = Picamera2()
            resolution = tuple(map(int, self.config["camera_resolution"].split("x")))
            framerate = self.config["camera_framerate"]
            video_config = self.camera.create_video_configuration(
                main={"size": resolution, "format": "RGB888"},
                controls={"FrameRate": framerate}
            )
            self.camera.configure(video_config)
            self.camera.start()
            time.sleep(2)  # Camera warm-up time
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            self.cleanup_gpio()
            raise

    def capture_frame(self):
        try:
            frame = self.camera.capture_array()
            return frame
        except Exception as e:
            logging.error(f"Error capturing frame: {e}")
            return None

    def encode_frame(self, frame):
        try:
            stream = io.BytesIO()
            from PIL import Image
            img = Image.fromarray(frame)
            img.save(stream, format="JPEG")
            stream.seek(0)
            return stream
        except Exception as e:
            logging.error(f"Error encoding frame: {e}")
            return None

    def process_frame(self, frame):
        try:
            if frame is None:
                return False
            if self.previous_frame is None:
                self.previous_frame = frame
                return False
            import numpy as np
            diff = np.abs(frame.astype(np.int16) - self.previous_frame.astype(np.int16))
            motion_detected = np.mean(diff) > self.motion_detection_threshold
            self.previous_frame = frame
            return motion_detected
        except Exception as e:
            logging.error(f"Error processing frame: {e}")
            return False

    def trigger_alert(self):
        try:
            GPIO.output(self.gpio_pin, GPIO.HIGH)
            time.sleep(self.led_activation_duration)
            GPIO.output(self.gpio_pin, GPIO.LOW)
            logging.info("LED alert triggered.")
        except Exception as e:
            logging.error(f"Error triggering LED alert: {e}")

    def run(self):
        try:
            self.initialize_camera()
            while self.running:
                frame = self.capture_frame()
                if frame is not None:
                    encoded_frame = self.encode_frame(frame)
                    if encoded_frame is not None:
                        try:
                            self.frame_queue.put(encoded_frame, block=False)
                        except queue.Full:
                            try:
                                self.frame_queue.get(block=False)
                            except queue.Empty:
                                pass
                        if self.process_frame(frame):
                            threading.Timer(0.5, self.trigger_alert).start()
                time.sleep(0.1)
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        logging.info("Cleaning up resources...")
        self.running = False
        if self.camera:
            try:
                self.camera.stop()
                self.camera.close()
            except Exception as e:
                logging.error(f"Error closing camera: {e}")
        self.cleanup_gpio()
        logging.info("Cleanup complete.")

    def cleanup_gpio(self):
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")

    def stop(self, signum=None, frame=None):
        logging.info("Stopping the application...")
        self.running = False

if __name__ == "__main__":
    app = CameraApp()
    signal.signal(signal.SIGINT, app.stop)
    signal.signal(signal.SIGTERM, app.stop)
    app.run()

