import cv2
import signal
import sys
import time
import os

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

CASCADE_PATH = "/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml"
CAMERA_INDEX = 0
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_FREQ = 50
SERVO_INCREMENT = 20
FRAME_WIDTH = 32

_running = True
_camera = None
_window = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def cleanup():
    global _camera, _window
    if _camera is not None:
        _camera.release()
        _camera = None
    if _window is not None:
        cv2.destroyWindow("Human Detection")
        _window = None
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def _init_gpio():
    if GPIO is None:
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(SERVO_PIN, GPIO.OUT)
        pwm = GPIO.PWM(SERVO_PIN, SERVO_FREQ)
        pwm.start(0)
        return pwm
    except Exception as e:
        print(f"GPIO init error: {e}", file=sys.stderr)
        return None


def _set_led(state):
    if GPIO is None:
        return
    try:
        GPIO.output(LED_PIN, GPIO.HIGH if state else GPIO.LOW)
    except Exception:
        pass


def _set_servo(angle):
    if GPIO is None:
        return
    try:
        angle = max(0, min(180, angle))
        pwm = _pwm if _pwm is not None else None
        if pwm is not None:
            pwm.ChangeDutyCycle((angle / 180.0) * 50)
        else:
            GPIO.output(SERVO_PIN, True if angle > 90 else False)
    except Exception:
        pass


def _detect_faces(frame, cascade):
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return cascade.detectMultiScale(gray, 1.3, 5)


def _process_frame(frame, cascade, pwm):
    faces = _detect_faces(frame, cascade)
    if len(faces) > 0:
        _set_led(True)
        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
            cx = x + w // 2
            if cx > FRAME_WIDTH:
                angle = min(180, pwm.angle + SERVO_INCREMENT)
            else:
                angle = max(0, pwm.angle - SERVO_INCREMENT)
            _set_servo(angle)
    else:
        _set_led(False)
    return frame


def main():
    global _camera, _window, _pwm

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not os.path.isfile(CASCADE_PATH):
        print(f"Error: cascade file not found at {CASCADE_PATH}", file=sys.stderr)
        sys.exit(0)

    cascade = cv2.CascadeClassifier(CASCADE_PATH)
    if cascade.empty():
        print("Error: failed to load cascade classifier", file=sys.stderr)
        sys.exit(0)

    _pwm = _init_gpio()
    pwm = _pwm if _pwm is not None else None

    _camera = cv2.VideoCapture(CAMERA_INDEX)
    if not _camera.isOpened():
        print("Error: cannot open camera at index 0", file=sys.stderr)
        cleanup()
        sys.exit(0)

    _window = cv2.namedWindow("Human Detection")

    try:
        while _running:
            ret, frame = _camera.read()
            if not ret:
                print("Error: failed to read frame from camera", file=sys.stderr)
                break

            processed = _process_frame(frame, cascade, pwm)
            cv2.imshow("Human Detection", processed)

            key = cv2.waitKey(1) & 0xFF
            if key == ord('q'):
                break
    except KeyboardInterrupt:
        pass
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

