import time
import random
import signal
import sys

try:
    import smbus2 as smbus
except ImportError:
    import smbus

try:
    from gpiozero import Buzzer
    from gpiozero.exc import GPIOZeroError
except ImportError:
    Buzzer = None
    GPIOZeroError = Exception

# --- Configuration -----------------------------------------------------------
BUZZER_PIN = 17
I2C_BUS = 1
AMG8833_ADDR = 0x70
POLL_INTERVAL = 0.1
BUZZER_DURATION = 1.0
HUMAN_TEMP_THRESHOLD = 30.0

# --- Globals for cleanup -----------------------------------------------------
buzzer = None
i2c_bus = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global running
    running = False


def init_buzzer():
    """Initialize the buzzer on GPIO17 (BCM)."""
    global buzzer
    if Buzzer is None:
        print("[WARN] gpiozero not available; buzzer disabled.")
        return None
    try:
        buzzer = Buzzer(BUZZER_PIN)
        print(f"[INFO] Buzzer initialized on GPIO{BUZZER_PIN} (BCM).")
    except GPIOZeroError as e:
        print(f"[ERROR] Failed to initialize buzzer on GPIO{BUZZER_PIN}: {e}")
        buzzer = None
    except Exception as e:
        print(f"[ERROR] Unexpected error initializing buzzer: {e}")
        buzzer = None


def init_i2c_bus():
    """Open the I2C bus and verify the AMG8833 is present."""
    global i2c_bus
    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
        # Probe the AMG8833 by reading the manufacturer ID register (0x00).
        try:
            i2c_bus.read_byte_data(AMG8833_ADDR, 0x00)
        except OSError:
            print(f"[ERROR] No device found at I2C address 0x{AMG8833_ADDR:02X} on bus {I2C_BUS}.")
            i2c_bus = None
            return None
        print(f"[INFO] I2C bus {I2C_BUS} opened; AMG8833 detected at 0x{AMG8833_ADDR:02X}.")
    except OSError as e:
        print(f"[ERROR] Cannot open I2C bus {I2C_BUS}: {e}")
        i2c_bus = None
    except Exception as e:
        print(f"[ERROR] Unexpected error opening I2C bus: {e}")
        i2c_bus = None


def read_amg8833_thermal_data():
    """Read the 8×8 temperature matrix from the AMG8833.

    Returns:
        list[list[float]] | None: 8×8 matrix of temperatures in °C, or None on error.
    """
    if i2c_bus is None:
        return None
    try:
        # AMG8833 returns 64 bytes starting at register 0x80 (thermal data).
        data = i2c_bus.read_i2c_block_data(AMG8833_ADDR, 0x80, 64)
        if len(data) != 64:
            print("[WARN] Unexpected data length from AMG8833.")
            return None
        pixels = []
        for i in range(0, 64, 2):
            raw = data[i] | (data[i + 1] << 8)
            # Convert to signed 12-bit value (0.25 °C LSB).
            if raw & 0x0800:
                raw -= 0x1000
            temp = raw * 0.25
            pixels.append(temp)
        return [pixels[i * 8:(i + 1) * 8] for i in range(8)]
    except OSError as e:
        print(f"[ERROR] I2C read error from AMG8833: {e}")
        return None
    except Exception as e:
        print(f"[ERROR] Unexpected error reading AMG8833: {e}")
        return None


def detect_human(thermal_data):
    """Return True if any pixel exceeds the human-temperature threshold."""
    if thermal_data is None:
        return False
    for row in thermal_data:
        for temp in row:
            if temp > HUMAN_TEMP_THRESHOLD:
                return True
    return False


def trigger_alert(buzzer_obj):
    """Sound the buzzer for BUZZER_DURATION seconds."""
    if buzzer_obj is None:
        print("[WARN] Buzzer not available; skipping alert.")
        return
    try:
        buzzer_obj.on()
        time.sleep(BUZZER_DURATION)
        buzzer_obj.off()
    except GPIOZeroError as e:
        print(f"[ERROR] Failed to control buzzer: {e}")
    except Exception as e:
        print(f"[ERROR] Unexpected error controlling buzzer: {e}")


def simulate_thermal_data():
    """Generate random 8×8 thermal data in the plausible range 20–45 °C."""
    return [[random.uniform(20.0, 45.0) for _ in range(8)] for _ in range(8)]


def cleanup():
    """Release all resources cleanly."""
    global buzzer, i2c_bus
    if buzzer is not None:
        try:
            buzzer.off()
            buzzer.close()
        except Exception:
            pass
        buzzer = None
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass
        i2c_bus = None
    print("[INFO] Resources released. Exiting.")


def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_buzzer()
    init_i2c_bus()

    print("[INFO] Starting thermal monitoring loop. Press Ctrl+C to stop.")

    try:
        while running:
            thermal_data = read_amg8833_thermal_data()
            if thermal_data is not None:
                human_detected = detect_human(thermal_data)
                if human_detected:
                    print(f"[ALERT] Human detected! Temperature: {HUMAN_TEMP_THRESHOLD:.1f} °C or higher.")
                    trigger_alert(buzzer)
            else:
                print("[WARN] Sensor read failed; simulating thermal data.")
                thermal_data = simulate_thermal_data()

            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"[ERROR] Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

