import RPi.GPIO as GPIO

# Constants
CAMERA_RESOLUTION = (160, 120)
CAMERA_FRAMERATE = 16
CAMERA_FLIP = 1
SEGMENT_THRESHOLD_1 = 20
SEGMENT_THRESHOLD_2 = 20
MORPH_KERNEL = np.ones((3, 3), np.uint8)
MIN_RED_AREA = 10
SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQ = 50
SERVO_CENTER = 7.0
SERVO_RANGE = 12.0 - 7.0
SEARCH_ANGLE = 0.0
ANGLE_INCREMENT = 0.1
PWM_SERVO_1 = None
PWM_SERVO_2 = None
ARDUINO = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def segment_red(img):
    hsv = cv2.cvtColor(img, cv2.COLOR_BGR2HSV)
    mask1 = cv2.inRange(hsv, np.array([160, 160, 10]), np.array([190, 255, 255]))
    ycr = cv2.cvtColor(img, cv2.COLOR_BGR2YCrCb)
    mask2 = cv2.inRange(ycr, np.array([0, 165, 0]), np.array([255, 255, 255]))
    mask = mask1 | mask2
    mask = cv2.erode(mask, MORPH_KERNEL)
    mask = cv2.dilate(mask, MORPH_KERNEL)
