#!/usr/bin/env python3

import os
import sys
import time
import signal
import logging
import configparser
import datetime
from pathlib import Path

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from gpiozero import DigitalInputDevice
except ImportError:
    DigitalInputDevice = None

# Global state for cleanup
running = True
picam2 = None
pir = None

DEFAULT_CONFIG = {
    'storage_directory': '/home/pi/storage',
    'disk_space_threshold_mb': '100',
    'log_file': 'motion_detection.log',
    'camera_resolution_width': '640',
    'camera_resolution_height': '480',
    'image_quality': '85',
    'video_bitrate': '64',
    'video_framerate': '20',
    'log_level': 'INFO',
    'pir_gpio_pin': '4',
}

def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def setup_logging(log_file):
    log_dir = os.path.dirname(os.path.abspath(log_file))
    try:
        os.makedirs(log_dir, exist_ok=True)
        handler = logging.FileHandler(log_file)
    except (PermissionError, OSError):
        handler = logging.StreamHandler(sys.stderr)
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[handler],
    )
    logging.info("Logging initialized.")

def load_config(config_file):
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        logging.warning(f"Config file {config_file} not found. Creating with defaults.")
        for section, defaults in DEFAULT_CONFIG.items():
            config[section] = defaults
        try:
            with open(config_file, 'w') as f:
                config.write(f)
        except OSError as e:
            logging.error(f"Failed to write default config: {e}")
    config.read(config_file)
    return config

def get_config(config, section, option, cast=None):
    try:
        if cast is None:
            return config.get(section, option)
        return cast(config.get(section, option))
    except (configparser.NoSectionError, configparser.NoOptionError, ValueError) as e:
        logging.error(f"Config error in {section}.{option}: {e}. Using default.")
        return DEFAULT_CONFIG[option]

def ensure_storage_dir(storage_dir):
    try:
        os.makedirs(storage_dir, exist_ok=True)
    except OSError as e:
        logging.error(f"Cannot create storage directory {storage_dir}: {e}")
        return False
    return True

def get_storage_path(storage_dir):
    today = datetime.date.today()
    return os.path.join(storage_dir, today.strftime('%Y'), today.strftime('%m'), today.strftime('%d'))

def get_free_disk_space(storage_dir):
    try:
        statvfs = os.statvfs(storage_dir)
        return statvfs.f_bavail * statvfs.f_frsize
    except OSError as e:
        logging.error(f"Error getting disk space: {e}")
        return 0

def cleanup_disk_space(storage_dir, threshold_mb):
    storage_path = get_storage_path(storage_dir)
    if not os.path.isdir(storage_path):
        return
    try:
        files = sorted(
            (os.path.join(storage_path, f) for f in os.listdir(storage_path)),
            key=os.path.getmtime,
        )
    except OSError as e:
        logging.error(f"Cannot list directory {storage_path}: {e}")
        return
    total_size = sum(os.path.getsize(f) for f in files if os.path.isfile(f))
    logging.info(f"Disk space low: {total_size / (1024 * 1024):.1f} MB free, threshold {threshold_mb} MB.")
    while total_size > threshold_mb * 1024 * 1024 and files:
        file_path = files.pop(0)
        try:
            os.remove(file_path)
            total_size -= os.path.getsize(file_path)
            logging.info(f"Deleted old file: {file_path}")
        except OSError as e:
            logging.error(f"Failed to delete {file_path}: {e}")
            break
    logging.info(f"Disk space recovered: {total_size / (1024 * 1024):.1f} MB free.")

def init_camera(resolution_width, resolution_height):
    global picam2
    if Picamera2 is None:
        logging.warning("picamera2 not installed. Continuing in degraded mode.")
        return None
    try:
        picam2 = Picamera2()
        config = picam2.create_still_configuration(
            main={"size": (resolution_width, resolution_height)},
            lores={"size": (resolution_width, resolution_height)},
            display=None,
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(2)
        logging.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logging.warning(f"Camera init failed: {e}. Continuing in degraded mode.")
        picam2 = None
        return None

def capture_image(picam2, storage_dir, quality):
    if picam2 is None:
        logging.warning("Camera unavailable, skipping image capture.")
        return None
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(storage_dir, f"{timestamp}_image.jpg")
        picam2.capture_file(filename, format="jpeg", quality=quality)
        logging.info(f"Captured image: {filename}")
        return filename
    except Exception as e:
        logging.error(f"Image capture failed: {e}")
        return None

def capture_video(picam2, storage_dir, framerate, bitrate):
    if picam2 is None:
        logging.warning("Camera unavailable, skipping video capture.")
        return None
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(storage_dir, f"{timestamp}_video.h264")
        config = picam2.create_video_configuration(
            main={"size": (640, 480)},
            lores={"size": (320, 240)},
            encode="lores",
        )
        picam2.configure(config)
        picam2.start_recording(
            filename,
            codec="h264",
            quality=bitrate,
            framerate=framerate,
        )
        time.sleep(5)
        picam2.stop_recording()
        logging.info(f"Captured video: {filename}")
        return filename
    except Exception as e:
        logging.error(f"Video capture failed: {e}")
        return None

def setup_pir(pin):
    global pir
    if DigitalInputDevice is None:
        logging.warning("gpiozero not installed. PIR disabled.")
        return None
    try:
        pir = DigitalInputDevice(pin, pull_up=False, bounce_time=0.1)
        logging.info(f"PIR sensor initialized on GPIO {pin}.")
        return pir
    except Exception as e:
        logging.error(f"PIR setup failed: {e}")
        pir = None
        return None

def cleanup(signum=None, frame=None):
    global running, picam2, pir
    running = False
    if picam2 is not None:
        try:
            picam2.stop()
            picam2.close()
        except Exception:
            pass
    if pir is not None:
        try:
            pir.close()
        except Exception:
            pass
    logging.info("Cleanup complete.")
    sys.exit(0)

def main():
    global running
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    setup_logging("motion_detection.log")
    config = load_config("config.ini")
    storage_dir = get_config(config, 'storage_directory', 'storage_directory')
    threshold_mb = get_config(config, 'storage_directory', 'disk_space_threshold_mb', int)
    log_file = get_config(config, 'storage_directory', 'log_file', str)
    resolution_width = get_config(config, 'camera_resolution_width', 'camera_resolution_width', int)
    resolution_height = get_config(config, 'camera_resolution_height', 'camera_resolution_height', int)
    quality = get_config(config, 'image_quality', 'image_quality', int)
    framerate = get_config(config, 'video_framerate', 'video_framerate', int)
    bitrate = get_config(config, 'video_bitrate', 'video_bitrate', int)
    pir_pin = get_config(config, 'pir_gpio_pin', 'pir_gpio_pin', int)
    if not ensure_storage_dir(storage_dir):
        logging.error("Cannot create storage directory. Exiting.")
        sys.exit(1)
    logging.info("Motion detection system started.")
    pir_sensor = setup_pir(pir_pin)
    if pir_sensor is None:
        logging.warning("PIR sensor unavailable. Entering polling mode.")
    camera = init_camera(resolution_width, resolution_height)
    if camera is None:
        logging.warning("Camera unavailable. Entering polling mode.")
    try:
        while running:
            if pir_sensor is not None:
                if pir_sensor.value:
                    logging.info("Motion detected!")
                    storage_path = get_storage_path(storage_dir)
                    if not os.path.isdir(storage_path):
                        os.makedirs(storage_path, exist_ok=True)
                    cleanup_disk_space(storage_dir, threshold_mb)
                    for i in range(3):
                        if not running:
                            break
                        image = capture_image(camera, storage_path, quality)
                        if not running:
                            break
                        time.sleep(0.5)
                    if running:
                        video = capture_video(camera, storage_path, framerate, bitrate)
            else:
                time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

