def capture_image(picam2, storage_dir, quality):
    if picam2 is None:
        logging.warning("Camera unavailable, skipping image capture.")
        return None
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(storage_dir, f"{timestamp}_image.jpg")
        picam2.capture_file(filename, format="jpeg", quality=quality)
        logging.info(f"Captured image: {filename}")
        return filename
    except Exception as e:
        logging.error(f"Image capture failed: {e}")
        return None

def capture_video(picam2, storage_dir, framerate, bitrate):
    if picam2 is None:
        logging.warning("Camera unavailable, skipping video capture.")
        return None
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(storage_dir, f"{timestamp}_video.h264")
        config = picam2.create_video_configuration(
            main={"size": (640, 480)},
            lores={"size": (320, 240)},
            encode="lores",
        )
        picam2.configure(config)
        picam2.start_recording(
            filename,
            codec="h264",
            quality=bitrate,
            framerate=framerate,
        )
        time.sleep(5)
        picam2.stop_recording()
        logging.info(f"Captured video: {filename}")
        return filename
    except Exception as e:
        logging.error(f"Video capture failed: {e}")
        return None

def setup_pir(pin):
    global pir
    if DigitalInputDevice is None:
        logging.warning("gpiozero not installed. PIR disabled.")
        return None
    try:
        pir = DigitalInputDevice(pin, pull_up=False, bounce_time=0.1)
        logging.info(f"PIR sensor initialized on GPIO {pin}.")
        return pir
    except Exception as e:
        logging.error(f"PIR setup failed: {e}")
        pir = None
        return None

def cleanup(signum=None, frame=None):
    global running, picam2, pir
    running = False
    if picam2 is not None:
        try:
            picam2.stop()
            picam2.close()
        except Exception:
            pass
    if pir is not None:
        try:
            pir.close()
        except Exception:
            pass
    logging.info("Cleanup complete.")
    sys.exit(0)

def main():
    global running
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    setup_logging("motion_detection.log")
    config = load_config("config.ini")
    storage_dir = get_config(config, 'storage_directory', 'storage_directory')
    threshold_mb = get_config(config, 'storage_directory', 'disk_space_threshold_mb', int)
    log_file = get_config(config, 'storage_directory', 'log_file', str)
    resolution_width = get_config(config, 'camera_resolution_width', 'camera_resolution_width', int)
    resolution_height = get_config(config, 'camera_resolution_height', 'camera_resolution_height', int)
    quality = get_config(config, 'image_quality', 'image_quality', int)
    framerate = get_config(config, 'video_framerate', 'video_framerate', int)
    bitrate = get_config(config, 'video_bitrate', 'video_bitrate', int)
    pir_pin = get_config(config, 'pir_gpio_pin', 'pir_gpio_pin', int)
    if not ensure_storage_dir(storage_dir):
        logging.error("Cannot create storage directory. Exiting.")
        sys.exit(1)
    logging.info("Motion detection system started.")
    pir_sensor = setup_pir(pir_pin)
    if pir_sensor is None:
        logging.warning("PIR sensor unavailable. Entering polling mode.")
    camera = init_camera(resolution_width, resolution_height)
    if camera is None:
        logging.warning("Camera unavailable. Entering polling mode.")
    try:
