import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

# Constants
CAMERA_INDEX = 0
ROI_SIZE = 10
MIN_CONTOUR_AREA = 500
SERIAL_TIMEOUT = 1

# Global state
cap = None
serial_port = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global cap, serial_port
    if cap is not None and cap.isOpened():
        cap.release()
    if serial_port is not None and serial_port.is_open:
        try:
            serial_port.close()
        except Exception:
            pass
    cv2.destroyAllWindows()


def initialize_camera(camera_index=0):
    try:
        cap = cv2.VideoCapture(camera_index)
        if not cap.isOpened():
            print(f"Error: Could not open camera at index {camera_index}.")
            return None
        return cap
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None


def initialize_serial():
    available_ports = [p.device for p in serial.tools.list_ports.comports()]
    preferred_port = "/dev/ttyACM0"
    if preferred_port in available_ports:
        try:
            ser = serial.Serial(preferred_port, 9600, timeout=SERIAL_TIMEOUT)
            print(f"Serial port {preferred_port} opened at 9600 baud.")
            return ser
        except serial.SerialException as e:
            print(f"Error opening preferred serial port {preferred_port}: {e}")
    else:
        print(f"Warning: Preferred serial port {preferred_port} not found.")

    if available_ports:
        first_port = available_ports[0]
        try:
            ser = serial.Serial(first_port, 9600, timeout=SERIAL_TIMEOUT)
            print(f"Serial port {first_port} opened at 9600 baud (fallback).")
            return ser
        except serial.SerialException as e:
            print(f"Error opening fallback serial port {first_port}: {e}")
    else:
        print("Warning: No serial ports detected.")

    return None


def get_ball_position(ball_x, ball_y, center_x, center_y):
    if abs(ball_x - center_x) > 50 and abs(ball_y - center_y) > 50:
        return "5"
    elif ball_x > center_x and ball_y > center_y:
        return "1"
    elif ball_x > center_x and ball_y < center_y:
        return "2"
    elif ball_x < center_x and ball_y > center_y:
        return "3"
    elif ball_x < center_x and ball_y < center_y:
        return "4"
    else:
        return "5"


def process_frame(frame, min_hsv, max_hsv):
    h, w, _ = frame.shape
    cx = w // 2
    cy = h // 2
    x1 = max(cx - ROI_SIZE // 2, 0)
    x2 = min(cx + ROI_SIZE // 2, w)
    y1 = max(cy - ROI_SIZE // 2, 0)
    y2 = min(cy + ROI_SIZE // 2, h)
    roi = frame[y1:y2, x1:x2]

    hsv = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
    mask = cv2.inRange(hsv, np.array(min_hsv), np.array(max_hsv))
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    ball_x = cx
    ball_y = cy

    for contour in contours:
        area = cv2.contourArea(contour)
        if area > MIN_CONTOUR_AREA:
            x, y, bw, bh = cv2.boundingRect(contour)
            cv2.rectangle(frame, (x, y), (x + bw, y + bh), (255, 0, 0), 2)
            ball_x = x + bw // 2
            ball_y = y + bh // 2

    return ball_x, ball_y, frame


def main():
    global cap, serial_port, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cap = initialize_camera()
    if cap is None:
        cleanup()
        sys.exit(1)

    serial_port = initialize_serial()

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break

            ball_x, ball_y, frame = process_frame(frame, (0, 0, 0), (255, 255, 255))

            cv2.imshow("Frame", frame)
            key = cv2.waitKey(1) & 0xFF

            if key == ord('s'):
                hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
                min_hsv = np.array([hsv[:, :, 0].min(), hsv[:, :, 1].min(), hsv[:, :, 2].min()])
                max_hsv = np.array([hsv[:, :, 0].max(), hsv[:, :, 1].max(), hsv[:, :, 2].max()])
                print(f"Min HSV: {min_hsv}, Max HSV: {max_hsv}")

            if key == ord('o'):
                tracking_enabled = not tracking_enabled

            if tracking_enabled:
                pos = get_ball_position(ball_x, ball_y, w // 2, h // 2)
                print(f"Position: {pos}")
                if serial_port is not None and serial_port.is_open:
                    try:
                        serial_port.write(pos.encode('utf-8'))
                    except serial.SerialException as e:
                        print(f"Error writing to serial port: {e}")

            if key == 27:
                break

    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

