import cv2
import numpy as np
import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

# Constants
CAMERA_WIDTH = 640
CAMERA_HEIGHT = 480
CENTER_X = CAMERA_WIDTH // 2
CENTER_Y = CAMERA_HEIGHT // 2
MIN_RADIUS = 10
RESIZE_WIDTH = 250
RESIZE_HEIGHT = 188
SCALE_FACTOR = 1.5
MIN_PATCH_SIZE = int(MIN_RADIUS * SCALE_FACTOR)
HAAR_CASCADE_PATH = "haarcascade_eye.xml"
PTZ_PIN_AZIMUTH = 7
PTZ_PIN_ELEVATION = 13
PTZ_FREQUENCY = 50
INITIAL_DUTY_CYCLE = 7.0
SERVO_DELAY = 0.02
SERVO_STOP_DELAY = 0.1
FONT = cv2.FONT_HERSHEY_SIMPLEX
FONT_SCALE = 0.5
FONT_COLOR = (255, 255, 255)
LINE_THICKNESS = 2
OBJECT_CLOSE_THRESHOLD = 100
OBJECT_FAR_THRESHOLD = 250
OBJECT_NOT_FOUND_THRESHOLD = 10

# Global variables
arduino = None
servo_azimuth = None
servo_elevation = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

def cleanup():
    global arduino, servo_azimuth, servo_elevation
    if arduino is not None and arduino.is_open:
        try:
            arduino.close()
        except Exception:
            pass
    if servo_azimuth is not None:
        try:
            servo_azimuth.stop()
        except Exception:
            pass
    if servo_elevation is not None:
        try:
            servo_elevation.stop()
        except Exception:
            pass
    cv2.destroyAllWindows()

def send_command(command):
    if arduino is None or not arduino.is_open:
        print("Arduino not initialized or closed.")
        return
    try:
        arduino.write(command.encode())
    except Exception as e:
        print(f"Error sending command: {e}")

def initialize_camera():
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera.")
        return None
    return cap

def initialize_arduino():
    try:
        ser = serial.Serial('/dev/ttyACM0', 115200, timeout=1)
        time.sleep(2)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing Arduino: {e}")
        return None

def initialize_face_detector():
    try:
        cascade_path = cv2.data.haarcascades + HAAR_CASCADE_PATH
        face_cascade = cv2.CascadeClassifier(cascade_path)
        if face_cascade.empty():
            print("Error: Could not load haarcascade_eye.xml.")
            return None
        return face_cascade
    except Exception as e:
        print(f"Error initializing face detector: {e}")
        return None

def initialize_servo_motors():
    global servo_azimuth, servo_elevation
    try:
        GPIO.setmode(GPIO.BOARD)
        GPIO.setup(PTZ_PIN_AZIMUTH, GPIO.OUT)
        GPIO.setup(PTZ_PIN_ELEVATION, GPIO.OUT)
        servo_azimuth = GPIO.PWM(PTZ_PIN_AZIMUTH, PTZ_FREQUENCY)
        servo_elevation = GPIO.PWM(PTZ_PIN_ELEVATION, PTZ_FREQUENCY)
        servo_azimuth.start(INITIAL_DUTY_CYCLE)
        servo_elevation.start(INITIAL_DUTY_CYCLE)
        return True
    except Exception as e:
        print(f"Error initializing servo motors: {e}")
        return False

def segment_red_object(frame):
    hsv_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask_1 = cv2.inRange(hsv_roi, np.array([160, 160, 10]), np.array([190, 255, 255]))
    ycr_roi = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    mask_2 = cv2.inRange(ycr_roi, np.array([0, 165, 0]), np.array([255, 255, 255]))
    mask = mask_1 | mask_2
    mask = cv2.erode(mask, np.ones((3, 3), np.uint8))
    mask = cv2.dilate(mask, np.ones((8, 8), np.uint8))
    return mask

def detect_largest_blob(mask):
    contours, _ = cv2.findContours(mask, cv2.RETR_CCOMP, cv2.CHAIN_APPROX_SIMPLE)
    largest_contour = (0, 0, 2, 2)
    largest_area = 0
    for contour in contours:
        area = cv2.contourArea(contour)
        if area > largest_area:
            largest_area = area
            largest_contour = cv2.boundingRect(contour)
    return largest_contour, largest_area

def calculate_center(x, y, w, h):
    return x + w // 2, y + h // 2

def calculate_distance(x1, y1, x2, y2):
    return np.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

def calculate_angle(x1, y1, x2, y2):
    return np.arctan2(y2 - y1, x2 - x1) * 180 / np.pi

def control_servo_motors(center_x, center_y):
    if center_x < 0:
        angle = -calculate_angle(CENTER_X, CENTER_Y, center_x, 0)
    elif center_x > CAMERA_WIDTH:
        angle = calculate_angle(CENTER_X, CENTER_Y, CAMERA_WIDTH, 0)
    else:
        angle = 0
    servo_azimuth.ChangeDutyCycle(np.clip(angle + 90, 0, 180) / 180 * 10)
    servo_elevation.ChangeDutyCycle(np.clip(center_y / CAMERA_HEIGHT * 100, 0, 100))

def process_frame(frame, face_cascade):
    resized_frame = cv2.resize(frame, (RESIZE_WIDTH, RESIZE_HEIGHT))
    gray = cv2.cvtColor(resized_frame, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, 1.3, 5)
    largest_contour, largest_area = detect_largest_blob(segment_red_object(resized_frame))
    if largest_area > OBJECT_NOT_FOUND_THRESHOLD:
        x, y, w, h = largest_contour
        center_x = x + w // 2
        center_y = y + h // 2
        distance = calculate_distance(CENTER_X, CENTER_Y, center_x, center_y)
        angle = calculate_angle(CENTER_X, CENTER_Y, center_x, center_y)
        if distance < OBJECT_CLOSE_THRESHOLD:
            send_command('c')
            control_servo_motors(center_x, center_y)
        elif distance > OBJECT_FAR_THRESHOLD:
            send_command('f')
            control_servo_motors(center_x, center_y)
        else:
            if angle > -15 and angle < 15:
                send_command('g')
            elif angle < -15:
                send_command('b')
            elif angle > 15:
                send_command('a')
            control_servo_motors(center_x, center_y)
        cv2.rectangle(resized_frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
        cv2.putText(resized_frame, 'Target', (x, y - 10), FONT, FONT_SCALE, FONT_COLOR, LINE_THICKNESS)
    else:
        send_command('h')
    return resized_frame

def main():
    global arduino, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    cap = initialize_camera()
    if cap is None:
        return
    arduino = initialize_arduino()
    if arduino is None:
        cap.release()
        return
    face_cascade = initialize_face_detector()
    if face_cascade is None:
        cap.release()
        return
    if not initialize_servo_motors():
        cap.release()
        return
    elevation_duty_cycle = INITIAL_DUTY_CYCLE
    sweeping = False
    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame.")
                break
            processed_frame = process_frame(frame, face_cascade)
            cv2.imshow("Frame", processed_frame)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
            if largest_area > OBJECT_NOT_FOUND_THRESHOLD:
                if not sweeping:
                    if abs(center_y - CENTER_Y) > 10:
                        sweeping = True
                        elevation_duty_cycle += 0.1
                        if elevation_duty_cycle > 12.0:
                            elevation_duty_cycle = INITIAL_DUTY_CYCLE
                            sweeping = False
                            send_command('h')
                else:
                    sweeping = False
            else:
                if sweeping:
                    elevation_duty_cycle = INITIAL_DUTY_CYCLE
                    sweeping = False
                    send_command('h')
    except Exception as e:
        print(f"Error in main loop: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

