import cv2
import face_recognition
import time
import os
import signal
import sys
from datetime import datetime

# --- Configuration ---
BUTTON_PIN = 23
DATASET_DIR = "Dataset"
TOLERANCE = 0.6
DEBOUNCE_DELAY = 0.2

# --- Globals for cleanup ---
cap = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

def cleanup():
    global cap
    if cap is not None and cap.isOpened():
        cap.release()
    cv2.destroyAllWindows()

def load_known_faces(dataset_dir):
    known_encodings = []
    known_names = []
    if not os.path.isdir(dataset_dir):
        print(f"Error: Dataset directory '{dataset_dir}' not found.")
        return None, None
    try:
        for filename in os.listdir(dataset_dir):
            if filename.lower().endswith((".jpg", ".jpeg", ".png")):
                image_path = os.path.join(dataset_dir, filename)
                try:
                    image = face_recognition.load_image_file(image_path)
                    encodings = face_recognition.face_encodings(image)
                    if encodings:
                        known_encodings.append(encodings[0])
                        known_names.append(os.path.splitext(filename)[0])
                    else:
                        print(f"Warning: No face found in {filename}, skipping.")
                except Exception as e:
                    print(f"Warning: Error processing {filename}: {e}")
    except Exception as e:
        print(f"Error loading faces from dataset: {e}")
        return None, None
    return known_encodings, known_names

def recognize_faces(frame, known_encodings, known_names, tolerance):
    rgb_frame = frame[:, :, ::-1]
    face_locations = face_recognition.face_locations(rgb_frame)
    face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)
    names = []
    for face_encoding in face_encodings:
        matches = face_recognition.compare_faces(known_encodings, face_encoding, tolerance=tolerance)
        name = "Unknown"
        if True in matches:
            matched_idxs = [i for (i, b) in enumerate(matches) if b]
            counts = {}
            for i in matched_idxs:
                label = known_names[i]
                counts[label] = counts.get(label, 0) + 1
            name = max(counts, key=counts.get)
        names.append(name)
    return list(zip(face_locations, names))

def main():
    global cap, running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera.")
        cleanup()
        sys.exit(1)

    known_encodings, known_names = load_known_faces(DATASET_DIR)
    if known_encodings is None or known_names is None:
        cleanup()
        sys.exit(1)

    last_logged = {}
    last_logged_time = 0.0
    print("Face recognition running. Press 'q' to quit.")

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break

            face_locations_and_names = recognize_faces(frame, known_encodings, known_names, TOLERANCE)

            for (top, right, bottom, left), name in face_locations_and_names:
                cv2.rectangle(frame, (left, top), (right, bottom), (0, 255, 0), 2)
                cv2.rectangle(frame, (left, bottom - 35), (right, bottom), (0, 255, 0), cv2.FILLED)
                cv2.putText(frame, name, (left + 6, bottom - 6), cv2.FONT_HERSHEY_DUPLEX, 0.8, (255, 255, 255), 1)

                current_time = time.time()
                if name != "Unknown":
                    if name not in last_logged or (current_time - last_logged_time) > 5:
                        print(f"{name} was here")
                        last_logged[name] = current_time
                        last_logged_time = current_time

            cv2.imshow("Video", frame)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    except Exception as e:
        print(f"Error during face recognition: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

