import time
import logging
import json
import signal
import sys
import os

try:
    import RPi.GPIO as GPIO
except Exception:
    GPIO = None

DEFAULT_CONFIG = {
    "trigger_pins": [17, 22, 24],
    "echo_pins": [18, 23, 25],
    "offsets": [0.0, 0.0, 0.0],
    "max_distances": [200.0, 200.0, 200.0],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True
_config = None
_gpio_ready = False


def load_config(config_file="config.json"):
    global _config
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
        merged = dict(DEFAULT_CONFIG)
        merged.update(cfg)
        _config = merged
        logging.info("Configuration loaded from %s", config_file)
    except FileNotFoundError:
        logging.warning("Config file not found; using defaults.")
        _config = dict(DEFAULT_CONFIG)
    except json.JSONDecodeError as e:
        logging.error("Invalid JSON in config file: %s; using defaults.", e)
        _config = dict(DEFAULT_CONFIG)
    except Exception as e:
        logging.error("Unexpected error loading config: %s; using defaults.", e)
        _config = dict(DEFAULT_CONFIG)


def setup_logging(log_file):
    try:
        logging.basicConfig(
            filename=log_file,
            level=logging.INFO,
            format="%(asctime)s - %(levelname)s - %(message)s",
        )
    except Exception as e:
        print(f"Failed to set up logging: {e}", file=sys.stderr)


def initialize_gpio(trigger_pins, echo_pins):
    global _gpio_ready
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in mock mode.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in trigger_pins + echo_pins:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        _gpio_ready = True
        logging.info("GPIO initialized successfully.")
        return True
    except Exception as e:
        logging.error("GPIO initialization failed: %s", e)
        _gpio_ready = False
        return False


def read_distance(trigger_pin, echo_pin):
    if not _gpio_ready:
        return None
    try:
        GPIO.output(trigger_pin, GPIO.LOW)
        time.sleep(0.000002)
        GPIO.output(trigger_pin, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, GPIO.LOW)

        timeout_start = time.time()
        while GPIO.input(echo_pin) == GPIO.LOW:
            if time.time() - timeout_start > 0.05:
                logging.warning("Echo timeout on trigger %d", trigger_pin)
                return None

        pulse_start = time.time()
        while GPIO.input(echo_pin) == GPIO.HIGH:
            if time.time() - pulse_start > 0.05:
                logging.warning("Echo pulse too long on trigger %d", trigger_pin)
                return None

        pulse_end = time.time()
        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150
        distance = round(distance, 2)
        return distance
    except Exception as e:
        logging.error("Error reading distance on trigger %d: %s", trigger_pin, e)
        return None


def get_water_level(distances):
    if not distances:
        return None
    distances = [d + offset for d, offset in zip(distances, _config["offsets"])]
    distances = [min(d, _config["max_distances"][i]) for i, d in enumerate(distances)]
    distances.sort()
    return distances[1]


def check_alerts(water_level, alert_low, alert_high):
    if water_level is None:
        return
    if water_level < alert_low:
        logging.warning("Water level LOW: %.2f cm", water_level)
    elif water_level > alert_high:
        logging.warning("Water level HIGH: %.2f cm", water_level)


def signal_handler(signum, frame):
    global _running
    _running = False


def cleanup():
    global _gpio_ready
    if _gpio_ready:
        try:
            GPIO.cleanup()
            _gpio_ready = False
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error("Error during GPIO cleanup: %s", e)


def main():
    global _running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    load_config()
    setup_logging(_config["log_file"])

    trigger_pins = _config["trigger_pins"]
    echo_pins = _config["echo_pins"]

    if not initialize_gpio(trigger_pins, echo_pins):
        logging.warning("Running in mock mode (GPIO unavailable).")

    last_alert_time = 0.0
    error_counts = [0] * len(trigger_pins)

    try:
        while _running:
            distances = []
            for i, (trig, ech) in enumerate(zip(trigger_pins, echo_pins)):
                dist = read_distance(trig, ech)
                if dist is None:
                    error_counts[i] += 1
                    if error_counts[i] >= 5:
                        logging.warning("Excluding sensor %d after 5 consecutive errors.", i + 1)
                        continue
                distances.append(dist)

            water_level = get_water_level(distances)

            if water_level is not None:
                check_alerts(water_level, _config["alert_threshold_low"], _config["alert_threshold_high"])
                logging.info("Water level: %.2f cm", water_level)
            else:
                logging.warning("No valid sensor readings.")

            for i, count in enumerate(error_counts):
                if count >= 5:
                    logging.warning("Sensor %d has been excluded.", i + 1)
                else:
                    error_counts[i] = 0

            time.sleep(5)
    except Exception as e:
        logging.error("Unexpected error in main loop: %s", e)
    finally:
        cleanup()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

