import signal
import logging
import random
import threading
import datetime
import subprocess
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    try:
        from gpiozero import OutputDevice
        from gpiozero.exc import GPIOZeroError
    except ImportError:
        OutputDevice = None
        GPIOZeroError = Exception

try:
    import board
    import adafruit_dht
except ImportError:
    board = None
    adafruit_dht = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    import speech_recognition as sr
except ImportError:
    speech_recognition = None

# Configuration
DHT_PIN = 4
LIGHT_RELAY_PIN = 17
WAKE_WORD = "Greenhouse"
LISTENING_TIMEOUT = 5
TEMPERATURE_MIN = 15
TEMPERATURE_MAX = 35
IMAGE_QUALITY = 64

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Global state
lights_on = False
dht_device = None
camera = None
running = True

# GPIO simulation fallback
_simulated_gpio = False
_simulated_output = None


def _simulate_gpio(pin, active_high=True, initial_value=False):
    global _simulated_gpio
    if _simulated_gpio:
        return
    _simulated_gpio = True
    if active_high:
        _simulated_output = OutputDevice(pin, active_high=True, initial_value=initial_value)
    else:
        _simulated_output = OutputDevice(pin, active_high=False, initial_value=initial_value)


def _cleanup_gpio():
    global _simulated_output
    if _simulated_output is not None:
        try:
            _simulated_output.close()
        except Exception:
            pass
        _simulated_output = None
    _simulated_gpio = False


def initialize_gpio():
    global _simulated_output
    if OutputDevice is None:
        _simulate_gpio(LIGHT_RELAY_PIN, active_high=True, initial_value=False)
        return
    try:
        return OutputDevice(LIGHT_RELAY_PIN, active_high=True, initial_value=False)
    except GPIOZeroError as e:
        logger.error(f"GPIO initialization failed: {e}. Simulating GPIO.")
        _simulate_gpio(LIGHT_RELAY_PIN, active_high=True, initial_value=False)
        return
    except Exception as e:
        logger.error(f"Unexpected GPIO initialization error: {e}. Simulating GPIO.")
        _simulate_gpio(LIGHT_RELAY_PIN, active_high=True, initial_value=False)


def read_temperature():
    global dht_device
    if adafruit_dht is None or board is None:
        return simulate_temperature()
    if dht_device is None:
        dht_device = adafruit_dht.DHT11(board.D4)
    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
        except RuntimeError as e:
            logger.warning(f"DHT11 read error (attempt {attempt + 1}/3): {e}")
        except Exception as e:
            logger.error(f"DHT11 unexpected error (attempt {attempt + 1}/3): {e}")
        time.sleep(2)
    logger.error("DHT11 read failed after 3 attempts. Simulating temperature.")
    return simulate_temperature()


def simulate_temperature():
    return random.uniform(TEMPERATURE_MIN, TEMPERATURE_MAX)


def take_picture():
    global camera
    if camera is None:
        logger.error("Camera not available.")
        return
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture_file(filename)
        logger.info(f"Picture saved as {filename}")
    except Exception as e:
        logger.error(f"Error taking picture: {e}")


def control_lights(command):
    global lights_on
    if command == "turn on the lights":
        if not lights_on:
            try:
                if OutputDevice is not None:
                    _simulated_output.on()
                lights_on = True
                logger.info("Lights turned on.")
            except Exception as e:
                logger.error(f"Error turning lights on: {e}")
    elif command == "turn off the lights":
        if lights_on:
            try:
                if OutputDevice is not None:
                    _simulated_output.off()
                lights_on = False
                logger.info("Lights turned off.")
            except Exception as e:
                logger.error(f"Error turning lights off: {e}")
    else:
        logger.warning(f"Invalid lights command: {command}")


def process_audio_data(audio_data):
    try:
        recognizer = sr.Recognizer()
        audio_data = audio_data.replace("b'", '').replace("'", '')
        audio_data = audio_data.replace(" ", "+").replace("\n", "")
        audio_data = audio_data.replace("b''", '')
        try:
            audio_data = bytes.fromhex(audio_data)
        except ValueError:
            logger.error("Invalid base64 audio data.")
            return
        audio_data = recognizer.record(recognizer.AudioSource.DEFAULT, duration=len(audio_data) / 16000)
        words = recognizer.recognize_google(audio_data)
        logger.info(f"Recognized speech: {words}")
        return words.lower()
    except sr.UnknownValueError:
        logger.warning("Google Web Speech API could not understand audio")
        return None
    except sr.RequestError as e:
        logger.error(f"Could not request results from Google Web Speech API; {e}")
        return None
    except Exception as e:
        logger.error(f"An unexpected error occurred during speech recognition: {e}")
        return None


def listen_for_command():
    global running
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            logger.info("Listening for wake word...")
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            audio = recognizer.listen(source, timeout=LISTENING_TIMEOUT, phrase_time_limit=3)
    except sr.WaitTimeoutError:
        logger.warning("Listening timed out.")
        return
    except Exception as e:
        logger.error(f"Microphone error: {e}")
        return
    try:
        words = process_audio_data(audio)
        if words is None:
            return
        if WAKE_WORD in words:
            logger.info(f"Wake word detected: {words}")
            command = process_command(words)
            if command:
                control_lights(command)
                take_picture()
    except Exception as e:
        logger.error(f"Error processing audio: {e}")


def process_command(words):
    if "what is the temperature":
        temperature = read_temperature()
        logger.info(f"Temperature: {temperature:.2f} C")
        return None
    elif "turn on the lights":
        control_lights("turn on the lights")
        return None
    elif "turn off the lights":
        control_lights("turn off the lights")
        return None
    elif "take a picture":
        take_picture()
        return None
    else:
        logger.warning(f"Unknown command: {words}")
        return None


def signal_handler(sig, frame):
    global running
    logger.info("Received signal, shutting down...")
    running = False


def main():
    global camera, dht_device
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()
    try:
        if Picamera2 is not None:
            camera = Picamera2()
            camera.configure(camera.create_still_configuration())
            camera.start()
            logger.info("Camera initialized.")
        else:
            logger.warning("picamera2 not available. Image capture disabled.")
    except Exception as e:
        logger.error(f"Error initializing camera: {e}")
        camera = None

    try:
        while running:
            listen_for_command()
            time.sleep(0.1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        logger.info("Cleaning up resources...")
        _cleanup_gpio()
        if camera is not None:
            try:
                camera.stop()
            except Exception:
                pass
        if dht_device is not None:
            try:
                dht_device.exit()
            except Exception:
                pass
        logger.info("Program terminated.")


if __name__ == "__main__":
    main()

