POLL_INTERVAL = 0.05

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        for pin in (PIN_INPUT_1, PIN_INPUT_2, PIN_INPUT_3, PIN_OUTPUT_1, PIN_OUTPUT_2):
            GPIO.setup(pin, GPIO.IN if pin in (PIN_INPUT_1, PIN_INPUT_2, PIN_INPUT_3) else GPIO.OUT, pull_up_down=GPIO.PUD_UP)

        state = False
        gpio_24_toggled = False

        while _running:
            try:
                val1 = GPIO.input(PIN_INPUT_1)
                val2 = GPIO.input(PIN_INPUT_2)
                val3 = GPIO.input(PIN_INPUT_3)
            except Exception as e:
                print(f"Error reading GPIO: {e}", file=sys.stderr)
                break

            if val1 == GPIO.LOW:
                GPIO.output(PIN_OUTPUT_1, GPIO.HIGH if not state else GPIO.LOW)
                state = not state
            else:
                GPIO.output(PIN_OUTPUT_1, GPIO.LOW)

            if val2 == GPIO.LOW:
                GPIO.output(PIN_OUTPUT_1, GPIO.LOW)
            else:
                GPIO.output(PIN_OUTPUT_1, GPIO.LOW)

            if val3 == GPIO.LOW:
                if gpio_24_toggled:
                    GPIO.output(PIN_OUTPUT_2, GPIO.LOW if GPIO.input(PIN_OUTPUT_2) == GPIO.HIGH else GPIO.HIGH)
                else:
                    GPIO.output(PIN_OUTPUT_2, GPIO.HIGH if GPIO.input(PIN_OUTPUT_2) == GPIO.LOW else GPIO.LOW)
                gpio_24_toggled = not gpio_24_toggled
            else:
                GPIO.output(PIN_OUTPUT_2, GPIO.LOW)

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"GPIO initialization or runtime error: {e}", file=sys.stderr)
    finally:
        _cleanup()

if __name__ == "__main__":
    main()

