import RPi.GPIO as GPIO
import time
import datetime
import signal
import sys
import threading

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

IR_SENSOR_PIN = 17
LOG_FILE = "intrusion_log.txt"

_running = True
_lock = threading.Lock()

def log_error(message):
    print(f"Error: {message}", file=sys.stderr)

def log_intrusion(message):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - {message}"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(log_entry + "\n")
    except IOError as e:
        log_error(f"Failed to write to log file: {e}")

def capture_image():
    if Picamera2 is None:
        log_error("picamera2 library not available.")
        return None
    try:
        picam2 = Picamera2()
        config = picam2.create_still_configuration(
            main={"format": "XRGB8888", "size": (64, 64)}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(0.5)
        buffer = picam2.capture_array()
        picam2.stop()
        picam2.close()
        return buffer
    except Exception as e:
        log_error(f"Failed to capture image: {e}")
        return None

def ir_callback(channel):
    time.sleep(0.2)
    if GPIO.input(IR_SENSOR_PIN) == GPIO.LOW:
        image_data = capture_image()
        if image_data is not None:
            filename = f"intrusion_{datetime.datetime.now().strftime('%Y%m%d%H%M%S')}.jpg"
            try:
                with open(filename, "wb") as f:
                    f.write(image_data.tobytes())
            except IOError as e:
                log_error(f"Failed to save image: {e}")
        log_intrusion("Intrusion detected")

def signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(IR_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.add_event_detect(IR_SENSOR_PIN, GPIO.FALLING, callback=ir_callback, bouncetime=200)
    except Exception as e:
        log_error(f"Failed to initialize GPIO: {e}")
        return

    try:
        while _running:
