import subprocess
import threading
import time
from threading import Condition, Thread, Lock

import zmq
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

try:
    from gps3 import gps3
except ImportError:
    gps3 = None

DEFAULT_LAT = "22.483425"
DEFAULT_LON = "88.455463"

shutdown_event = threading.Event()

gps_lock = Lock()
gps_data = {
    "latitude": None,
    "longitude": None,
    "magnetic_field": None,
    "altitude": None,
}

def restart_gpsd():
    try:
        subprocess.run(
            ["sudo", "systemctl", "restart", "gpsd"],
            check=True,
            timeout=10,
        )
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, FileNotFoundError) as e:
        print(f"gpsd restart failed: {e}")

def set_default_coordinates():
    global gps_data
    gps_data["latitude"] = DEFAULT_LAT
    gps_data["longitude"] = DEFAULT_LON

def gps_data_thread():
    if gps3 is None:
        print("gps3 module not available; using default coordinates.")
        set_default_coordinates()
        return

    try:
        gps_socket = gps3.GPSDSocket()
        data_stream = gps3.DataStream()
        gps_socket.connect()
        gps_socket.watch()
    except Exception as e:
        print(f"Failed to connect to gpsd: {e}")
        set_default_coordinates()
        return

    try:
        for new_data in gps_socket:
            if shutdown_event.is_set():
                break
            if new_data:
                data_stream.unpack(new_data)
                lat = data_stream.TPV.get("lat")
                lon = data_stream.TPV.get("lon")
                mag = data_stream.TPV.get("mag")
                alt = data_stream.TPV.get("alt")

                if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
                    with gps_lock:
                        gps_data["latitude"] = lat
                        gps_data["longitude"] = lon
                        gps_data["magnetic_field"] = mag
                        gps_data["altitude"] = alt
                else:
                    print("Invalid GPS data format.")
            time.sleep(0.5)
    except Exception as e:
        print(f"Error in GPS data thread: {e}")
    finally:
        try:
            gps_socket.close()
        except Exception:
            pass

def camera_thread(zmq_socket):
    picam2 = None
    try:
        picam2 = Picamera2()
        video_config = picam2.create_video_configuration(
            main={"size": (640, 480), "format": "MJPEG"},
            controls={"FrameRate": 100},
            transform="hflip",
        )
        picam2.configure(video_config)
        picam2.camera_config["transform"] = "vflip"
        output = Output()
        encoder = MJPEGEncoder()
        picam2.start_recording(encoder, output)
        print("Camera started recording.")

        while not shutdown_event.is_set():
            try:
                frame = output.get_array()
                if frame is not None:
                    lat = gps_data["latitude"]
                    lon = gps_data["longitude"]
                    mag = gps_data["magnetic_field"]
                    alt = gps_data["altitude"]

                    if lat is not None and lon is not None:
                        message = f"{lat},{lon},{mag},{alt}"
                    else:
                        message = "0,0,0,0"

                    zmq_socket.send_string(message, zmq.SNDMORE)
                    zmq_socket.send(frame, zmq.NOBLOCK)
            except zmq.ZMQError as e:
                print(f"ZMQError in camera thread: {e}")
                break
            except Exception as e:
                print(f"Error processing frame: {e}")
                break
    except Exception as e:
        print(f"Error initializing or using camera: {e}")
    finally:
        if picam2 is not None:
            try:
                picam2.stop_recording()
            except Exception:
                pass
            try:
                picam2.close()
            except Exception:
                pass
        print("Camera recording stopped.")

def main():
    context = None
    footage_socket = None
    try:
        context = zmq.Context()
        footage_socket = context.socket(zmq.PUB)
        footage_socket.setsockopt(zmq.LINGER, 0)
        footage_socket.bind("tcp://*:5555")
        print("ZMQ socket bound to port 5555.")

        gps_thread = Thread(target=gps_data_thread, daemon=True)
        camera_thread(footage_socket)

        gps_thread.start()
        camera_thread(footage_socket)

        while not shutdown_event.is_set():
            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
        shutdown_event.set()
    except Exception as e:
        print(f"An error occurred: {e}")
        shutdown_event.set()
    finally:
        shutdown_event.set()
        if footage_socket is not None:
            try:
                footage_socket.close()
            except Exception:
                pass
        if context is not None:
            try:
                context.term()
            except Exception:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

