import cv2
import face_recognition
import time
import json
import logging
import signal
import sys
import os

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    logging.error("gpiozero is required. Install with: pip install gpiozero")
    sys.exit(1)

DEFAULT_CONFIG = {
    "camera_width": 640,
    "camera_height": 480,
    "motion_threshold": 500,
    "face_recognition_confidence_threshold": 0.6,
    "relay_gpio_pin": 17,
    "relay_on_duration": 5,
    "debounce_interval": 2,
    "log_level": "INFO",
}

running = True
relay = None

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False

def load_config(config_file="config.json"):
    config = DEFAULT_CONFIG.copy()
    try:
        with open(config_file, "r") as f:
            user_config = json.load(f)
        config.update(user_config)
        logging.info(f"Configuration loaded from {config_file}")
    except FileNotFoundError:
        logging.warning(f"Config file {config_file} not found. Using defaults.")
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding config file: {e}. Using defaults.")
    except Exception as e:
        logging.error(f"Unexpected error loading config: {e}. Using defaults.")
    return config

def initialize_camera(config):
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, config["camera_width"])
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, config["camera_height"])
        cap.set(cv2.CAP_PROP_FPS, 10)
        logging.info("Camera initialized successfully.")
        return cap
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None

def process_frame(frame, config, encodings, last_relay_activation):
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    gray = cv2.GaussianBlur(gray, (21, 21), 0)

    if last_relay_activation is not None:
        time_since_last = time.time() - last_relay_activation
        if time_since_last < config["debounce_interval"]:
            logging.info("Debounce active, skipping relay activation.")
            return last_relay_activation, encodings

    if config.get("relay_gpio_pin", 17) is not None:
        try:
            relay.on()
            logging.info("Relay activated.")
            time.sleep(config["relay_on_duration"])
            relay.off()
            logging.info("Relay deactivated.")
        except GPIOZeroError as e:
            logging.error(f"Error controlling relay: {e}")
        except Exception as e:
            logging.error(f"Unexpected error controlling relay: {e}")
        last_relay_activation = time.time()
        return last_relay_activation, encodings

    return last_relay_activation, encodings

def recognize_face(frame, config, encodings):
    try:
        rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        face_locations = face_recognition.face_locations(rgb_frame)
        face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)

        for face_encoding in face_encodings:
            matches = face_recognition.compare_faces(list(encodings.values()), face_encoding)
            face_distances = face_recognition.face_distance(list(encodings.values()), face_encoding)
            best_match_index = int(np.argmin(face_distances))
            if matches[best_match_index] and face_distances[best_match_index] <= config["face_recognition_confidence_threshold"]:
                name = list(encodings.keys())[best_match_index]
                logging.info(f"Face recognized: {name}")
                return name
            else:
                logging.info("Face unrecognized.")
    except Exception as e:
        logging.error(f"Error during face recognition: {e}")

def main():
    global relay, running

    config = load_config()
    logging.basicConfig(
        level=getattr(logging, config.get("log_level", "INFO").upper(), logging.INFO),
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        relay = OutputDevice(config.get("relay_gpio_pin", 17), active_high=True, initial_value=False)
        logging.info(f"Relay initialized on GPIO{config.get('relay_gpio_pin', 17)} (active_high=True).")
    except GPIOZeroError as e:
        logging.error(f"Error initializing relay on GPIO{config.get('relay_gpio_pin', 17)}: {e}")
        sys.exit(1)
    except Exception as e:
        logging.error(f"Unexpected error initializing relay: {e}")
        sys.exit(1)

    cap = initialize_camera(config)
    if cap is None:
        logging.error("Camera initialization failed. Exiting.")
        if relay:
            relay.close()
        sys.exit(1)

    encodings = {}
    try:
        with open("encodings.json", "r") as f:
            encodings = json.load(f)
        if not encodings:
            logging.warning("encodings.json is empty. Starting with empty encodings.")
    except FileNotFoundError:
        logging.warning("encodings.json not found. Starting with empty encodings.")
    except json.JSONDecodeError:
        logging.error("Error decoding encodings.json. Starting with empty encodings.")
    except Exception as e:
        logging.error(f"Unexpected error loading encodings.json: {e}. Starting with empty encodings.")

    last_relay_activation = None

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                logging.error("Failed to capture frame. Retrying...")
                time.sleep(0.1)
                continue

            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            gray = cv2.GaussianBlur(gray, (21, 21), 0)

            if cv2.countNonZero(cv2.absdiff(gray, cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR))) > config["motion_threshold"]:
                logging.info("Motion detected.")
                last_relay_activation, encodings = process_frame(frame, config, encodings, last_relay_activation)
                recognize_face(frame, config, encodings)

            time.sleep(1.0 / 10.0)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        if cap is not None:
            cap.release()
        if relay is not None:
            relay.close()
        logging.info("Resources released. Exiting.")

if __name__ == "__main__":
    main()

