import cv2
import select
import sys
import time
import signal
import threading
import numpy as np
import config
import face
import mixer

try:
    from gpiozero import OutputDevice, Button
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

DOOR_PIN = 18
BUTTON_PIN = 17

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_sound(path):
    try:
        return mixer.Sound(path)
    except Exception as e:
        print(f"Error loading sound file {path}: {e}")
        return None

def play_sound(sound):
    if sound is None:
        return
    try:
        mixer.play(sound)
    except Exception as e:
        print(f"Error playing sound: {e}")

def is_letter_input(letter):
    try:
        rlist, _, _ = select.select([sys.stdin], [], [], 0.0)
        if rlist:
            input_char = sys.stdin.read(1)
            return input_char.lower() == letter.lower()
        return False
    except Exception:
        return False

def recognize_face(image):
    try:
        gray_image = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
        face_coords = face.detect_single(gray_image)
        if face_coords is None:
            return None, None
        x, y, w, h = face_coords
        cropped_face = face.crop(gray_image, x, y, w, h)
        resized_face = face.resize(cropped_face)
        label, confidence = face.recognize(resized_face)
        return label, confidence
    except Exception as e:
        print(f"Error during face recognition: {e}")
        return None, None

def control_door(door, button, sound_player, welcome_sound, wait_sound, later_sound):
    global running
    try:
        if button.is_active:
            print("Button pressed, looking for face...")
            image = camera.read()
            if image is None:
                print("Error: Could not read image from camera.")
                return
            label, confidence = recognize_face(image)
            if label is None:
                print("Could not recognize face!")
                play_sound(later_sound)
                return
            print(f"Recognized face with confidence: {confidence}")
            if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                print("Recognized face! Unlocking Door...")
                door.on()
                play_sound(welcome_sound)
            else:
                print("Did not recognize face!")
                play_sound(wait_sound)
    except Exception as e:
        print(f"Error controlling door: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise RuntimeError("Could not open camera.")
    except Exception as e:
        print(f"Error initializing camera: {e}")
        sys.exit(1)

    try:
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
    except Exception as e:
        print(f"Error loading training data: {e}")
        sys.exit(1)

    try:
        door = OutputDevice(DOOR_PIN, active_high=True, initial_value=False)
        button = Button(BUTTON_PIN, pull_up=True)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

    welcome_sound = load_sound(config.WELCOME_SOUND_FILE)
    wait_sound = load_sound(config.WAIT_SOUND_FILE)
    later_sound = load_sound(config.LATER_SOUND_FILE)

    try:
        mixer.init()
    except Exception as e:
        print(f"Error initializing mixer: {e}")
        sys.exit(1)

    print("Running Door Controller...")
    print("Press button to trigger face recognition.")
    print("Press Ctrl+C to exit.")

    try:
        while running:
            if is_letter_input('d'):
                door.off()
                print("Door locked.")
            elif is_letter_input('u'):
                door.on()
                print("Door unlocked.")
            elif is_letter_input('q'):
                break
            control_door(door, button, None, welcome_sound, wait_sound, later_sound)
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        print("Cleaning up...")
        try:
            mixer.stop()
        except Exception:
            pass
        try:
            camera.release()
        except Exception:
            pass
        try:
            door.close()
        except Exception:
            pass
        try:
            button.close()
        except Exception:
            pass
        print("Exiting.")

if __name__ == "__main__":
    main()

