import time
import threading
import signal
import sys
import psutil
from luma.core.interface.serial import i2c
from luma.lcd.device import ssd1306
from PIL import ImageDraw, ImageFont

# LED pin assignments (BCM numbering)
LED_PINS = [17, 18, 23, 27, 22]

# LCD I2C configuration
I2C_PORT = 1
LCD_COLUMNS = 16
LCD_ROWS = 2
LCD_CHAR_WIDTH = 8
LCD_CHAR_HEIGHT = 16

# Global state
lcd = None
led_states = [False] * 5
stop_event = threading.Event()

# Font for the LCD
FONT = ImageFont.load_default()


def init_lcd():
    """Initialize the I2C LCD device; return the device object or None on failure."""
    try:
        serial = i2c(port=I2C_PORT, address=0x3C)  # Common HD44780 address
        return ssd1306(serial, width=LCD_COLUMNS, height=LCD_ROWS)
    except Exception as e:
        print(f"Error initializing LCD on I2C bus {I2C_PORT}: {e}", file=sys.stderr)
        return None


def init_leds():
    """Initialize GPIO pins for LEDs; return True on success, False on failure."""
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in LED_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        return False


def read_cpu_stats():
    """Read CPU usage and temperature; return (usage, temp) or (None, None) on error."""
    try:
        usage = psutil.cpu_percent(interval=None)
        temp = psutil.sensors_temperatures()['cpu_thermal'][0].current
        return usage, temp
    except Exception as e:
        print(f"Error reading CPU stats: {e}", file=sys.stderr)
        return None, None


def update_lcd(device, usage, temp):
    """Update the LCD with CPU usage and temperature; handle I2C errors."""
    if device is None:
        return
    try:
        image = ImageDraw.Draw(device.image)
        image.text((0, 0), f"CPU: {usage:5.1f}%", font=FONT, fill="white")
        image.text((0, 16), f"Temp: {temp:5.1f}C", font=FONT, fill="white")
        device.display()
    except Exception as e:
        print(f"Error updating LCD: {e}", file=sys.stderr)


def activate_led(index):
    """Turn on the specified LED for 1 second, then turn it off."""
    if 0 <= index < len(led_states):
        led_states[index] = True
        print(f"LED {index} activated")
        time.sleep(1)
        led_states[index] = False
        print(f"LED {index} deactivated")


def lcd_update_loop(device):
    """Background thread: read CPU stats and update LCD every 1 second."""
    while not stop_event.is_set():
        usage, temp = read_cpu_stats()
        if usage is not None and temp is not None:
            update_lcd(device, usage, temp)
        else:
            print("Skipping LCD update due to read error", file=sys.stderr)
        stop_event.wait(1.0)


def clear_lcd(device):
    """Clear the LCD display."""
    if device is None:
        return
    try:
        device.clear()
        device.display()
    except Exception as e:
        print(f"Error clearing LCD: {e}", file=sys.stderr)


def cleanup(signum=None, frame=None):
    """Graceful shutdown: stop threads, clear LCD, release GPIO."""
    print("\nShutting down...")
    stop_event.set()
    time.sleep(0.2)  # Allow threads to notice the stop event

    clear_lcd(lcd)

    if lcd is not None:
        try:
            lcd.cleanup()
        except Exception:
            pass

    if init_leds():
        try:
            import RPi.GPIO as GPIO
            GPIO.cleanup()
        except Exception:
            pass

    sys.exit(0)


def main():
    global lcd

    # Register signal handler for Ctrl+C
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize LCD
    lcd = init_lcd()
    if lcd is None:
        print("Failed to initialize LCD. Exiting.", file=sys.stderr)
        sys.exit(1)

    # Initialize LEDs
    if not init_leds():
        print("Failed to initialize GPIO. Exiting.", file=sys.stderr)
        cleanup()

    # Start LCD update thread
    lcd_thread = threading.Thread(target=lcd_update_loop, args=(lcd,), daemon=True)
    lcd_thread.start()

    # Main loop: activate LEDs based on user input
    try:
        while True:
            try:
                cls = int(input("Enter class index (0-4): "))
                if 0 <= cls < len(led_states):
                    activate_led(cls)
                else:
                    print("Invalid class index. Must be between 0 and 4.")
            except ValueError:
                print("Invalid input. Please enter an integer.")
            except EOFError:
                print("\nEnd of input.")
                break
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

