import smbus
import time
import signal
import sys

# Constants
I2C_BUS = 1
THERMAL_ZONE_FILE = '/sys/class/thermal/thermal_zone0/temp'

# Global reference for cleanup
_i2c_bus = None

def cleanup(signum=None, frame=None):
    """Release the I2C bus on exit or signal."""
    global _i2c_bus
    if _i2c_bus is not None:
        try:
            _i2c_bus.close()
        except Exception:
            pass
        _i2c_bus = None
    if signum is not None:
        sys.exit(0)

def get_temperature():
    """Read the CPU temperature from the thermal zone file."""
    try:
        with open(THERMAL_ZONE_FILE, 'r') as f:
            raw = f.read().strip()
            return float(raw) / 1000.0
    except FileNotFoundError:
        print(f"Error: Thermal zone file not found: {THERMAL_ZONE_FILE}")
        return None
    except PermissionError:
        print(f"Error: Permission denied reading thermal zone file: {THERMAL_ZONE_FILE}")
        return None
    except (IOError, OSError) as e:
        print(f"Error reading temperature: {e}")
        return None

def main():
    global _i2c_bus
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize I2C bus (only for bus checks; no display writes)
    try:
        _i2c_bus = smbus.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied opening I2C bus {I2C_BUS}. Run as root or add user to 'i2c' group.")
        sys.exit(1)
    except OSError as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        while True:
            temp_c = get_temperature()
            if temp_c is not None:
                print(f"CPU Temperature: {temp_c:.1f}°C")
            time.sleep(2)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

