from adafruit_tsl2561 import TSL2561
from adafruit_ssd1306 import SSD1306_I2C

# Global resources for cleanup
_i2c = None
_oled = None
_running = True


def _cleanup():
    """Clear the OLED and release I2C resources."""
    global _oled, _i2c
    if _oled is not None:
        try:
            _oled.fill(0)
            _oled.show()
        except Exception:
            pass
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
    _i2c = None
    _oled = None


def _handle_sigint(signum, frame):
    """SIGINT handler for graceful shutdown."""
    global _running
    _running = False


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    global _i2c
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
        return True
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return False


def initialize_oled(i2c_bus):
    """Initialize the SSD1306 OLED display."""
    global _oled
    try:
        _oled = SSD1306_I2C(128, 64, i2c_bus)
        _oled.fill(0)
        _oled.show()
        return True
    except Exception as e:
        print(f"Error initializing OLED display: {e}", file=sys.stderr)
        return False


def initialize_bme280(i2c_bus):
    """Initialize the BME280 sensor."""
    try:
        sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=0x76)
        return sensor
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}", file=sys.stderr)
        return None


def initialize_tsl2561(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        sensor = TSL2561(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}", file=sys.stderr)
        return None


def read_sensor_data(bme280_sensor, tsl2561_sensor):
    """Read temperature, humidity, pressure, and light level."""
    temperature = None
    humidity = None
    pressure = None
    light_level = None

    if bme280_sensor is not None:
        try:
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity
            pressure = bme280_sensor.pressure
        except Exception as e:
            print(f"Error reading BME280 data: {e}", file=sys.stderr)

    if tsl2561_sensor is not None:
        try:
            light_level = tsl2561_sensor.lux
        except Exception as e:
            print(f"Error reading TSL2561 data: {e}", file=sys.stderr)

    return temperature, humidity, pressure, light_level


def display_data(oled_display, temperature, humidity, pressure, light_level):
    """Display sensor data on the OLED screen."""
    oled_display.fill(0)
    if temperature is not None:
        oled_display.text("Temp: {} C".format(temperature), 0, 0, 1)
    if humidity is not None:
        oled_display.text("Humidity: {} %".format(humidity), 0, 16, 1)
    if pressure is not None:
        oled_display.text("Pressure: {} hPa".format(pressure), 0, 32, 1)
    if light_level is not None:
        oled_display.text("Light: {} lux".format(light_level), 0, 48, 1)
    oled_display.show()


def main():
    """Main function to read sensor data and display it on the OLED screen."""
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    if not initialize_i2c():
        _cleanup()
        sys.exit(1)

    if not initialize_oled(_i2c):
        _cleanup()
        sys.exit(1)

    bme280_sensor = initialize_bme280(_i2c)
    tsl2561_sensor = initialize_tsl2561(_i2c)

    try:
