log = logging.getLogger("adc_oled")

ADC_CHANNELS = [0, 1, 2, 3]
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 50000
I2C_PORT = 1
I2C_ADDR = 0x3C
UPDATE_INTERVAL_S = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def init_spi():
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED_HZ
        spi.mode = 0
        log.info("SPI bus %d device %d opened at %d Hz.", SPI_BUS, SPI_DEVICE, SPI_SPEED_HZ)
        return spi
    except Exception as exc:
        log.error("Failed to initialise SPI: %s", exc)
        return None


def init_oled():
    try:
        serial = i2c(port=I2C_PORT, address=I2C_ADDR)
        device = ssd1306(serial)
        log.info("SSD1306 OLED initialised on I2C bus %d addr 0x%02X.", I2C_PORT, I2C_ADDR)
        return device
    except Exception as exc:
        log.error("Failed to initialise OLED: %s", exc)
        return None


