    if not 0 <= channel <= 3:
        raise ValueError(f"Invalid ADC channel {channel}; must be 0-3.")
    if spi is None:
        raise RuntimeError("SPI device is not initialised.")
    try:
        cmd = 0x01 << 3 | (channel & 0x07)
        tx = [0x01, cmd, 0x00]
        rx = spi.xfer2(tx)
        return ((rx[1] & 0x03) << 8) | rx[2]
    except Exception as exc:
        log.error("SPI read error on channel %d: %s", channel, exc)
        raise


def adc_to_voltage(raw, vref=3.3):
    if raw is None:
        return None
    return (raw / 1023.0) * vref


def update_display(device, voltages):
    if device is None:
        return
    try:
        with canvas(device) as draw:
            for i, v in enumerate(voltages):
                if v is None:
                    text = f"CH{i+1}: --V"
                else:
                    text = f"CH{i+1}: {v:.2f}V"
                draw.text((0, i * 10), text, fill="white")
    except Exception as exc:
        log.error("OLED update error: %s", exc)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

