    if spi is None:
        log.error("Cannot continue without SPI.")
        sys.exit(1)

    device = init_oled()
    if device is None:
        log.error("Cannot continue without OLED.")
        try:
            spi.close()
        except Exception:
            pass
        sys.exit(1)

    log.info("Entering main loop. Press Ctrl+C to exit.")
    try:
        while _running:
            voltages = []
            for ch in ADC_CHANNELS:
                try:
                    raw = read_adc(spi, ch)
                    v = adc_to_voltage(raw)
                    voltages.append(v)
                except Exception as exc:
                    log.error("Skipping channel %d: %s", ch, exc)
                    voltages.append(None)
            update_display(device, voltages)
            time.sleep(UPDATE_INTERVAL_S)
    except Exception as exc:
        log.error("Unexpected error in main loop: %s", exc)
    finally:
        log.info("Cleaning up resources.")
        try:
            spi.close()
        except Exception:
            pass
        try:
            device.cleanup()
        except Exception:
            pass
        log.info("Done.")


if __name__ == "__main__":
    main()

