import signal
import sys
import time

import board
import busio
from adafruit_ssd1306 import SSD1306_I2C
from adafruit_tsl2561 import TSL2561

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
TSL2561_ADDR = 0x3C
OLED_WIDTH = 128
OLED_HEIGHT = 64
INTEGRATION_TIME_MS = 101
GAIN = 1
LUX_SCALE = 255.0 / 10000.0

# --- Globals for cleanup -----------------------------------------------------
_i2c = None
_oled = None
_light = None
_running = True


def _cleanup(signum=None, frame=None):
    """Power down the light sensor, clear the OLED, and close the bus."""
    global _running, _i2c, _oled, _light
    _running = False
    if _light is not None:
        try:
            _light.enable_proximity = False
            _light.integration_time = TSL2561.INTEGRATIONTIME_101MS
            _light.gain = GAIN
        except Exception:
            pass
    if _oled is not None:
        try:
            _oled.fill(0)
            _oled.show()
        except Exception:
            pass
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def _init_i2c():
    """Initialize the I2C bus and verify the TSL2561 is present."""
    global _i2c
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while not _i2c.try_lock():
            pass
        try:
            devices = _i2c.scan()
        finally:
            _i2c.unlock()
    except Exception as exc:
        print(f"Error scanning I2C bus: {exc}", file=sys.stderr)
        _i2c.deinit()
        sys.exit(1)

    if TSL2561_ADDR not in devices:
        print(
            f"TSL2561 not found at 0x{TSL2561_ADDR:02X}; "
            f"detected: {[hex(d) for d in devices]}",
            file=sys.stderr,
        )
        _i2c.deinit()
        sys.exit(1)


def _init_oled():
    """Initialize the SSD1306 OLED display."""
    global _oled
    try:
        _oled = SSD1306_I2C(
            OLED_WIDTH, OLED_HEIGHT, _i2c, port=18, addr=0x3C
        )
        _oled.fill(0)
        _oled.show()
    except Exception as exc:
        print(f"Error initializing OLED: {exc}", file=sys.stderr)
        _i2c.deinit()
        sys.exit(1)


def _init_light():
    """Initialize the TSL2561 light sensor."""
    global _light
    try:
        _light = TSL2561(_i2c, address=TSL2561_ADDR)
        _light.integration_time = INTEGRATION_TIME_MS
        _light.gain = GAIN
    except Exception as exc:
        print(f"Error initializing TSL2561: {exc}", file=sys.stderr)
        _i2c.deinit()
        sys.exit(1)


def compute_lux(raw_ch0, raw_ch1):
    """Compute lux from raw channel values using the TSL2561 formula."""
    if raw_ch0 == 0:
        return 0.0
    ratio = raw_ch1 / raw_ch0
    if ratio <= 0.52:
        lux = 0.0315 * raw_ch0 - 0.05934 * raw_ch0 * (ratio ** 1.4)
    elif ratio <= 0.65:
        lux = 0.0219 * raw_ch0 - 0.0291 * raw_ch0 * (ratio ** 1.2)
    elif ratio <= 0.80:
        lux = 0.0144 * raw_ch0 - 0.0159 * raw_ch0 * (ratio ** 1.05)
    elif ratio <= 1.3:
        lux = 0.0036 * raw_ch0 - 0.0028 * raw_ch0 * (ratio ** 0.85)
    else:
        lux = 0.0
    return max(lux, 0.0)


def main():
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    _init_i2c()
    _init_oled()
    _init_light()

    while _running:
        try:
            raw_ch0, raw_ch1 = _light.raw_values
            lux = compute_lux(raw_ch0, raw_ch1)
            brightness = int(round(lux * LUX_SCALE))
            _oled.fill(0)
            _oled.text(f"Lux: {lux:.2f}", 0, 0, 1)
            _oled.text(f"Brightness: {brightness}", 0, 16, 1)
            _oled.show()
        except Exception as exc:
            print(f"Error during read cycle: {exc}", file=sys.stderr)
        time.sleep(1)


if __name__ == "__main__":
    main()

