            self.spi.mode = 0
            self.spi.bits_per_word = 8
        except Exception as e:
            self.spi.close()
            raise RuntimeError(f"Failed to initialize SPI: {e}")
        self._initialized = True
        logger.info("ST7789 display initialized on SPI %d.%d", spi_port, spi_device)

    def clear(self, color=(0, 0, 0)):
        """Clear the display to the specified RGB color."""
        if not self._initialized:
            raise RuntimeError("Display not initialized")
        image = Image.new('RGB', (self.width, self.height), color)
        self.show_image(image)

    def show_image(self, image):
        """Display a PIL Image on the ST7789."""
        if not self._initialized:
            raise RuntimeError("Display not initialized")
        if image.size != (self.width, self.height):
            image = image.resize((self.width, self.height))
        rgb_image = image.convert('RGB')
        pixels = list(rgb_image.getdata())
        # Pack 24-bit RGB into bytes (R, G, B)
        packed = [(b & 0xF8) << 8 | (g & 0xFC) << 3 | (r & 0xF8) >> 3 for r, g, b in pixels]
        try:
            self.spi.writebytes(packed)
        except Exception as e:
            logger.error("SPI write failed: %s", e)
            raise

    def cleanup(self):
        """Release SPI resources."""
        if self._initialized:
            try:
                self.spi.close()
            except Exception:
                pass
            self._initialized = False


class GifPlayer:
    """Plays GIF animations on an ST7789 display."""

    def __init__(self, display: ST7789Display, folder: str, default_duration: int = 100):
        if not os.path.isdir(folder):
            raise FileNotFoundError(f"Folder not found: {folder}")
        self.display = display
        self.folder = folder
        self.default_duration = default_duration
        self.gif_files: List[str] = []
        self._running = True
        self._load_gif_files()

    def _load_gif_files(self):
        """Load all .gif files from the specified folder."""
        try:
            self.gif_files = [
                f for f in os.listdir(self.folder)
                if f.lower().endswith('.gif') and os.path.isfile(os.path.join(self.folder, f))
            ]
        except FileNotFoundError:
            raise FileNotFoundError(f"Folder not found: {self.folder}")
        except PermissionError as e:
            raise PermissionError(f"Permission denied accessing folder {self.folder}: {e}")
        if not self.gif_files:
            raise FileNotFoundError(f"No .gif files found in {self.folder}")
        logger.info("Found %d GIF files in %s", len(self.gif_files), self.folder)

    def _get_gif_file_path(self, index: int) -> str:
        """Return the path of the GIF at the given index, or None if invalid."""
        if 0 <= index < len(self.gif_files):
            return os.path.join(self.folder, self.gif_files[index])
        return None

    def _play_animation(self, image_sequence: List[Image.Image]):
        """Play a single animation from a list of PIL Image frames."""
        if not image_sequence:
            logger.warning("Empty image sequence for animation.")
            return

        total_duration = sum(self._get_frame_duration(frame) for frame in image_sequence)
        start_time = time.monotonic()
        frame_index = 0

        try:
            while self._running:
                elapsed = time.monotonic() - start_time
                remaining = total_duration - elapsed
                if remaining <= 0:
                    logger.info("Animation complete.")
                    break

                duration = self._get_frame_duration(image_sequence[frame_index])
                sleep_time = max(0, duration - (time.monotonic() - start_time))
                time.sleep(sleep_time)

                self.display.show_image(image_sequence[frame_index])
                frame_index += 1
                if frame_index >= len(image_sequence):
                    frame_index = 0
        except Exception as e:
            logger.error("Error playing animation: %s", e)
            raise

    def _get_frame_duration(self, frame: Image.Image) -> int:
        """Return the duration of a single frame in milliseconds."""
        try:
            if hasattr(frame, 'info') and 'duration' in frame.info:
                return int(frame.info['duration'])
            return self.default_duration
        except Exception:
            return self.default_duration

    def play(self, index: int = 0) -> None:
        """Play the GIF at the specified index."""
        file_path = self._get_gif_file_path(index)
        if not file_path:
            logger.error("Invalid GIF index: %d", index)
            return

        try:
            sequence = []
            with Image.open(file_path) as image:
                for frame in image.sequence:
                    if not self._running:
                        break
                    sequence.append(frame.convert('RGB'))
            self._play_animation(sequence)
        except FileNotFoundError:
            logger.error("GIF file not found: %s", file_path)
        except Exception as e:
            logger.error("Error playing GIF %s: %s", file_path, e)

    def run(self) -> None:
        """Run through all available GIFs indefinitely."""
        logger.info("Starting GIF player. Press Ctrl+C to exit.")
        try:
            while self._running:
                for i, file_path in enumerate(self.gif_files):
                    if not self._running:
                        break
                    self.play(i)
        except Exception as e:
            logger.error("Unexpected error in run loop: %s", e)
        finally:
            self.cleanup()

    def cleanup(self) -> None:
        """Release resources and clear the display."""
        self._running = False
        try:
            self.display.clear()
        except Exception as e:
            logger.error("Error during cleanup: %s", e)
        if hasattr(self, 'display') and self.display:
            self.display.cleanup()
        logger.info("Cleanup complete.")


def main():
    """Main entry point."""
    display = None
    try:
        display = ST7789Display(spi_port=0, spi_device=0, width=240, height=240)
    except RuntimeError as e:
        logger.error("Failed to initialize display: %s", e)
        return

    player = GifPlayer(display, '/home/pi/gifs', default_duration=100)

    def signal_handler(signum, frame):
        logger.info("Signal %d received, shutting down...", signum)
        player._running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        player.run()
    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        if display:
            display.cleanup()


