import math
import time
import signal
import sys

# GPIO pins for the left and right motors (BCM numbering)
LEFT_MOTOR_PIN_1 = 12
LEFT_MOTOR_PIN_2 = 13
RIGHT_MOTOR_PIN_1 = 18
RIGHT_MOTOR_PIN_2 = 19

# Constants for motor control
FORWARD_SPEED = 50
STOP_SPEED = 0

# Geometry values
ball = (180, -200)
car_front = (180, -15)
car_back = (200, -15)
goal = (0, 200)

# Tolerance for heading
HEADING_TOLERANCE_MIN = 175
HEADING_TOLERANCE_MAX = 185

# Distance threshold for forward movement
DISTANCE_THRESHOLD = 10

# Extension beyond the ball on the ball-goal line
EXTENSION = 50

# Global flag for graceful shutdown
running = True


def signal_handler(sig, frame):
    """Handle Ctrl+C to stop the robot gracefully."""
    global running
    running = False


def calculate_distance(x1, y1, x2, y2):
    """Calculates the Euclidean distance between two points."""
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)


def calculate_heading(x1, y1, x2, y2):
    """Calculates the heading (angle) of the line from point 1 to point 2 in degrees."""
    dx = x2 - x1
    dy = y2 - y1
    return math.degrees(math.atan2(dy, dx))


def calculate_intercept_point(ball_x, ball_y, goal_x, goal_y):
    """Calculates the intercept point between the ball and the line extending through the goal."""
    ball_to_goal_x = goal_x - ball_x
    ball_to_goal_y = goal_y - ball_y
    dist_sq = ball_to_goal_x ** 2 + ball_to_goal_y ** 2
    if dist_sq == 0:
        return ball_x, ball_y
    d = EXTENSION / math.sqrt(dist_sq)
    return int(ball_x + d * ball_to_goal_x), int(ball_y + d * ball_to_goal_y)


def calculate_intercept_distance(intercept_x, intercept_y, goal_x, goal_y):
    """Calculates the distance from the intercept point to the goal."""
    return calculate_distance(intercept_x, intercept_y, goal_x, goal_y)


def calculate_intercept_angle(intercept_x, intercept_y, ball_x, ball_y):
    """Calculates the angle between the line from the ball to the intercept point and the horizontal axis."""
    return calculate_heading(ball_x, ball_y, intercept_x, intercept_y)


def calculate_intercept_distance_to_ball(intercept_x, intercept_y, ball_x, ball_y):
    """Calculates the distance from the intercept point to the ball."""
    return calculate_distance(intercept_x, intercept_y, ball_x, ball_y)


def calculate_distance_to_line(x, y, line_x1, line_y1, line_x2, line_y2):
    """Calculates the perpendicular distance from a point to a line."""
    dx = line_x2 - line_x1
    dy = line_y2 - line_y1
    d = math.sqrt(dx * dx + dy * dy)
    if d == 0:
        return 0
    x1 = line_x1 - x
    x2 = line_x2 - x
    y1 = line_y1 - y
    y2 = line_y2 - y
    cross = x1 * y2 - x2 * y1
    return abs(cross) / d


def calculate_distance_to_goal(x, y, goal_x, goal_y):
    """Calculates the distance from a point to the goal."""
    return calculate_distance(x, y, goal_x, goal_y)


def calculate_distance_to_intercept(x, y, intercept_x, intercept_y):
    """Calculates the distance from a point to the intercept point."""
    return calculate_distance(x, y, intercept_x, intercept_y)


def calculate_distance_to_line_intercept(x, y, line_x1, line_y1, line_x2, line_y2):
    """Calculates the perpendicular distance from a point to a line (intercept line)."""
    return calculate_distance_to_line(x, y, line_x1, line_y1, line_x2, line_y2)


def calculate_distance_to_ball(x, y, ball_x, ball_y):
    """Calculates the distance from a point to the ball."""
    return calculate_distance(x, y, ball_x, ball_y)


def calculate_distance_to_car_front(x, y, front_x, front_y):
    """Calculates the distance from a point to the front of the car."""
    return calculate_distance(x, y, front_x, front_y)


def calculate_distance_to_car_back(x, y, back_x, back_y):
    """Calculates the distance from a point to the back of the car."""
    return calculate_distance(x, y, back_x, back_y)


def calculate_distance_to_nearest_line(x, y, line_x1, line_y1, line_x2, line_y2):
    """Calculates the distance from a point to the nearest of two lines."""
    dist_to_line1 = calculate_distance_to_line(x, y, line_x1, line_y1, line_x2, line_y2)
    dist_to_line2 = calculate_distance_to_line(x, y, line_x1, line_y1, line_x2, line_y2)
    return min(dist_to_line1, dist_to_line2)


def control_motor(left_speed, right_speed):
    """Controls the motors based on the calculated speeds."""
    # In a real implementation, you would use a motor driver library here.
    # For this example, we simulate motor control by printing the speeds.
    print(f"Motor Control: Left={left_speed}, Right={right_speed}")


def main():
    """Main function to run the robot control loop."""
    global running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    intercept_x, intercept_y = calculate_intercept_point(ball[0], ball[1], goal[0], goal[1])
    print(f"Intercept Point: ({intercept_x}, {intercept_y})")

    try:
        for iteration in range(1000):
            if not running:
                break

            # Calculate distances and angles
            distance_to_intercept = calculate_distance_to_intercept(car_front[0], car_front[1], intercept_x, intercept_y)
            distance_to_ball = calculate_distance_to_ball(car_front[0], car_front[1], ball[0], ball[1])
            distance_to_goal = calculate_distance_to_goal(car_front[0], car_front[1], goal[0], goal[1])
            distance_to_nearest_line = calculate_distance_to_nearest_line(car_front[0], car_front[1], intercept_x, intercept_y, goal[0], goal[1])

            if distance_to_ball > 0:
                heading_to_intercept = calculate_intercept_angle(intercept_x, intercept_y, ball[0], ball[1])
                distance_to_nearest_line_intercept = calculate_distance_to_nearest_line(car_front[0], car_front[1], intercept_x, intercept_y, goal[0], goal[1])

                if distance_to_nearest_line_intercept > 0:
                    distance_to_nearest_line_intercept_intercept = calculate_distance_to_nearest_line(car_front[0], car_front[1], intercept_x, intercept_y, goal[0], goal[1])
                    distance_to_nearest_line_intercept_ball = calculate_distance_to_nearest_line(car_front[0], car_front[1], intercept_x, intercept_y, ball[0], ball[1])

                    if distance_to_nearest_line_intercept_intercept < distance_to_nearest_line_intercept_ball:
                        distance_to_nearest_line = distance_to_nearest_line_intercept_intercept
                        heading_to_intercept = calculate_intercept_angle(intercept_x, intercept_y, ball[0], ball[1])
                    else:
                        distance_to_nearest_line = distance_to_nearest_line_intercept_ball
                        heading_to_intercept = calculate_heading(ball[0], ball[1], car_front[0], car_front[1])

                if distance_to_intercept > DISTANCE_THRESHOLD:
                    control_motor(FORWARD_SPEED, FORWARD_SPEED)
                    print(f"Iteration {iteration + 1}: Moving forward (dist={distance_to_intercept:.1f}, heading={heading_to_intercept:.1f})")
                else:
                    control_motor(0, 0)
                    print(f"Iteration {iteration + 1}: At intercept point")
                    break

            else:
                print(f"Iteration {iteration + 1}: Ball too close")
                control_motor(0, 0)
                break

            time.sleep(0.1)

    except Exception as e:
        print(f"Error during execution: {e}")
    finally:
        print("Stopping motors and cleaning up...")
        control_motor(STOP_SPEED, STOP_SPEED)
        print("Robot control loop finished.")


if __name__ == "__main__":
    main()

