import smbus
import time
import signal
import sys

# PCF8574 I2C address (A0‑A2 tied to GND)
PCF8574_ADDR = 0x3F
# Port B bit masks for sensors 0‑7
SENSOR_MASKS = [0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80]
POLL_INTERVAL = 0.1
RETRY_DELAY = 1.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor(bus, sensor_num):
    """Read an active-low sensor from the PCF8574. Returns True if obstacle detected (LOW)."""
    mask = SENSOR_MASKS[sensor_num]
    try:
        data = bus.read_byte(PCF8574_ADDR)
        return not bool(data & mask)
    except OSError as e:
        print(f"I2C read error on sensor {sensor_num}: {e}")
        return False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = smbus.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}")
        sys.exit(1)

    try:
        while running:
            for sn in range(8):
                if not running:
                    break
                if not read_sensor(bus, sn):
                    print(f"Error reading sensor {sn}. Retrying in {RETRY_DELAY}s...")
                    time.sleep(RETRY_DELAY)
                    continue
                if read_sensor(bus, sn):
                    print(f"Obstacle detected by sensor {sn}")
            if running:
                time.sleep(POLL_INTERVAL)
    finally:
        if bus is not None:
            bus.close()
        print("Program terminated cleanly.")

if __name__ == "__main__":
    main()

