import time
import logging
import signal
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """
    Driver for the DHT20 temperature/humidity sensor using I2C on a Raspberry Pi.

    The DHT20 is accessed via I2C bus 1 (SDA=GPIO2, SCL=GPIO3).  It requires
    a 0.5 s power-on stabilization delay and performs a status-register check
    before each read.  CRC-8 validation is performed over the first six bytes
    using the documented polynomial and initial value.
    """

    # --- Constants -----------------------------------------------------------
    I2C_BUS = 1
    I2C_ADDR = 0x76
    POWER_ON_DELAY = 0.5
    STATUS_CHECK_MASK = 0x80
    STATUS_CHECK_VALUE = 0x00
    POLYNOMIAL = 0x31
    INIT_VALUE = 0xFF
    MAX_RETRIES = 5
    RETRY_DELAY = 2.0
    POLL_TIMEOUT = 0.1
    MAX_BYTES = 7

    # --- Internal state ------------------------------------------------------
    _bus: smbus2.SMBus | None = None
    _closed = False

    # --- Lifecycle ----------------------------------------------------------
    def __init__(self, bus_num: int = I2C_BUS, addr: int = I2C_ADDR):
        if not isinstance(bus_num, int) or bus_num < 0:
            raise ValueError(f"Invalid I2C bus number: {bus_num!r}")
        if not isinstance(addr, int) or addr < 0 or addr > 0xFF:
            raise ValueError(f"Invalid I2C address: 0x{addr:02X}")
        self._addr = addr
        self._bus = None
        self._install_signal_handlers()
        try:
            self._bus = smbus2.SMBus(bus_num)
        except FileNotFoundError:
            raise RuntimeError(f"I2C bus {bus_num} not found. Enable I2C with 'raspi-config'.")
        except PermissionError:
            raise RuntimeError(f"Permission denied opening I2C bus {bus_num}. Run as root or add user to 'i2c' group.")
        except OSError as exc:
            raise RuntimeError(f"Failed to open I2C bus {bus_num}: {exc}") from exc
        self._initialize()

    def _install_signal_handlers(self):
        """Ensure the bus is closed on SIGINT / SIGTERM."""
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame):
        logger.info("Signal %s received; closing I2C bus.", signum)
        self.close()
        raise SystemExit(0)

    # -- Public API ---------------------------------------------------------
    def read(self) -> tuple[float | None, float | None, bool]:
        """
        Read temperature (°C) and humidity (%RH).

        Returns:
            (temperature, humidity, crc_error_flag)
        crc_error_flag is True when the CRC mismatch is detected.
        """
        if self._bus is None:
            logger.error("I2C bus is not initialized.")
            return None, None, True

        for attempt in range(1, self.MAX_RETRIES + 1):
            try:
                if not self._wait_for_nmi():
                    logger.warning("NMI not set (status 0x%02X) - retrying (attempt %d/%d).",
                                  self._read_u8(0xAA), attempt, self.MAX_RETRIES)
                    time.sleep(self.RETRY_DELAY)
                    continue

                data = self._read_data()
                if data is None:
                    logger.warning("Failed to read data from DHT20 (attempt %d/%d).", attempt, self.MAX_RETRIES)
                    time.sleep(self.RETRY_DELAY)
                    continue

                crc_ok = self._verify_crc(data)
                if not crc_ok:
                    logger.warning("CRC mismatch on data (attempt %d/%d).", attempt, self.MAX_RETRIES)
                    time.sleep(self.RETRY_DELAY)
                    continue

                humidity_raw = self._combine_bytes(data[1], data[2], data[3])
                temperature_raw = self._combine_bytes(data[3], data[4], data[5])
                temperature = self._celsius(temperature_raw)
                humidity = self._percent(humidity_raw)
                return temperature, humidity, False

            except OSError as exc:
                logger.error("I2C bus error during read (attempt %d/%d): %s", attempt, self.MAX_RETRIES, exc)
                time.sleep(self.RETRY_DELAY)

        logger.error("Failed to read DHT20 after %d retries.", self.MAX_RETRIES)
        return None, None, True

    # -- Internal helpers ----------------------------------------------------
    def _wait_for_nmi(self) -> bool:
        """Poll the status register bit 7 until it clears (NMI asserted)."""
        deadline = time.monotonic() + self.POLL_TIMEOUT
        while time.monotonic() < deadline:
            status = self._read_u8(0xAA)
            if not (status & self.STATUS_CHECK_MASK):
                return True
            time.sleep(0.001)
        return False

    def _read_u8(self, reg: int) -> int:
        return self._bus.read_byte_data(self._addr, reg)

    def _read_data(self) -> list[int] | None:
        """Read 7 bytes starting at 0x70; return None on short read / bus error."""
        try:
            return self._bus.read_i2c_block_data(self._addr, 0x70, self.MAX_BYTES)
        except OSError as exc:
            logger.error("I2C read failed: %s", exc)
            return None

    def _combine_bytes(self, low: int, mid: int, high: int) -> int:
        """Combine three nibbles into a 20-bit raw value (MSB first)."""
        return (high << 12) | (mid << 4) | (low >> 4)

    def _celsius(self, raw: int) -> float | None:
        """Convert a 20-bit raw temperature value to Celsius."""
        if raw is None:
            return None
        return (raw / 1048576.0) * 200.0 - 50.0

    def _percent(self, raw: int) -> float | None:
        """Convert a 20-bit raw humidity value to percent relative humidity."""
        if raw is None:
            return None
        return (raw / 1048576.0) * 100.0

    def _verify_crc(self, data: list[int]) -> bool:
        """
        CRC-8 validation over the first six bytes using the DHT20 polynomial.
        Returns True if the checksum matches the 7th byte, False otherwise.
        """
        if len(data) < 7:
            return False
        crc = self.INIT_VALUE
        for byte in data[:6]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc == data[6]

    def _initialize(self) -> None:
        """Power-on delay followed by a status-register check."""
        time.sleep(self.POWER_ON_DELAY)
        status = self._read_u8(0xAA)
        if status & self.STATUS_CHECK_MASK != self.STATUS_CHECK_VALUE:
            raise RuntimeError(f"DHT20 status check failed: 0x{status:02X} (expected 0x{self.STATUS_CHECK_VALUE:02X})")
        logger.info("DHT20 initialized successfully (status 0x%02X).", status)

    def close(self) -> None:
        """Release the I2C bus if it is open."""
        if self._bus is not None and not self._closed:
            try:
                self._bus.close()
            except OSError as exc:
                logger.warning("Error closing I2C bus: %s", exc)
            finally:
                self._bus = None
                self._closed = True

    def __del__(self):
        self.close()


if __name__ == "__main__":
    try:
        sensor = DHT20(bus_num=1, addr=0x76)
        temp, hum, err = sensor.read()
        if err:
            logger.error("CRC error or read failure.")
        else:
            logger.info("Temperature: %.2f °C, Humidity: %.2f %%RH", temp, hum)
    except Exception as exc:
        logger.error("Initialization or read error: %s", exc)

