import serial
import signal
import sys
from datetime import datetime

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Global handle for signal handler
_uart = None

def _cleanup(signum=None, frame=None):
    """Close the UART port on exit or signal."""
    global _uart
    if _uart is not None:
        try:
            _uart.close()
            print(f"UART port {SERIAL_PORT} closed.")
        except Exception as e:
            print(f"Error closing UART: {e}", file=sys.stderr)
        finally:
            _uart = None
    if signum is not None:
        sys.exit(0)

def validate_weather_data(data_string):
    """Validate the weather data format and ranges."""
    try:
        parts = data_string.split(',')
        if len(parts) != 3:
            return False
        temperature = float(parts[0])
        humidity = float(parts[1])
        pressure = float(parts[2])
    except ValueError:
        return False

    if not (-40 <= temperature <= 85):
        return False
    if not (0 <= humidity <= 100):
        return False
    if not (800 <= pressure <= 1200):
        return False
    return True

def process_weather_data(data_string):
    """Process and print valid weather data."""
    if validate_weather_data(data_string):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        print(f"[{timestamp}] Temperature: {data_string.split(',')[0]}°C, "
              f"Humidity: {data_string.split(',')[1]}%, "
              f"Pressure: {data_string.split(',')[2]} hPa")
    else:
        print(f"Invalid weather data: {data_string}")

def main():
    """Main function to read and process weather data from UART."""
    global _uart
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    try:
        _uart = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Error opening UART port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                raw = _uart.readline()
                if not raw:
                    continue
                data = raw.decode('ascii', errors='replace').strip()
                if data:
                    process_weather_data(data)
            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break
            except OSError as e:
                print(f"I/O error: {e}", file=sys.stderr)
                break
    finally:
        _cleanup()

if __name__ == "__main__":
    main()

