import time
import signal
import sys
import logging
import configparser
from gpiozero import LED, DigitalInputDevice
from gpiozero.exc import GPIOZeroError

CONFIG_FILE = 'config.ini'

DEFAULT_CONFIG = {
    'GPIO': {
        'DHT_PIN': '4',
        'LED_PIN': '17'
    },
    'Logging': {
        'LEVEL': 'INFO'
    },
    'Sensor': {
        'READ_INTERVAL': '5'
    }
}

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_config(config_file):
    config = configparser.ConfigParser()
    config.read_dict(DEFAULT_CONFIG)
    if not config.read(config_file):
        logging.warning(f"Config file {config_file} not found; using defaults.")
    return config

def setup_logging(log_level):
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f"Invalid log level: {log_level}")
    logging.basicConfig(
        level=numeric_level,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[
            logging.FileHandler('sensor_monitor.log'),
            logging.StreamHandler(sys.stdout)
        ]
    )

def read_sensor(dht_device):
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None for temperature or humidity")
        logging.info(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")
        return temperature, humidity
    except RuntimeError as e:
        logging.error(f"Sensor read error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected sensor error: {e}")
        return None, None

def control_led(led, error):
    if error:
        led.on()
        logging.warning("Sensor error detected; LED on.")
    else:
        led.blink(on_time=0.5, off_time=0.5, background=True)
        logging.info("Normal operation; LED blinking.")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    try:
        setup_logging(config['Logging']['LEVEL'])
    except (ValueError, KeyError) as e:
        print(f"Error setting up logging: {e}")
        sys.exit(1)

    dht_pin = int(config['GPIO']['DHT_PIN'])
    led_pin = int(config['GPIO']['LED_PIN'])
    read_interval = int(config['Sensor']['READ_INTERVAL'])

    try:
        dht_device = DigitalInputDevice(dht_pin, pull_up=False)
        led = LED(led_pin)
    except GPIOZeroError as e:
        logging.error(f"GPIO initialization failed: {e}")
        sys.exit(1)
    except Exception as e:
        logging.error(f"Unexpected initialization error: {e}")
        sys.exit(1)

    logging.info("Starting sensor monitoring...")

    try:
        while running:
            temperature, humidity = read_sensor(dht_device)
            error = temperature is None or humidity is None
            control_led(led, error)
            time.sleep(read_interval)
    except Exception as e:
        logging.error(f"Fatal error in main loop: {e}")
    finally:
        logging.info("Shutting down...")
        try:
            led.off()
            led.close()
            dht_device.close()
        except Exception:
            pass
        logging.info("Cleanup complete. Exiting.")

if __name__ == "__main__":
    main()

