try:
    i2c_bus = busio.I2C(board.SCL, board.SDA)
except Exception as e:
    print(f"Failed to initialize I2C bus: {e}")
    exit(1)

# Initialize TCA9548A I2C multiplexer
try:
    i2c_multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
except Exception as e:
    print(f"Failed to initialize TCA9548A multiplexer: {e}")
    exit(1)

# Initialize BME280 sensor (channel 0)
try:
    bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_multiplexer[0], address=0x76)
except Exception as e:
    print(f"Failed to initialize BME280 sensor: {e}")
    exit(1)

# Initialize TSL2591 sensor (channel 1)
try:
    tsl2591_sensor = adafruit_tsl2591.TSL2591(i2c_multiplexer[1], address=0x74)
except Exception as e:
    print(f"Failed to initialize TSL2591 sensor: {e}")
    exit(1)

# Main loop
try:
    while True:
        # Read BME280 sensor data
        try:
            temperature = bme280_sensor.temperature
            humidity = bme280_sensor.humidity
            print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
        except Exception as e:
            print(f"Error reading BME280 sensor: {e}")

        # Read TSL2591 sensor data
        try:
            light_level = tsl2591_sensor.lux
            print(f"Light Level: {light_level:.2f} lux")
        except Exception as e:
            print(f"Error reading TSL2591 sensor: {e}")

        # Pause for 2 seconds
        time.sleep(2)

except KeyboardInterrupt:
    print("Exiting program")

