import json
import logging
import os
import random
import signal
import sys
import time
import urllib.error
import urllib.request
from collections import deque
from datetime import datetime

try:
    import board
    import adafruit_dht
except ImportError:
    print("Required libraries not found. Install with:")
    print("  pip install adafruit-circuitpython-dht")
    sys.exit(1)

CONFIG_FILE = "config.json"
DHT_PIN = board.D4
MAX_SAMPLES = 5
READ_INTERVAL = 60
WEBHOOK_URL = None
SIMULATION_MODE = False

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

_running = True
_last_temp = None
_last_hum = None
_temp_buffer = deque(maxlen=MAX_SAMPLES)
_hum_buffer = deque(maxlen=MAX_SAMPLES)


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


def _load_config():
    global WEBHOOK_URL
    try:
        with open(CONFIG_FILE, "r") as f:
            cfg = json.load(f)
        WEBHOOK_URL = cfg.get("webhook_url")
        SIMULATION_MODE = cfg.get("simulation_mode", False)
        logger.info("Configuration loaded from %s", CONFIG_FILE)
    except FileNotFoundError:
        logger.warning("config.json not found; using defaults.")
    except json.JSONDecodeError as exc:
        logger.error("Invalid JSON in config.json: %s", exc)
    except OSError as exc:
        logger.error("Cannot read config.json: %s", exc)


def _simulate_sensor_data():
    global _last_temp, _last_hum
    _last_temp = round(random.uniform(20.0, 30.0), 1)
    _last_hum = round(random.uniform(60.0, 80.0), 1)
    return _last_temp, _last_hum


def _validate(temp, hum):
    if temp is None or hum is None:
        return False
    if not (-40.0 <= temp <= 80.0):
        logger.warning("Temperature out of range: %.1f", temp)
        return False
    if not (0.0 <= hum <= 100.0):
        logger.warning("Humidity out of range: %.1f", hum)
        return False
    return True


def _moving_average(temp, hum):
    _temp_buffer.append(temp)
    _hum_buffer.append(hum)
    if len(_temp_buffer) < MAX_SAMPLES:
        return None, None
    avg_temp = sum(_temp_buffer) / len(_temp_buffer)
    avg_hum = sum(_hum_buffer) / len(_hum_buffer)
    return avg_temp, avg_hum


def _send_webhook(temp, hum):
    if WEBHOOK_URL is None:
        logger.error("Webhook URL not configured.")
        return False
    payload = json.dumps({"temperature": temp, "humidity": hum}).encode("utf-8")
    req = urllib.request.Request(
        WEBHOOK_URL,
        data=payload,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    for attempt in range(3):
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if 200 <= resp.status < 300:
                    logger.info("Webhook sent successfully (attempt %d).", attempt + 1)
                    return True
                logger.error(
                    "Webhook failed with HTTP %d (attempt %d).",
                    resp.status,
                    attempt + 1,
                )
        except urllib.error.URLError as exc:
            logger.error("Webhook network error: %s (attempt %d).", exc, attempt + 1)
        except Exception as exc:
            logger.error("Webhook unexpected error: %s (attempt %d).", exc, attempt + 1)
        if attempt < 2:
            time.sleep(1 if attempt == 0 else 3 if attempt == 1 else 9)
    logger.error("Webhook failed after 3 retries.")
    return False


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _load_config()

    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        logger.error("Failed to initialize DHT22 on pin %s: %s", DHT_PIN, exc)
        sys.exit(1)

    logger.info("Greenhouse monitoring started (pin %s, interval %ds, max %d samples).",
                DHT_PIN, READ_INTERVAL, MAX_SAMPLES)

    try:
        while _running:
            if SIMULATION_MODE:
                temp, hum = _simulate_sensor_data()
            else:
                try:
                    temp = dht_device.temperature
                    hum = dht_device.humidity
                except RuntimeError as exc:
                    logger.warning("DHT22 read error (simulation): %s", exc)
                    temp, hum = _simulate_sensor_data()
                except Exception as exc:
                    logger.error("Unexpected DHT22 error: %s", exc)
                    temp, hum = _simulate_sensor_data()

            if _validate(temp, hum):
                avg_temp, avg_hum = _moving_average(temp, hum)
                if avg_temp is not None and avg_hum is not None:
                    logger.info("Avg T=%.1f°C  H=%.1f%%", avg_temp, avg_hum)
                    _send_webhook(avg_temp, avg_hum)
                else:
                    logger.info("Not enough samples yet (avg).")
            else:
                logger.warning("Invalid sensor data; skipping.")

            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)

            if not _running:
                break

            if _validate(temp, hum):
                logger.info("Valid reading; resuming normal acquisition.")
            else:
                logger.warning("Consecutive failures; pausing %ds before retry.", 300)
                for _ in range(300):
                    if not _running:
                        break
                    time.sleep(1)

    finally:
        try:
            dht_device.exit()
        except Exception:
            pass
        logger.info("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

