import time
import board
import busio
import adafruit_ahtx0

# Constants
READ_INTERVAL = 5  # seconds between readings
TEMP_MIN, TEMP_MAX = -40.0, 85.0
HUM_MIN, HUM_MAX = 0.0, 100.0

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Scan for devices to confirm the bus is functional
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
        finally:
            i2c.unlock()
        if 0 not in devices:
            print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Error: No I2C devices detected on SCL={board.SCL}, SDA={board.SDA}")
            i2c.deinit()
            return None
        return i2c
    except Exception as e:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Error initializing I2C bus: {e}")
        return None


def initialize_sensor(i2c_bus):
    """Initialize the AHT20 sensor on the given I2C bus."""
    try:
        sensor = adafruit_ahtx0.AHTx0(i2c_bus)
        # Force a read to confirm the sensor is actually responding
        _ = sensor.temperature
        return sensor
    except Exception as e:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Error initializing AHT20 sensor: {e}")
        return None


def read_sensor_data(sensor):
    """Read temperature and humidity from the sensor.
    Returns (temperature, humidity) or (None, None) on error."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Error: Sensor returned None for temperature or humidity.")
            return None, None
        return temperature, humidity
    except Exception as e:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Error reading sensor data: {e}")
        return None, None


def validate_data(temperature, humidity):
    """Validate temperature and humidity readings are within expected ranges."""
    if temperature is None or humidity is None:
        return False
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Warning: Temperature {temperature:.1f}°C out of range [{TEMP_MIN}, {TEMP_MAX}].")
        return False
    if not (HUM_MIN <= humidity <= HUM_MAX):
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Warning: Humidity {humidity:.1f}% out of range [{HUM_MIN}, {HUM_MAX}].")
        return False
    return True


def display_data(temperature, humidity):
    """Print the timestamped temperature and humidity."""
    if temperature is not None and humidity is not None:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")


def main():
    """Main loop: initialize, read, validate, display, and handle shutdown."""
    global _running

    # Register signal handlers for graceful shutdown
    import signal
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = None
    sensor = None

    try:
        # Attempt to initialize the I2C bus and sensor
        while _running and i2c_bus is None:
            i2c_bus = initialize_i2c()
            if i2c_bus is None:
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Retrying I2C initialization in {READ_INTERVAL} seconds...")
                time.sleep(READ_INTERVAL)

        if not _running:
            return

        # Attempt to initialize the sensor
        while _running and sensor is None:
            sensor = initialize_sensor(i2c_bus)
            if sensor is None:
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Retrying sensor initialization in {READ_INTERVAL} seconds...")
                time.sleep(READ_INTERVAL)

        if not _running:
            return

        # Main reading loop
        while _running:
            temperature, humidity = read_sensor_data(sensor)
            if validate_data(temperature, humidity):
                display_data(temperature, humidity)
            time.sleep(READ_INTERVAL)

    except Exception as e:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Unexpected error: {e}")
    finally:
        # Clean up resources on all exit paths
        if sensor is not None:
            try:
                sensor.deinit()
            except Exception:
                pass
        if i2c_bus is not None:
            try:
                i2c_bus.deinit()
            except Exception:
                pass
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: Program terminated.")


if __name__ == "__main__":
    main()

