logger = logging.getLogger(__name__)

DEGREE_CELSIUS = '\u00B0C'
DHT_READ_INTERVAL = 2.0

running = True
dht_sensor = None
mqtt_client = None


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def cleanup():
    global dht_sensor, mqtt_client
    if mqtt_client is not None:
        try:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
            logger.info("MQTT disconnected.")
        except Exception as e:
            logger.error(f"Error disconnecting MQTT: {e}")
    if dht_sensor is not None:
        try:
            dht_sensor.close()
            logger.info("GPIO cleaned up.")
        except Exception as e:
            logger.error(f"Error cleaning up GPIO: {e}")


def read_dht22():
    global dht_sensor
    if dht_sensor is None:
        raise RuntimeError("DHT sensor not initialized.")
    for attempt in range(3):
        try:
            temperature = dht_sensor.temperature
            humidity = dht_sensor.humidity
            if temperature is not None and humidity is not None:
                return round(temperature, 1), round(humidity, 1)
        except RuntimeError as e:
            logger.warning(f"DHT22 read attempt {attempt + 1} failed: {e}")
        time.sleep(2.0)
    raise RuntimeError("Failed to read DHT22 after multiple attempts.")


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker.")
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.info(f"Disconnected from MQTT broker, reason code: {reason_code}")


def main():
    global dht_sensor, mqtt_client
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        dht_sensor = DigitalInputDevice(config.dhtgpiopin, pull_up=False)
        logger.info(f"DHT22 initialized on GPIO {config.dhtgpiopin}.")
    except Exception as e:
        logger.error(f"Failed to initialize DHT22: {e}")
        sys.exit(1)

    try:
        mqtt_client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid
        )
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        mqtt_client.loop_start()
    except Exception as e:
        logger.error(f"Failed to connect to MQTT broker: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                temperature, humidity = read_dht22()
                base_topic = f"homie/{config.homieclientid}/{config.homienodes}"
                mqtt_client.publish(f"{base_topic}/temperature", str(temperature), qos=1)
                mqtt_client.publish(f"{base_topic}/humidity", str(humidity), qos=1)
                logger.info(f"Published: Temperature={temperature} {DEGREE_CELSIUS}, Humidity={humidity} %")
            except Exception as e:
                logger.error(f"Error publishing data: {e}")
            time.sleep(DHT_READ_INTERVAL)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

