import signal
import sys
import time
import smbus2

I2C_BUS = 1
SENSOR_ADDR = 0x76

# AHT20/DHT20 register addresses
REG_CHIP_ID = 0xD0
REG_RESET = 0xE3
REG_INIT = 0xAC
REG_MEASURE = 0xBA
REG_STATUS = 0x27
REG_DATA = 0x71

# Expected chip ID
EXPECTED_CHIP_ID = 0x53

# Timing constants (seconds)
RESET_DELAY = 0.02
INIT_DELAY = 0.01
MEASURE_DELAY = 0.08
READ_INTERVAL = 5.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _read_register(bus, reg):
    return bus.read_byte_data(SENSOR_ADDR, reg)

def _write_register(bus, reg, value):
    bus.write_byte_data(SENSOR_ADDR, reg, value)

def _read_block(bus, reg, length):
    return bus.read_i2c_block_data(SENSOR_ADDR, reg, length)

def _calculate_crc(data):
    crc = 0xFF
    for byte in data[:-1]:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ 0x42) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def _init_sensor(bus):
    chip_id = _read_register(bus, REG_CHIP_ID)
    if chip_id != EXPECTED_CHIP_ID:
        raise IOError(f"Invalid chip ID: 0x{chip_id:02X}, expected 0x{EXPECTED_CHIP_ID:02X}")
    _write_register(bus, REG_RESET, 0xB6)
    time.sleep(RESET_DELAY)
    _write_register(bus, REG_INIT, 0x10)
    time.sleep(INIT_DELAY)

def _read_sensor(bus):
    _write_register(bus, REG_MEASURE, 0x01)
    time.sleep(MEASURE_DELAY)
    data = _read_block(bus, REG_DATA, 7)
    status = _read_register(bus, REG_STATUS)
    if status & 0x01:
        raise IOError("Sensor not ready")
    if len(data) < 7:
        raise IOError(f"Incomplete data block: got {len(data)} bytes, expected 7")
    if _calculate_crc(data[:-1]) != data[-1]:
        raise IOError("CRC mismatch")
    return data

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
        _init_sensor(bus)
        while _running:
            try:
                data = _read_sensor(bus)
                temp_c = data[1] | (data[2] << 8)
                humidity = data[3] | (data[4] << 8)
                temp_f = temp_c * 9.0 / 5.0 + 32.0
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}: "
                      f"Temperature: {temp_c:.2f}°C / {temp_f:.2f}°F, "
                      f"Humidity: {humidity:.2f}%")
            except IOError as e:
                print(f"Error: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")
            for _ in range(int(READ_INTERVAL * 10)):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        if bus is not None:
            bus.close()

if __name__ == "__main__":
    main()

