import signal
import sys
import time
import logging
from smbus2 import SMBus, i2c_msg
from ina219 import INA219, DeviceRangeError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

SUPPLY_SHUNT_RESISTOR = 0.00725
BATTERY_SHUNT_RESISTOR = 0.005
I2C_BUS = 1
DEVICE_ADDRESS = 0x77

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logger.info("Shutdown signal received. Exiting gracefully...")

class UPSPlusMonitor:
    def __init__(self, bus_num=I2C_BUS, address=DEVICE_ADDRESS):
        self.bus_num = bus_num
        self.address = address
        self.bus = None
        self.supply_ina = None
        self.battery_ina = None
        self._initialize_i2c()
        self._initialize_sensors()

    def _initialize_i2c(self):
        try:
            self.bus = SMBus(self.bus_num)
            logger.info(f"I2C bus {self.bus_num} initialized successfully.")
        except Exception as e:
            logger.error(f"Failed to initialize I2C bus {self.bus_num}: {e}")
            raise

    def _initialize_sensors(self):
        try:
            self.supply_ina = INA219(SUPPLY_SHUNT_RESISTOR, busnum=self.bus_num, address=self.address)
            self.supply_ina.configure()
            logger.info("Supply INA219 sensor initialized successfully.")
        except Exception as e:
            logger.error(f"Failed to initialize supply INA219 sensor: {e}")
            self.supply_ina = None

        try:
            self.battery_ina = INA219(BATTERY_SHUNT_RESISTOR, busnum=self.bus_num, address=self.address)
            self.battery_ina.configure()
            logger.info("Battery INA219 sensor initialized successfully.")
        except Exception as e:
            logger.error(f"Failed to initialize battery INA219 sensor: {e}")
            self.battery_ina = None

    def read_supply_data(self):
        if not self.supply_ina:
            logger.error("Supply INA219 sensor not initialized.")
            return None, None, None
        try:
            voltage = self.supply_ina.voltage()
            current = self.supply_ina.current()
            power = self.supply_ina.power()
            return voltage, current, power
        except DeviceRangeError:
            logger.warning("Supply INA219: Current out of device range.")
            return None, None, None
        except Exception as e:
            logger.error(f"Error reading supply data: {e}")
            return None, None, None

    def read_battery_data(self):
        if not self.battery_ina:
            logger.error("Battery INA219 sensor not initialized.")
            return None, None, None
        try:
            voltage = self.battery_ina.voltage()
            current = self.battery_ina.current()
            power = self.battery_ina.power()
            return voltage, current, power
        except DeviceRangeError:
            logger.warning("Battery INA219: Current out of device range.")
            return None, None, None
        except Exception as e:
            logger.error(f"Error reading battery data: {e}")
            return None, None, None

    def close(self):
        if self.bus:
            try:
                self.bus.close()
                logger.info("I2C bus closed.")
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    ups_monitor = None
    try:
        ups_monitor = UPSPlusMonitor()
        while running:
            supply_voltage, supply_current, supply_power = ups_monitor.read_supply_data()
            battery_voltage, battery_current, battery_power = ups_monitor.read_battery_data()

            if supply_voltage is not None and supply_current is not None and supply_power is not None:
                logger.info(f"Supply: Voltage={supply_voltage:.3f} V, Current={supply_current:.3f} mA, Power={supply_power:.3f} mW")
            else:
                logger.warning("Failed to read supply data.")

            if battery_voltage is not None and battery_current is not None and battery_power is not None:
                logger.info(f"Battery: Voltage={battery_voltage:.3f} V, Current={battery_current:.3f} mA, Power={battery_power:.3f} mW")
            else:
                logger.warning("Failed to read battery data.")

            time.sleep(1.0)
    except Exception as e:
        logger.error(f"Fatal error in main loop: {e}")
    finally:
        if ups_monitor:
            ups_monitor.close()

if __name__ == "__main__":
    main()

