import subprocess
import time
import signal
import sys
import logging

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    logging.error("gpiozero is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)

PWM_PIN = 14
PWM_FREQ = 100
TEMP_INTERVAL = 5

_running = True


def _handle_signal(signum, frame):
    global _running
    logging.info("Received signal %s, shutting down...", signum)
    _running = False


def get_cpu_temp():
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            check=True,
            timeout=5,
        )
        out = result.stdout.strip()
        return float(out.split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired, IndexError, ValueError, FileNotFoundError) as e:
        logging.error("Failed to get CPU temperature: %s", e)
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    fan = None
    try:
        fan = PWMOutputDevice(PWM_PIN, frequency=PWM_FREQ, initial_value=0)
        logging.info("PWM initialized on GPIO%d at %d Hz.", PWM_PIN, PWM_FREQ)
    except Exception as e:
        logging.warning("Failed to initialize PWM on GPIO%d: %s. Continuing in degraded mode.", PWM_PIN, e)
        fan = None

    last_speed = 0.0

    try:
        while _running:
            temp = get_cpu_temp()
            if temp is not None:
                speed = 100.0 + (temp - 40.0) * 5.0
                speed = max(0.0, min(100.0, speed))
                if speed != last_speed:
                    last_speed = speed
                    if fan is not None:
                        fan.value = speed / 100.0
                        logging.info("Temp: %.1f°C -> Fan duty: %.1f%%", temp, speed)
                    else:
                        logging.info("Temp: %.1f°C -> Fan duty: %.1f%% (degraded mode)", temp, speed)
            else:
                logging.warning("Temperature read failed; keeping last fan speed.")

            for _ in range(TEMP_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    finally:
        if fan is not None:
            try:
                fan.value = 0
                fan.close()
                logging.info("PWM stopped and GPIO released.")
            except Exception as e:
                logging.error("Error during cleanup: %s", e)


if __name__ == "__main__":
    main()

