import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

FAN_PIN = 18
PWM_FREQ = 25000
TEMP_THRESHOLD = 40.0
DUTY_HIGH = 100.0
DUTY_LOW = 20.0
POLL_INTERVAL = 5.0

fan = None
running = True


def cleanup(signum=None, frame=None):
    global running, fan
    running = False
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def read_cpu_temp():
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError):
        return None


def main():
    global fan
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except GPIOZeroError as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        while running:
            temp = read_cpu_temp()
            if temp is None:
                print("Warning: temperature read failed, skipping cycle.", file=sys.stderr)
            else:
                if temp > TEMP_THRESHOLD:
                    fan.value = DUTY_HIGH / 100.0
                    print(f"Temp {temp:.1f}°C -> fan {DUTY_HIGH:.0f}%")
                else:
                    fan.value = DUTY_LOW / 100.0
                    print(f"Temp {temp:.1f}°C -> fan {DUTY_LOW:.0f}%")
            time.sleep(POLL_INTERVAL)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

