import logging
import logging.handlers
import random
import signal
import sys
import time
from pathlib import Path

try:
    import gpiozero
    from gpiozero import DigitalInputDevice
except ImportError:
    print("gpiozero is required: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

# Constants
DHT_PIN = 4
READ_INTERVAL = 5
MAX_RETRIES = 3
TEMP_MIN = 10
TEMP_MAX = 55
HUM_MIN = 20
HUM_MAX = 100
LOG_FILE = Path("/var/log/wearable")
FALLBACK_LOG_FILE = Path.home() / ".local" / "log" / "wearable"

# Global state
_running = True
_sensor = None


def setup_logging():
    log_file = LOG_FILE
    if not log_file.exists() or not log_file.parent.exists():
        log_file = FALLBACK_LOG_FILE
    logger = logging.getLogger("wearable")
    logger.setLevel(logging.INFO)
    logger.handlers.clear()
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    try:
        file_handler = logging.handlers.TimedRotatingFileHandler(
            str(log_file), when="midnight", interval=1, backupCount=7
        )
        file_handler.setFormatter(formatter)
        logger.addHandler(file_handler)
    except OSError as e:
        print(f"Cannot write to {log_file}: {e}. Falling back to {FALLBACK_LOG_FILE}.", file=sys.stderr)
        try:
            file_handler = logging.handlers.TimedRotatingFileHandler(
                str(FALLBACK_LOG_FILE), when="midnight", interval=1, backupCount=7
            )
            file_handler.setFormatter(formatter)
            logger.addHandler(file_handler)
        except OSError as e2:
            print(f"Cannot write to {FALLBACK_LOG_FILE}: {e2}.", file=sys.stderr)
    console_handler = logging.StreamHandler()
    console_handler.setFormatter(formatter)
    logger.addHandler(console_handler)
    return logger


def simulate_dht22_reading():
    temperature = random.uniform(15, 45)
    humidity = random.uniform(40, 95)
    return temperature, humidity


def validate_reading(temperature, humidity):
    if not isinstance(temperature, (int, float)) or not isinstance(humidity, (int, float)):
        return False
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        return False
    if not (HUM_MIN <= humidity <= HUM_MAX):
        return False
    return True


def read_sensor_data(logger):
    global _sensor
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature, humidity = simulate_dht22_reading()
            if validate_reading(temperature, humidity):
                return temperature, humidity
            else:
                logger.warning(
                    f"Invalid reading (T={temperature}, H={humidity}). "
                    f"Retrying ({attempt}/{MAX_RETRIES})."
                )
        except Exception as e:
            logger.error(f"Unexpected error during simulation: {e}. "
                         f"Retrying ({attempt}/{MAX_RETRIES}).")
        if attempt < MAX_RETRIES:
            time.sleep(1)
    logger.error(f"Failed to get valid reading after {MAX_RETRIES} attempts.")
    return None, None


def log_data(logger, temperature, humidity):
    if temperature is not None and humidity is not None:
        logger.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
    else:
        logger.error("Failed to log data due to invalid sensor reading.")


def signal_handler(signum, frame):
    global _running
    _running = False


def cleanup():
    global _sensor
    if _sensor is not None:
        try:
            _sensor.close()
        except Exception:
            pass
        _sensor = None
    logging.shutdown()


def main():
    global _sensor, _running
    logger = setup_logging()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        _sensor = DigitalInputDevice(DHT_PIN, pull_up=True)
        logger.info(f"DHT22 sensor initialized on GPIO{DHT_PIN}.")
    except Exception as e:
        logger.error(f"Failed to initialize GPIO{DHT_PIN}: {e}")
        sys.exit(1)
    try:
        while _running:
            temperature, humidity = read_sensor_data(logger)
            log_data(logger, temperature, humidity)
            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        logger.info("Program terminated.")


if __name__ == "__main__":
    main()

