import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: pip install RPi.GPIO")
    sys.exit(1)

LED_PIN = 17
led_state = False

def cleanup_gpio():
    """Drive the LED low and release GPIO resources safely."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global led_state
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        cleanup_gpio()
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on' to turn LED on, 'off' to turn LED off, or 'exit' to quit: ").strip().lower()
            except EOFError:
                print("\nInput stream closed. Exiting.")
                break

            if user_input == "on":
                led_state = True
                GPIO.output(LED_PIN, GPIO.HIGH)
                print(f"LED is {'ON' if led_state else 'OFF'}")
            elif user_input == "off":
                led_state = False
                GPIO.output(LED_PIN, GPIO.LOW)
                print(f"LED is {'ON' if led_state else 'OFF'}")
            elif user_input == "exit":
                print("Exiting program.")
                break
            else:
                print("Invalid input")

            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

