def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in SENSOR_PINS:
            try:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            except Exception as e:
                print(f"Error: Failed to configure GPIO{pin} as input: {e}", file=sys.stderr)
                GPIO.cleanup()
                sys.exit(1)
    except Exception as e:
        print(f"Error: Failed to initialize GPIO: {e}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    print(f"Monitoring sensors on GPIO pins: {SENSOR_PINS} every {POLL_INTERVAL} second(s).")

    try:
        while _running:
            for pin in SENSOR_PINS:
                try:
                    if GPIO.input(pin) == GPIO.HIGH:
                        print(f"Response for sensor {SENSOR_PINS.index(pin) + 1}")
                except Exception as e:
                    print(f"Error reading GPIO{pin}: {e}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

