from requests.auth import HTTPBasicAuth

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    print("RPi.GPIO is not available. Run this script on a Raspberry Pi.")
    sys.exit(0)

SENSOR_PIN = 4
SERVER_URL = 'http://localhost:5000/sensor'
USERNAME = 'user'
PASSWORD = 'pass'
POLL_INTERVAL = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def init_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_OFF)

def read_sensor():
    try:
        return GPIO.input(SENSOR_PIN)
    except Exception as e:
        print(f"Sensor read error: {e}")
        return None

def submit_data(value):
    try:
        data = {'sensor': 'digital_input', 'value': int(value)}
        response = requests.post(
            SERVER_URL,
            json=data,
            auth=HTTPBasicAuth(USERNAME, PASSWORD),
            timeout=10
        )
        print(f"Server response: {response.status_code} - {response.text}")
    except requests.exceptions.RequestException as e:
        print(f"Request error: {e}")

def main():
    signal.signal(signal.SIGTERM, _handle_signal)
    init_gpio()
    print("GPIO initialized. Starting polling loop...")
    try:
        while _running:
            val = read_sensor()
            if val is not None:
                submit_data(val)
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == '__main__':
    main()

