import sys
import time
import threading
import signal
import atexit

try:
    import DOG
    _DOG_AVAILABLE = True
except ImportError:
    _DOG_AVAILABLE = False

_running = True
_receive_thread = None
_receive_lock = threading.Lock()
_log_file = None
_log_file_name = None
_api_started = False


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _api_started
    if _api_started:
        try:
            DOG.api()
        except Exception:
            pass
        _api_started = False
    if _receive_thread is not None and _receive_thread.is_alive():
        _receive_thread.join(timeout=2.0)
    if _log_file is not None:
        try:
            _log_file.close()
        except Exception:
            pass
    _log_file = None
    _log_file_name = None


def _receive_loop():
    global _running, _log_file, _log_file_name
    while _running:
        try:
            data = DOG.receive()
            if data is not None:
                try:
                    with _receive_lock:
                        if _log_file is not None:
                            _log_file.write(str(data) + "\n")
                except Exception as e:
                    print(f"Error writing to log file: {e}", file=sys.stderr)
        except Exception as e:
            print(f"Error receiving data: {e}", file=sys.stderr)
        time.sleep(0.1)


def _start_receive(filename):
    global _log_file, _log_file_name, _api_started, _receive_thread
    if _api_started:
        print("API already started.", file=sys.stderr)
        return
    if not _DOG_AVAILABLE:
        print("DOG library not available.", file=sys.stderr)
        return
    try:
        _log_file = open(filename, "w")
        _log_file_name = filename
        _api_started = True
        _receive_thread = threading.Thread(target=_receive_loop, daemon=True)
        _receive_thread.start()
        print(f"Started receiving data to {filename}")
    except Exception as e:
        print(f"Error starting receive: {e}", file=sys.stderr)
        _api_started = False
        _receive_thread = None
        _log_file = None
        _log_file_name = None


def _stop_receive():
    global _running, _api_started, _receive_thread
    _running = False
    _api_started = False
    if _receive_thread is not None and _receive_thread.is_alive():
        _receive_thread.join(timeout=2.0)
    _receive_thread = None


def _help(args):
    if len(args) < 2:
        print("Available commands: help, display, send, write, exit")
        print("Usage: help <command>")
        return
    cmd = args[1]
    help_text = {
        "help": "Display help information for a specific command",
        "display": "Display the current log file contents",
        "send": "Send data via DOG.send()",
        "write": "Write data directly to the log file",
        "exit": "Exit the program",
        "start": "Start receiving data to a file",
    }.get(cmd, "No help found for this command.")
    if help_text:
        print(help_text)
    else:
        print(f"No help found for command: {cmd}")


def _display():
    global _log_file, _log_file_name
    if _log_file is None:
        print("No log file opened.", file=sys.stderr)
        return
    try:
        with _receive_lock:
            with open(_log_file_name, "r") as f:
                print(f.read(), end="")
    except Exception as e:
        print(f"Error displaying log: {e}", file=sys.stderr)


def _send(args):
    if not _api_started:
        print("API not started. Use 'start ' first.", file=sys.stderr)
        return
    if len(args) < 2:
        print("Usage: send <data>")
        return
    data = " ".join(args[1:])
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}", file=sys.stderr)


def _write(args):
    global _log_file, _log_file_name
    if _log_file is None:
        print("No log file opened.", file=sys.stderr)
        return
    if len(args) < 2:
        print("Usage: write <data>")
        return
    data = " ".join(args[1:])
    try:
        with _receive_lock:
            with open(_log_file_name, "a") as f:
                f.write(data + "\n")
    except Exception as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def _exit():
    global _running, _api_started, _receive_thread
    _running = False
    _api_started = False
    if _receive_thread is not None and _receive_thread.is_alive():
        _receive_thread.join(timeout=2.0)
    _receive_thread = None
    if _log_file is not None:
        try:
            _log_file.close()
        except Exception:
            pass
    _log_file = None
    _log_file_name = None
    print("Exiting program.")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    atexit.register(_cleanup)
    while _running:
        try:
            args = input("JAYES@ROVER53:\t").split()
            if not args:
                continue
            cmd = args[0].lower()
            if cmd == "help":
                _help(args)
            elif cmd == "display":
                _display()
            elif cmd == "send":
                _send(args)
            elif cmd == "write":
                _write(args)
            elif cmd == "exit":
                _exit()
            elif cmd == "start":
                if len(args) < 2:
                    print("Usage: start ")
                    continue
                _start_receive(args[1])
            else:
                print(f"Unknown command: {cmd}")
        except EOFError:
            break
        except Exception as e:
            print(f"An unexpected error occurred: {e}", file=sys.stderr)
    _cleanup()


if __name__ == "__main__":
    main()

