DEFAULT_KEYWORD_SPOTTING_SENSITIVITY = 0.5
DEFAULT_SENTIMENT_ANALYSIS_WINDOW = 5
DEFAULT_LED_PIN = 17
DEFAULT_HEARTBEAT_INTERVAL = 60
DEFAULT_LOG_INTERVAL = 60
DEFAULT_RESOURCE_MONITOR_INTERVAL = 60
DEFAULT_CHECK_CONFIG_INTERVAL = 300
DEFAULT_CLOUD_ENDPOINT = "http://localhost:5000/api/v1/alerts"

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class ConfigurationError(Exception):
    pass


class AudioError(Exception):
    pass


class ModelError(Exception):
