class ResourceMonitor:
    def __init__(self, interval: int = DEFAULT_RESOURCE_MONITOR_INTERVAL):
        self.interval = interval
        self.cpu_usage = deque(maxlen=10)
        self.memory_usage = deque(maxlen=10)
        self.start_time = time.time()
        self.current_cpu = 0.0
        self.current_memory = 0.0
        self._running = True

    def monitor(self):
        while self._running:
            try:
                cpu_usage = os.getloadavg()[0]
                memory_usage = self._get_memory_usage()
                self.cpu_usage.append(cpu_usage)
                self.memory_usage.append(memory_usage)
                logger.info(
                    f"CPU Usage: {self.cpu_usage[-1]:.2f}%, Memory Usage: {self.memory_usage[-1]:.2f}%"
                )
                if time.time() - self.start_time >= self.interval:
                    avg_cpu = sum(self.cpu_usage) / len(self.cpu_usage)
                    avg_memory = sum(self.memory_usage) / len(self.memory_usage)
                    logger.info(
                        f"Average CPU Usage: {avg_cpu:.2f}%, Average Memory Usage: {avg_memory:.2f}%"
                    )
                    self.start_time = time.time()
            except Exception as e:
                logger.error(f"Error monitoring resources: {e}")
            try:
                asyncio.get_event_loop().run_until_complete(asyncio.sleep(self.interval))
            except RuntimeError:
                self._running = False

    def _get_memory_usage(self) -> float:
        try:
            import psutil
            return psutil.virtual_memory().percent
        except Exception:
            return 0.0


class HeartbeatManager:
    def __init__(self, interval: int = DEFAULT_HEARTBEAT_INTERVAL):
        self.interval = interval
        self.last_heartbeat = time.time()
        self._running = True

    def send_heartbeat(self, config: dict) -> None:
        try:
            endpoint = config.get("cloud", {}).get("endpoint")
            if endpoint:
                data = {"status": "alive", "timestamp": time.time()}
                asyncio.get_event_loop().run_until_complete(
                    asyncio.sleep(0)
                )
                import aiohttp
                async with aiohttp.ClientSession() as session:
                    async with session.post(endpoint, json=data) as resp:
                        if resp.status != 200:
                            logger.warning(
                                f"Heartbeat failed with status {resp.status}"
                            )
        except Exception as e:
            logger.error(f"Error sending heartbeat: {e}")

    async def heartbeat_task(self, config: dict) -> None:
        while self._running:
            await asyncio.sleep(self.interval)
            if time.time() - self.last_heartbeat >= self.interval:
                self.send_heartbeat(config)
                self.last_heartbeat = time.time()

    def start(self, config: dict) -> None:
        asyncio.create_task(self.heartbeat_task(config))


class ConfigManager:
    def __init__(self, config_file: str = DEFAULT_CONFIG_FILE):
        self.config_file = config_file
        self.config: dict = {}
        self.load_config()

    def load_config(self) -> None:
        try:
            with open(self.config_file, "r") as f:
                self.config = json.load(f)
            logger.info("Configuration loaded successfully.")
        except FileNotFoundError:
            raise ConfigurationError(f"Configuration file not found: {self.config_file}")
        except json.JSONDecodeError as e:
            raise ConfigurationError(f"Invalid JSON format in configuration file: {e}")
        except Exception as e:
            raise ConfigurationError(f"Error loading configuration: {e}")

    def save_config(self) -> None:
