class KeywordSpotting:
    def __init__(self, config: dict):
        self.config = config
        self.keywords: List[str] = self.config.get("keywords", [])
        self.sensitivity: float = self.config.get("keyword_spotting_sensitivity", DEFAULT_KEYWORD_SPOTTING_SENSITIVITY)
        self.threshold: float = self.config.get("keyword_spotting_threshold", 0.5)
        self.interpreter: Optional[tflite.Interpreter] = None
        self.input_details: List[tflite.Tensor] = []
        self.output_details: List[tflite.Tensor] = []
        self.load_model()

    def load_model(self) -> None:
        if tflite is None:
            raise ModelError("tflite_runtime not installed")
        model_path = self.config.get("model", "model.tflite")
        if not os.path.exists(model_path):
            raise ModelError(f"Model file not found: {model_path}")
        try:
            self.interpreter = tflite.Interpreter(model_path=model_path)
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            logger.info("Keyword spotting model loaded successfully.")
        except Exception as e:
            raise ModelError(f"Error loading keyword spotting model: {e}")

    def preprocess_audio(self, audio_data: np.ndarray) -> np.ndarray:
        audio_data = audio_data.astype(np.float32)
        audio_data = (audio_data / 32768.0) * 2.0
        audio_data = audio_data - 1.0
        return audio_data

    def predict(self, audio_data: np.ndarray) -> Tuple[np.ndarray, float]:
        audio_data = self.preprocess_audio(audio_data)
        input_data = np.expand_dims(audio_data, axis=0)
        self.interpreter.set_tensor(self.input_details[0]["index"], input_data)
        self.interpreter.invoke()
        output_data = self.interpreter.get_tensor(self.output_details[0]["index"])
        return output_data[0], float(output_data[1])

    def postprocess(self, output_data: np.ndarray, threshold: float) -> Tuple[str, float]:
        keyword_index = np.argmax(output_data)
        confidence = float(output_data[keyword_index])
        if confidence > self.threshold:
            return self.keywords[keyword_index], confidence
        return None, 0.0


class SentimentAnalysis:
    def __init__(self, config: dict):
        self.config = config
        self.sentiment_window: List[float] = deque(maxlen=DEFAULT_SENTIMENT_ANALYSIS_WINDOW)
        self.sentiment_thresholds: Dict[str, float] = {
            "positive": self.config.get("sentiment_analysis_positive_threshold", 0.7),
            "negative": self.config.get("sentiment_analysis_negative_threshold", 0.3),
        }
        self.sentiment_history: List[float] = deque(maxlen=DEFAULT_SENTIMENT_ANALYSIS_WINDOW)

    def analyze_sentiment(self, text: str) -> Tuple[float, float]:
        sentiment_score = 0.0
        sentiment_probability = 0.0
        if text:
            sentiment_score, sentiment_probability = 1.0, 0.5
        self.sentiment_window.append(sentiment_score)
        self.sentiment_history.append(sentiment_probability)
        return sentiment_score, sentiment_probability

    def check_sentiment(self) -> None:
        positive_sentiment = sum(self.sentiment_history) / len(self.sentiment_history) if self.sentiment_history else 0.0
        negative_sentiment = -sum(self.sentiment_history) / len(self.sentiment_history) if self.sentiment_history else 0.0
        if (positive_sentiment > self.sentiment_thresholds["positive"] and "positive" not in self.config.get("commands", [])):
            logger.info("Positive sentiment detected.")
            self.trigger_alert("Positive sentiment detected.")
        elif (negative_sentiment < self.sentiment_thresholds["negative"] and "negative" not in self.config.get("commands", [])):
            logger.info("Negative sentiment detected.")
            self.trigger_alert("Negative sentiment detected.")

    def trigger_alert(self, message: str) -> None:
        alert_type = self.config.get("alert_type", "led")
        if alert_type == "led":
            self.led.on()
            logger.info(f"LED alert triggered: {message}")
            asyncio.create_task(self.send_cloud_alert(message))
        elif alert_type == "cloud":
            self.send_cloud_alert(message)
        else:
            logger.warning(f"Invalid alert type: {alert_type}")

    async def send_cloud_alert(self, message: str) -> None:
        endpoint = self.config.get("cloud", {}).get("endpoint")
        if endpoint:
            data = {"status": "alert", "message": message, "timestamp": time.time()}
            import aiohttp
            async with aiohttp.ClientSession() as session:
                async with session.post(endpoint, json=data) as resp:
                    if resp.status != 200:
                        logger.warning(f"Cloud alert failed with status {resp.status}")


class VoiceActivityDetector:
    def __init__(self, sample_rate: int = DEFAULT_SAMPLE_RATE):
        self.sample_rate = sample_rate
        self.threshold: float = self.config.get("voice_activity_threshold", 0.1)
        self.running = True

    def detect_voice(self, audio_data: np.ndarray) -> Tuple[bool, float]:
        energy = np.sum(audio_data ** 2) / len(audio_data)
        return energy > self.threshold, energy

    def record_audio(self, duration: int = 5) -> Tuple[np.ndarray, float]:
        try:
            logger.info(f"Recording audio for {duration} seconds...")
            audio_data = sf.read(sd.rec(int(duration * self.sample_rate), samplerate=self.sample_rate, channels=1), dtype="float32")[0]
            logger.info("Audio recording complete.")
            return audio_data, float(self.sample_rate)
        except Exception as e:
            logger.error(f"Error recording audio: {e}")
            return None, 0.0

    def run(self) -> None:
        while self.running:
            try:
                audio_data, sample_rate = self.record_audio()
                if audio_data is not None:
                    voice_detected, energy = self.detect_voice(audio_data)
                    if voice_detected:
                        logger.info("Voice activity detected.")
                        self.process_audio(audio_data)
            except Exception as e:
                logger.error(f"Error in voice activity detection: {e}")
            try:
                asyncio.get_event_loop().run_until_complete(asyncio.sleep(0.1))
            except RuntimeError:
                self.running = False

    def process_audio(self, audio_data: np.ndarray) -> None:
        try:
            audio_data = self.preprocess_audio(audio_data)
            keyword_spotting_model = KeywordSpotting(self.config)
            sentiment_analysis = SentimentAnalysis(self.config)
            sentiment_score, sentiment_probability = sentiment_analysis.analyze_sentiment(self.config.get("text", ""))
            sentiment_analysis.check_sentiment()
            audio_data, _ = keyword_spotting_model.predict(audio_data)
            keyword, confidence = keyword_spotting_model.postprocess(audio_data, self.threshold)
            if keyword:
                logger.info(f"Keyword detected: {keyword} with confidence {confidence:.2f}")
                sentiment_analysis.trigger_alert(f"Keyword detected: {keyword}")
        except Exception as e:
            logger.error(f"Error processing audio: {e}")


class CloudAlertManager:
    def __init__(self, config: dict):
        self.config = config
        self.alert_queue: List[str] = []
        self.alert_queue_lock = asyncio.Lock()
        self.check_config_interval = self.config.get("check_config_interval", DEFAULT_CHECK_CONFIG_INTERVAL)

    async def check_config_updates(self) -> None:
        while True:
            try:
                await asyncio.sleep(self.check_config_interval)
                await self.load_config_from_cloud()
            except Exception as e:
                logger.error(f"Error checking for config updates: {e}")

    async def load_config_from_cloud(self) -> None:
        endpoint = self.config.get("cloud", {}).get("endpoint")
        if endpoint:
            try:
                import aiohttp
                async with aiohttp.ClientSession() as session:
                    async with session.get(endpoint) as resp:
                        if resp.status == 200:
                            new_config = await resp.json()
                            self.config.update(new_config)
                            logger.info("Configuration updated from cloud.")
                        else:
                            logger.warning("No new configuration available from cloud.")
            except Exception as e:
                logger.error(f"Error loading configuration from cloud: {e}")

    async def send_alerts_to_cloud(self) -> None:
        while True:
            try:
                with self.alert_queue_lock:
                    if self.alert_queue:
                        await self.send_alert_to_cloud(self.alert_queue.pop(0))
                await asyncio.sleep(1)
            except Exception as e:
                logger.error(f"Error sending alerts to cloud: {e}")

    async def send_alert_to_cloud(self, alert: str) -> None:
        endpoint = self.config.get("cloud", {}).get("endpoint")
        if endpoint:
            try:
                import aiohttp
                async with aiohttp.ClientSession() as session:
                    async with session.post(endpoint, json={"status": "alert", "message": alert}) as resp:
                        if resp.status != 200:
                            logger.warning(f"Failed to send alert to cloud. Status code: {resp.status}")
            except Exception as e:
                logger.error(f"Error sending alert to cloud: {e}")
                self.alert_queue.append(alert)

    def start(self) -> None:
        asyncio.create_task(self.check_config_updates())
        asyncio.create_task(self.send_alerts_to_cloud())


async def main() -> None:
    parser = argparse.ArgumentParser(description="Voice-Controlled Smart Home Hub")
    parser.add_argument("--config", default=DEFAULT_CONFIG_FILE, help="Path to the configuration file")
    parser.add_argument("--log_file", default=DEFAULT_LOG_FILE, help="Path to the log file")
    parser.add_argument("--log_level", default=DEFAULT_LOG_LEVEL, help="Logging level (DEBUG, INFO, WARNING, ERROR, CRITICAL)")
    parser.add_argument("--sample_rate", type=int, default=DEFAULT_SAMPLE_RATE, help="Audio sample rate in Hz")
    parser.add_argument("--keyword_spotting_sensitivity", type=float, default=DEFAULT_KEYWORD_SPOTTING_SENSITIVITY, help="Sensitivity for keyword spotting")
    parser.add_argument("--sentiment_analysis_window", type=int, default=DEFAULT_SENTIMENT_ANALYSIS_WINDOW, help="Size of the sentiment analysis window")
    parser.add_argument("--led_pin", type=int, default=DEFAULT_LED_PIN, help="GPIO pin for the LED indicator")
    parser.add_argument("--heartbeat_interval", type=int, default=DEFAULT_HEARTBEAT_INTERVAL, help="Interval for sending heartbeat signals")
    parser.add_argument("--log_interval", type=int, default=DEFAULT_LOG_INTERVAL, help="Interval for logging resource usage")
    parser.add_argument("--resource_monitor_interval", type=int, default=DEFAULT_RESOURCE_MONITOR_INTERVAL, help="Interval for monitoring system resources")
    parser.add_argument("--check_config_interval", type=int, default=DEFAULT_CHECK_CONFIG_INTERVAL, help="Interval for checking the configuration file for updates")
    parser.add_argument("--cloud_endpoint", default=DEFAULT_CLOUD_ENDPOINT, help="Endpoint for the cloud service")
    args = parser.parse_args()

    log_level = getattr(logging, args.log_level.upper(), None)
    if not isinstance(log_level, int):
        raise ValueError(f"Invalid log level: {args.log_level}")
    logger.setLevel(log_level)

    config_manager = ConfigManager(args.config)
    config = config_manager.config

    try:
        led = LED(args.led_pin)
    except Exception as e:
        logger.error(f"Error initializing LED on GPIO pin {args.led_pin}: {e}")
        sys.exit(1)

    voice_activity_detector = VoiceActivityDetector(args.sample_rate)
    keyword_spotting = KeywordSpotting(config)
    sentiment_analysis = SentimentAnalysis(config)
    cloud_alert_manager = CloudAlertManager(config)

    heartbeat_manager = HeartbeatManager(args.heartbeat_interval)
    heartbeat_manager.start(config)

    resource_monitor = ResourceMonitor(args.resource_monitor_interval)
    resource_monitor.start()

    try:
        await asyncio.gather(
            voice_activity_detector.run(),
            resource_monitor.monitor(),
        )
    except asyncio.CancelledError:
        logger.info("Tasks cancelled, shutting down...")
    finally:
        logger.info("Shutting down...")
        try:
            led.close()
        except Exception:
            pass
        logger.info("Cleanup complete.")


