import signal
import sys
import time
import logging

import board
import busio
from adafruit_tsl2561 import TSL2561
from adafruit_circuitpython_lsm303_accel import LSM303_Accel
from adafruit_blinka.microcontroller.bcm283x.pin import D18

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("light_led")

PWM_PIN = D18
PWM_FREQ = 1000
UPDATE_INTERVAL = 1.0

_running = True
_pwm = None

def _handle_signal(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False

def init_sensor():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        log.error("Failed to initialise I2C bus: %s", exc)
        return None

    try:
        sensor = TSL2561(i2c)
        sensor.gain = TSL2561.GAIN_1X
        sensor.integration_time = TSL2561.INTEGRATIONTIME_100MS
        log.info("TSL2561 initialised (gain=1x, integration=100ms).")
        return sensor
    except Exception as exc:
        log.error("TSL2561 not found on the I2C bus: %s", exc)
        return None

def read_lux(sensor):
    try:
        lux = sensor.lux
        if lux is None:
            log.warning("Sensor returned None for lux.")
            return None
        return float(lux)
    except Exception as exc:
        log.error("Error reading lux: %s", exc)
        return None

def lux_to_brightness(lux):
    if lux is None:
        return 0
    return int(round((lux / 1000.0) * 255))

def main():
    global _pwm

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = init_sensor()
    if sensor is None:
        log.error("Cannot continue without a working sensor.")
        sys.exit(1)

    try:
        _pwm = PWM_PIN.PWM(PWM_PIN, PWM_FREQ)
        _pwm.start(0)
    except Exception as exc:
        log.error("Failed to initialise PWM on GPIO%d: %s", PWM_PIN.number, exc)
        sys.exit(1)

    brightness = 0
    last_lux = 0.0

    try:
        while _running:
            lux = read_lux(sensor)
            if lux is not None:
                last_lux = lux
                brightness = lux_to_brightness(lux)
                log.info("Lux: %.2f  Brightness: %d", last_lux, brightness)
            else:
                log.warning("Sensor read failed – retaining previous brightness (%d).", brightness)

            time.sleep(UPDATE_INTERVAL)
    finally:
        if _pwm is not None:
            try:
                _pwm.stop()
            except Exception:
                pass
        log.info("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

