import signal
import sys
import logging
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    import gpiozero
    from gpiozero import LED
    _GPIOZERO_AVAILABLE = True
except ImportError:
    _GPIOZERO_AVAILABLE = False

LED_PIN = 17
PORT = 8080

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')

led = None
httpd = None

class WebPage(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/':
            self._return_index()
        elif self.path == '/light_on':
            self._handle_light_on()
        elif self.path == '/light_off':
            self._handle_light_off()
        else:
            self._return_error('404 Not Found')

    def _return_index(self):
        body = (
            '<html><head><title>Raspberry Pi Web Control</title></head>'
            '<body><h1>Raspberry Pi Web Control</h1>'
            '<p><a href="/light_on">Turn LED On</a> | '
            '<a href="/light_off">Turn LED Off</a></p>'
            '</body></html>'
        )
        self._return_text(body, 200)

    def _return_text(self, text, status_code=200):
        self.send_response(status_code)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Length', str(len(text)))
        self.end_headers()
        self.wfile.write(text.encode('utf-8'))

    def _return_error(self, message):
        body = (
            '<html><head><title>Error</title></head>'
            '<body><h1>Error</h1><p>{}</p></body></html>'
        ).format(message)
        self._return_text(body, 404)

    def _handle_light_on(self):
        global led
        if led is None:
            self._return_error('LED not initialized')
        try:
            led.on()
            status = 'LED is ON'
        except Exception as e:
            self._return_error(f'Failed to turn LED on: {e}')
        body = (
            '<html><head><title>LED On</title></head>'
            '<body><h1>LED On</h1><p><a href="/light_off">Turn LED Off</a></p>'
            '<p>Status: {}</p></body></html>'
        ).format(status)
        self._return_text(body, 200)

    def _handle_light_off(self):
        global led
        if led is None:
            self._return_error('LED not initialized')
        try:
            led.off()
            status = 'LED is OFF'
        except Exception as e:
            self._return_error(f'Failed to turn LED off: {e}')
        body = (
            '<html><head><title>LED Off</title></head>'
            '<body><h1>LED Off</h1><p><a href="/light_on">Turn LED On</a></p>'
            '<p>Status: {}</p></body></html>'
        ).format(status)
        self._return_text(body, 200)

def cleanup(signum=None, frame=None):
    global led, httpd
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)

def main():
    global led, httpd
    if not _GPIOZERO_AVAILABLE:
        logging.warning('gpiozero not installed; LED control disabled')
    else:
        try:
            led = LED(LED_PIN)
            logging.info('LED initialized on GPIO %d', LED_PIN)
        except Exception as e:
            logging.error('Failed to initialize LED on GPIO %d: %s', LED_PIN, e)
            led = None

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        httpd = HTTPServer(('0.0.0.0', PORT), WebPage)
        logging.info('Server listening on 0.0.0.0:%d', PORT)
        while True:
            httpd.handle_request()
    except Exception as e:
        logging.error('Server error: %s', e)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

