import signal
import sys
import time
from threading import Lock

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)


class OutputPin:
    """Generic output pin with value validation and shutdown support."""

    def __init__(self, pin_number, pin_name, initial_value=0, allowed_values=(0, 1)):
        if initial_value not in allowed_values:
            raise ValueError(f"Initial value must be one of {allowed_values}, got {initial_value}")
        self.pin_number = pin_number
        self.pin_name = pin_name
        self.value = initial_value
        self.lock = Lock()
        self._initialized = False
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.pin_number, GPIO.OUT, initial=GPIO.LOW)
            self._initialized = True
        except Exception as e:
            raise RuntimeError(f"Failed to initialize GPIO pin {self.pin_number} ({self.pin_name}): {e}") from e

    def set_value(self, value):
        if value not in self.allowed_values:
            raise ValueError(f"Value must be one of {self.allowed_values}, got {value}")
        with self.lock:
            self.value = value
            try:
                GPIO.output(self.pin_number, GPIO.HIGH if value else GPIO.LOW)
            except Exception as e:
                raise RuntimeError(f"Failed to write to GPIO pin {self.pin_number}: {e}") from e

    def get_value(self):
        with self.lock:
            return self.value

    def shutdown(self):
        if self._initialized:
            try:
                GPIO.setup(self.pin_number, GPIO.IN)
            except Exception as e:
                print(f"Warning: failed to revert pin {self.pin_number} to input: {e}", file=sys.stderr)
            self._initialized = False


class TriggerPin(OutputPin):
    """Output pin that can generate a short high pulse."""

    def __init__(self, pin_number, pin_name, initial_value=0, pulse_high=True, allowed_values=(0, 1)):
        super().__init__(pin_number, pin_name, initial_value, allowed_values)
        self.pulse_high = pulse_high
        self.trigger_lock = Lock()
        self.set_value(initial_value)

    def trigger(self):
        with self.trigger_lock:
            current_value = self.get_value()
            if self.pulse_high != (current_value == GPIO.HIGH):
                self.set_value(1)
            else:
                self.set_value(0)


_pins = []


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    for pin in _pins:
        pin.shutdown()
    GPIO.cleanup()
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        example_output = OutputPin(21, "ExampleOutput", initial_value=0)
        example_trigger = TriggerPin(20, "ExampleTrigger", initial_value=0, pulse_high=True)
        _pins.extend([example_output, example_trigger])

        print(f"Output pin: {example_output.pin_name} (BCM {example_output.pin_number}) value={example_output.get_value()}")
        print(f"Trigger pin: {example_trigger.pin_name} (BCM {example_trigger.pin_number}) value={example_trigger.get_value()}")

        example_trigger.trigger()
        time.sleep(0.1)

        print(f"Output pin: {example_output.pin_name} (BCM {example_output.pin_number}) value={example_output.get_value()}")
        print(f"Trigger pin: {example_trigger.pin_name} (BCM {example_trigger.pin_number}) value={example_trigger.get_value()}")

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        for pin in _pins:
            pin.shutdown()
        GPIO.cleanup()


if __name__ == "__main__":
    main()

