import signal
import sys
import time
import logging
from typing import Callable, Optional

import zmq

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

logger = logging.getLogger(__name__)


class PIDHandler:
    """
    Handles PID control logic, error output, and watchdog functionality.

    Attributes:
        error_output_pin: BCM GPIO pin number for the error output (PWM or digital).
        error_output_is_pwm: True if the error output pin is PWM, False if digital.
        watchdog_timeout: Timeout (seconds) for the watchdog timer.
        last_msg_time: Timestamp of the last received message.
        global_err_state: Current global error state.
        subscribe: Callback function for subscribing to data.
        unsubscribe: Callback function for unsubscribing from data.
    """

    def __init__(
        self,
        error_output_pin: int = 18,
        error_output_is_pwm: bool = True,
        watchdog_timeout: int = 20,
    ) -> None:
        self.error_output_pin = error_output_pin
        self.error_output_is_pwm = error_output_is_pwm
        self.watchdog_timeout = watchdog_timeout
        self.last_msg_time: float = time.time()
        self.global_err_state = False
        self.subscribe: Optional[Callable[[], None]] = None
        self.unsubscribe: Optional[Callable[[], None]] = None
        self.context: Optional[zmq.Context] = None
        self.socket: Optional[zmq.Socket] = None
        self._initialized = False
        self._pwm: Optional[object] = None

        self._setup_logging()
        self._setup_gpio()
        self._setup_zmq()

    def _setup_logging(self) -> None:
        logging.basicConfig(
            level=logging.INFO,
            format="%(asctime)s - %(levelname)s - %(message)s",
        )

    def _setup_gpio(self) -> None:
        if GPIO is None:
            logger.error("RPi.GPIO module not available; running in stub mode.")
            return
        try:
            GPIO.setmode(GPIO.BOARD)
            GPIO.setwarnings(False)
            GPIO.setup(self.error_output_pin, GPIO.OUT)
            if self.error_output_is_pwm:
                self._pwm = GPIO.PWM(self.error_output_pin, 1000)
                self._pwm.start(0.0)
            else:
                GPIO.output(self.error_output_pin, GPIO.LOW)
            self._initialized = True
            logger.info(
                "GPIO initialized: pin %d (BOARD) as error output (PWM=%s).",
                self.error_output_pin,
                self.error_output_is_pwm,
            )
        except Exception as e:
            logger.error("Failed to initialize GPIO: %s", e)
            self._initialized = False

    def _setup_zmq(self) -> None:
        try:
            self.context = zmq.Context.instance()
            self.socket = self.context.socket(zmq.SUB)
            self.socket.setsockopt(zmq.SUBSCRIBE, b"")
            self.socket.connect("tcp://localhost:5555")
            logger.info("ZeroMQ SUB socket connected to tcp://localhost:5555.")
        except Exception as e:
            logger.error("Failed to initialize ZeroMQ: %s", e)
            self.context = None
            self.socket = None

    def update_error_output(self, state: bool) -> None:
        if self._initialized:
            if self.error_output_is_pwm:
                self._pwm.ChangeDutyCycle(100.0 if state else 0.0)
            else:
                GPIO.output(self.error_output_pin, GPIO.HIGH if state else GPIO.LOW)
        self.global_err_state = state

    def set_error_output(self, state: bool) -> None:
        self.global_err_state = state
        self.update_error_output(state)

    def handle_message(self, message: bytes) -> None:
        if self.subscribe:
            self.subscribe()
        if self.unsubscribe:
            self.unsubscribe()
        self.last_msg_time = time.time()

    def _watchdog_check(self) -> None:
        if time.time() - self.last_msg_time > self.watchdog_timeout:
            logger.warning(
                "Watchdog timeout! No message received for %d seconds.",
                self.watchdog_timeout,
            )
            self.set_error_output(True)

    def run(self) -> None:
        if not self._initialized:
            logger.warning("PIDHandler run called but GPIO not initialized.")
            return
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        try:
            while True:
                self._watchdog_check()
                if self.socket:
                    try:
                        message = self.socket.recv_string(zmq.NOBLOCK)
                        if message:
                            self.handle_message(message)
                    except zmq.Again:
                        pass
                    except Exception as e:
                        logger.error("Error receiving message: %s", e)
                time.sleep(0.1)
        except Exception as e:
            logger.error("Unexpected error in main loop: %s", e)
        finally:
            self.cleanup()

    def _signal_handler(self, signum, frame) -> None:
        logger.info("Received signal %d, shutting down.", signum)
        self.cleanup()
        sys.exit(0)

    def cleanup(self) -> None:
        if self._initialized:
            try:
                if self._pwm is not None:
                    self._pwm.stop()
                if self.error_output_is_pwm:
                    GPIO.output(self.error_output_pin, GPIO.LOW)
                GPIO.cleanup()
                self._initialized = False
                logger.info("GPIO cleaned up.")
            except Exception as e:
                logger.error("Error during GPIO cleanup: %s", e)
        if self.context:
            try:
                self.context.term()
                self.context = None
                logger.info("ZeroMQ context terminated.")
            except Exception as e:
                logger.error("Error terminating ZeroMQ context: %s", e)


if __name__ == "__main__":
    handler = PIDHandler(error_output_pin=18, error_output_is_pwm=True, watchdog_timeout=20)
    handler.subscribe = lambda: logger.info("Subscribed.")
    handler.unsubscribe = lambda: logger.info("Unsubscribed.")
    handler.run()

