import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: pip install RPi.GPIO")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000

pwm = None

try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(FAN_PIN, GPIO.OUT)

    # Attempt hardware PWM at 25 kHz; fall back to software PWM if unavailable.
    try:
        pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception:
        pwm = None

    print(f"PWM fan control started on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    print("Enter a speed (0-100) or 'q' to quit.\n")

    while True:
        try:
            user_input = input("Enter fan speed (0-100): ").strip()
        except EOFError:
            print("\nEOF received, exiting.")
            break

        if user_input.lower() == 'q':
            print("Exiting...")
            break

        try:
            speed = float(user_input)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100, or 'q' to quit.")
            continue

        if 0 <= speed <= 100:
            if pwm is not None:
