import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)


class RotaryEncoder:
    """
    A robust rotary encoder reader for the KY-040 using RPi.GPIO.

    Wiring (BCM numbering):
      CLK  -> GPIO17 (internal pull-up)
      DT   -> GPIO18 (internal pull-up)
      SW   -> (optional, not used by this implementation)
      VCC  -> 3.3 V
      GND  -> GND

    The encoder's internal pull-ups keep the pins high when the rotary
    shaft is not shorted to either line, so the signals are active-low.
    """

    def __init__(self, clk_pin, dt_pin, callback=None, initial_value=0,
                 pull_up=True, bounce_time=0.005):
        if not callable(callback):
            raise ValueError("callback must be callable")

        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.value = initial_value
        self.bounce_time = bounce_time
        self._last_clk = GPIO.HIGH
        self._last_dt = GPIO.HIGH
        self._last_change_time = 0.0
        self._debounced_change_time = 0.0
        self._lock = None

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=pull_up)
            GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=pull_up)
        except Exception as exc:
            raise RuntimeError(f"Failed to initialize GPIO pins {self.clk_pin}/{self.dt_pin}: {exc}") from exc

        self._lock = threading.Lock()
        self._install_edge_detection()

    # ------------------------------------------------------------------
    # Edge detection
    # ------------------------------------------------------------------
    def _install_edge_detection(self):
        try:
            GPIO.add_event_detect(
                self.clk_pin, GPIO.BOTH,
                callback=self._on_edge, bouncetime=int(self.bounce_time * 1_000_000)
            )
            GPIO.add_event_detect(
                self.dt_pin, GPIO.BOTH,
                callback=self._on_edge, bouncetime=int(self.bounce_time * 1_000_000)
            )
        except Exception as exc:
            raise RuntimeError(f"Failed to add edge detection: {exc}") from exc

    def _on_edge(self, channel):
        """Called by RPi.GPIO on any edge of CLK or DT."""
        current_time = time.time()
        if current_time - self._last_change_time < self.bounce_time:
            return
        self._last_change_time = current_time

        try:
            self._process_edge(channel)
        except Exception:
            pass

    def _process_edge(self, channel):
        """Determine direction from the current CLK/DT pair and update value."""
        try:
            clk_state = GPIO.input(self.clk_pin)
            dt_state = GPIO.input(self.dt_pin)

            if clk_state != self._last_clk:
                self._last_clk = clk_state
                if dt_state != self._last_dt:
                    self._last_dt = dt_state
                    self._update_value()
                else:
                    self._debounced_change_time = time.time()
            else:
                self._debounced_change_time = 0.0

            if self._debounced_change_time > 0 and self._debounced_change_time < self.bounce_time:
                self._last_clk = clk_state
                self._last_dt = dt_state
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def get_value(self):
        with self._lock:
            return self.value

    def cleanup(self):
        try:
            GPIO.remove_event_detect(self.clk_pin)
        except Exception:
            pass
        try:
            GPIO.remove_event_detect(self.dt_pin)
        except Exception:
            pass
        try:
            GPIO.cleanup([self.clk_pin, self.dt_pin])
        except Exception:
            pass

    def _update_value(self):
        with self._lock:
            if self.callback:
                try:
                    self.callback(self.value)
                except Exception as exc:
                    print(f"Callback raised an exception: {exc}", file=sys.stderr)


# ----------------------------------------------------------------------
# Demo / smoke test
# ----------------------------------------------------------------------
def _demo_callback(value):
    print(f"Encoder value: {value}")


def main():
    encoder = None
    try:
        encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=_demo_callback, initial_value=50)
        print("Rotary encoder ready. Turn the knob (Ctrl+C to exit).")
        while True:
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
    finally:
        if encoder is not None:
            encoder.cleanup()


if __name__ == "__main__":
    main()

