import argparse
import json
import signal
import socket
import sys
import time

import smbus2

try:
    from lsm303dlhc import LSM303DLHC
except ImportError:
    print("Error: lsm303dlhc library not found. Install with: pip install lsm303dlhc", file=sys.stderr)
    sys.exit(1)

# Global state for graceful shutdown
_running = True
_i2c_bus = None
_sensor = None
_tcp_socket = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _validate_data(x, y, z, mag_x, mag_y, mag_z):
    """Validate sensor readings are within expected physical ranges."""
    if not (-32768 <= x <= 32767 and -32768 <= y <= 32767 and -32768 <= z <= 32767):
        print("Warning: Acceleration data out of range.", file=sys.stderr)
    if not (-16000 <= mag_x <= 16000 and -16000 <= mag_y <= 16000 and -16000 <= mag_z <= 16000):
        print("Warning: Magnetometer data out of range.", file=sys.stderr)


def _read_sensor_data(sensor):
    """Read raw accelerometer and magnetometer data from the LSM303DLHC."""
    try:
        accel_x, accel_y, accel_z = sensor.accelerometer()
        mag_x, mag_y, mag_z = sensor.magnetometer()
        return accel_x, accel_y, accel_z, mag_x, mag_y, mag_z
    except OSError as e:
        print(f"I2C communication error: {e}", file=sys.stderr)
        return None, None, None, None, None, None
    except Exception as e:
        print(f"Error reading sensor data: {e}", file=sys.stderr)
        return None, None, None, None, None, None


def _apply_calibration(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z,
                       accel_offset_x, accel_offset_y, accel_offset_z,
                       mag_offset_x, mag_offset_y, mag_offset_z):
    """Apply calibration offsets to sensor readings."""
    return (accel_x + accel_offset_x, accel_y + accel_offset_y, accel_z + accel_offset_z,
            mag_x + mag_offset_x, mag_y + mag_offset_y, mag_z + mag_offset_z)


def _create_data_packet(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z):
    """Create a JSON data packet with sensor readings."""
    return json.dumps({
        "accel_x": accel_x,
        "accel_y": accel_y,
        "accel_z": accel_z,
        "mag_x": mag_x,
        "mag_y": mag_y,
        "mag_z": mag_z
    })


def _send_data(data_packet, tcp_socket):
    """Send the data packet over the TCP socket."""
    try:
        tcp_socket.sendall(data_packet.encode('utf-8'))
    except socket.error as e:
        print(f"Socket send error: {e}", file=sys.stderr)


def main():
    global _i2c_bus, _sensor, _tcp_socket

    parser = argparse.ArgumentParser(description="Read LSM303DLHC sensor data and send via TCP.")
    parser.add_argument("--accel-offset-x", type=float, default=0.0, help="Calibration offset for accelerometer X.")
    parser.add_argument("--accel-offset-y", type=float, default=0.0, help="Calibration offset for accelerometer Y.")
    parser.add_argument("--accel-offset-z", type=float, default=0.0, help="Calibration offset for accelerometer Z.")
    parser.add_argument("--mag-offset-x", type=float, default=0.0, help="Calibration offset for magnetometer X.")
    parser.add_argument("--mag-offset-y", type=float, default=0.0, help="Calibration offset for magnetometer Y.")
    parser.add_argument("--mag-offset-z", type=float, default=0.0, help="Calibration offset for magnetometer Z.")
    args = parser.parse_args()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C bus
    try:
        _i2c_bus = smbus2.SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    # Initialize LSM303DLHC sensor
    try:
        _sensor = LSM303DLHC(_i2c_bus)
    except Exception as e:
        print(f"Error initializing LSM303DLHC sensor: {e}", file=sys.stderr)
        _i2c_bus.close()
        sys.exit(1)

    # Create TCP socket
    try:
        _tcp_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        _tcp_socket.settimeout(1.0)  # 1 second timeout for connection
        _tcp_socket.connect(("localhost", 5000))
    except socket.error as e:
        print(f"Socket connection error: {e}", file=sys.stderr)
        _i2c_bus.close()
        sys.exit(1)

    # Main loop
    try:
        while _running:
            accel_x, accel_y, accel_z, mag_x, mag_y, mag_z = _read_sensor_data(_sensor)

            if accel_x is not None and mag_x is not None:
                _validate_data(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z)
                corrected_accel_x, corrected_accel_y, corrected_accel_z, \
                corrected_mag_x, corrected_mag_y, corrected_mag_z = _apply_calibration(
                    accel_x, accel_y, accel_z, mag_x, mag_y, mag_z,
                    args.accel_offset_x, args.accel_offset_y, args.accel_offset_z,
                    args.mag_offset_x, args.mag_offset_y, args.mag_offset_z)

                data_packet = _create_data_packet(corrected_accel_x, corrected_accel_y, corrected_accel_z,
                                                  corrected_mag_x, corrected_mag_y, corrected_mag_z)
                _send_data(data_packet, _tcp_socket)
            else:
                print("Failed to read sensor data.", file=sys.stderr)

            time.sleep(0.01)  # 10 ms delay

    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)

    finally:
        print("Shutting down gracefully...")
        if _sensor is not None:
            try:
                _sensor.disable()  # Disable accelerometer
            except Exception as e:
                print(f"Error disabling accelerometer: {e}", file=sys.stderr)
        try:
            _sensor.magnetometer.set_sleep_mode(True)  # Put magnetometer to sleep
        except Exception as e:
            print(f"Error putting magnetometer to sleep: {e}", file=sys.stderr)
        if _i2c_bus is not None:
            try:
                _i2c_bus.close()
            except Exception as e:
                print(f"Error closing I2C bus: {e}", file=sys.stderr)
        if _tcp_socket is not None:
            try:
                _tcp_socket.close()
            except Exception as e:
                print(f"Error closing socket: {e}", file=sys.stderr)
        print("Shutdown complete.")


if __name__ == "__main__":
    main()

