import atexit
import logging
import signal
import sys
import time

try:
    from adafruit_pca9685 import PCA9685
    from adafruit_extended_bus import ExtendedI2C as I2C
except ImportError:
    print("Missing dependencies. Install with:")
    print("  pip install adafruit-circuitpython-pca9685 adafruit-circuitpython-extended-bus")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("fuchikoma")

SERVO_MIN_US = 150
SERVO_MAX_US = 600
SERVO_FREQ = 60
DEFAULT_DELAY = 0.029

_PCA9685 = None
_SERVO_CHANNELS = {
    "claw": 0,
    "lock": 1,
    "water_gun": 2,
}


class Fuchikoma:
    """
    Controls a robot arm via a PCA9685 PWM servo driver on a Raspberry Pi.

    Each servo is mapped to a channel:
      - claw: channel 0
      - lock: channel 1
      - water_gun: channel 2
    Angles are in the range -77 to 77 (microseconds).
    """

    def __init__(self, i2c_bus=1, address=0x60):
        global _PCA9685
        try:
            i2c = I2C(i2c_bus)
            _PCA9685 = PCA9685(i2c, address=address)
            _PCA9685.frequency = SERVO_FREQ
            _PCA9685.pwm_duty_cycle[0] = 0
            _PCA9685.pwm_duty_cycle[1] = 0
            _PCA9685.pwm_duty_cycle[2] = 0
            log.info("PCA9685 initialized at 0x%02X on I2C bus %d", address, i2c_bus)
        except (ValueError, OSError) as exc:
            log.error("Failed to initialize PCA9685 at 0x%02X on bus %d: %s", address, i2c_bus, exc)
            raise

    @staticmethod
    def _angle_to_us(angle):
        if not -77 <= angle <= 77:
            raise ValueError(f"Angle {angle} out of range [-77, 77]")
        return int(SERVO_MIN_US + (angle + 77) * (SERVO_MAX_US - SERVO_MIN_US) / 150)

    def move_servo(self, api_name, angle, delay=DEFAULT_DELAY):
        if _PCA9685 is None:
            raise RuntimeError("PCA9685 not initialized")
        if api_name not in _SERVO_CHANNELS:
            raise ValueError(f"Unknown servo: {api_name}")
        channel = _SERVO_CHANNELS[api_name]
        try:
            pulse_us = self._angle_to_us(angle)
            _PCA9685.pwm_duty_cycle[channel] = pulse_us
            time.sleep(delay)
            _PCA9685.pwm_duty_cycle[channel] = 0
        except (OSError, ValueError) as exc:
            log.error("I2C error moving %s: %s", api_name, exc)
            raise

    def bite(self):
        self.move_servo("claw", -75)

    def open_claw(self):
        self.move_servo("claw", 75)

    def lock(self):
        self.move_servo("lock", 75)

    def unlock(self):
        self.move_servo("lock", -75)

    def shoot(self):
        self.move_servo("water_gun", -75)
        time.sleep(0.15)

    def load_water(self):
        self.move_servo("water_gun", 75)

    def cleanup(self):
        if _PCA9685 is not None:
            try:
                for ch in _SERVO_CHANNELS.values():
                    _PCA9685.pwm_duty_cycle[ch] = 0
                log.info("All PCA9685 channels de-energized")
            except Exception as exc:
                log.warning("Error during PCA9685 cleanup: %s", exc)
            try:
                _PCA9685.deinit()
            except Exception:
                pass
            _PCA9685 = None


_arm = None


def _signal_handler(signum, frame):
    log.info("Signal %d received, shutting down", signum)
    if _arm is not None:
        _arm.cleanup()
    sys.exit(0)


def main():
    global _arm
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    atexit.register(_arm.cleanup)
    try:
        _arm = Fuchikoma()
        _arm.bite()
        _arm.open_claw()
        _arm.lock()
        _arm.unlock()
        _arm.shoot()
        _arm.load_water()
    except Exception as exc:
        log.error("Fatal error: %s", exc)
    finally:
        if _arm is not None:
            _arm.cleanup()


if __name__ == "__main__":
    main()

