import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

SERVO_PIN = 18
PWM_FREQ = 50
DUTY_MIN = 2.5
DUTY_MAX = 12.5

_running = True
_servo = None

def _signal_handler(signum, frame):
    global _running
    _running = False

def angle_to_duty(angle):
    """Map 0-180 degrees to a 50 Hz duty cycle in percent."""
    return DUTY_MIN + (angle / 180.0) * (DUTY_MAX - DUTY_MIN)

def main():
    global _servo

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _servo = PWMOutputDevice(SERVO_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Error: Failed to initialize GPIO{SERVO_PIN} for PWM: {e}", file=sys.stderr)
        sys.exit(1)

    heart_rate_readings = [62, 75, 88, 110, 95]
    try:
        for hr in heart_rate_readings:
            if not _running:
                print("\nInterrupted by signal; exiting loop early.")
                break

            needle_angle = (hr / 100.0) * 180.0
            duty = angle_to_duty(needle_angle)
            _servo.value = duty / 100.0

            print(f"Heart Rate: {hr} bpm, Servo Angle: {needle_angle:.1f} degrees")

            if _running and hr < 100:
                time.sleep(0.8)
            else:
                break

    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        if _servo is not None:
            try:
                _servo.value = 0
                _servo.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

