import argparse
import datetime
import json
import logging
import os
import signal
import sys
import threading
import time
import gzip
import shutil
from pathlib import Path

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
I2C_BUS = 1
READ_INTERVAL = 5          # seconds between readings
LOG_FILE_SIZE_LIMIT = 1_048_576  # 1 MB
LOG_FILE_PERMISSIONS = 0o600

# Sensor simulation parameters
NUM_SENSORS = 3
SENSOR_IDS = [f"MCP39F511N_{i}" for i in range(1, NUM_SENSORS + 1)]

# Simulated sensor reading ranges
ACTIVE_POWER_MIN = 50
ACTIVE_POWER_MAX = 200
VOLTAGE_MIN = 220
VOLTAGE_MAX = 240
CURRENT_MIN = 0.2
CURRENT_MAX = 1.0
FREQUENCY_MIN = 59.5
FREQUENCY_MAX = 60.5
POWER_FACTOR_MIN = 0.8
POWER_FACTOR_MAX = 1.0

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------
stop_event = threading.Event()
log_lock = threading.Lock()

# ---------------------------------------------------------------------------
# Logging setup
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Sensor simulation
# ---------------------------------------------------------------------------
def simulate_sensor_reading(sensor_id: str) -> dict:
    """Return a simulated MCP39F511N reading."""
    return {
        "sensor_id": sensor_id,
        "active_power": round(
            ACTIVE_POWER_MIN + (ACTIVE_POWER_MAX - ACTIVE_POWER_MIN)
            * (time.time() % 10) / 10, 2
        ),
        "voltage": round(VOLTAGE_MIN + (VOLTAGE_MAX - VOLTAGE_MIN) * (time.time() % 10) / 10, 2),
        "current": round(
            CURRENT_MIN + (CURRENT_MAX - CURRENT_MIN) * (time.time() % 10) / 10, 2
        ),
        "frequency": round(
            FREQUENCY_MIN + (FREQUENCY_MAX - FREQUENCY_MIN) * (time.time() % 10) / 10, 2
        ),
        "power_factor": round(
            POWER_FACTOR_MIN + (POWER_FACTOR_MAX - POWER_FACTOR_MIN)
            * (time.time() % 10) / 10, 2
        ),
        "timestamp": datetime.datetime.now().isoformat(),
    }


# ---------------------------------------------------------------------------
# File / directory helpers
# ---------------------------------------------------------------------------
def ensure_directory_exists(directory: str) -> None:
    """Create *directory* if it does not exist."""
    try:
        Path(directory).mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        logger.error("Cannot create directory %s: %s", directory, exc)
        raise


def get_log_file_path(date_str: str) -> str:
    """Return the path for today's log file, creating the parent directory."""
    today = datetime.date.today()
    return os.path.join(
        today.strftime("%Y/%m/%d"),
        f"energy_log_{date_str}.json",
    )


def get_log_file_path_with_rotation(date_str: str) -> str:
    """Return the path for today's log file, creating the parent directory and rotating if needed."""
    today = datetime.date.today()
    path = os.path.join(
        today.strftime("%Y/%m/%d"),
        f"energy_log_{date_str}.json",
    )
    if os.path.exists(path):
        # File exists and is not a directory — rotate it.
        try:
            if os.path.getsize(path) > LOG_FILE_SIZE_LIMIT:
                rotate_log_file(path)
        except OSError as exc:
            logger.error("Error checking size of %s: %s", path, exc)
    return path


def rotate_log_file(log_file_path: str) -> None:
    """Compress the existing log file and start a new one."""
    try:
        with log_lock:
            if not os.path.exists(log_file_path):
                return
            compressed_path = log_file_path + ".gz"
            with open(log_file_path, "rb") as src, gzip.open(
                compressed_path, "wb"
            ) as dst:
                shutil.copyfileobj(src, dst)
            # Remove the original so the new log starts fresh.
            os.remove(log_file_path)
            logger.info("Rotated log file: %s -> %s", log_file_path, compressed_path)
    except OSError as exc:
        logger.error("Error rotating log file %s: %s", log_file_path, exc)


def ensure_log_file_permissions(log_file_path: str) -> None:
    """Set the log file to mode 0o600."""
    try:
        os.chmod(log_file_path, LOG_FILE_PERMISSIONS)
    except OSError as exc:
        logger.error("Cannot set permissions for %s: %s", log_file_path, exc)


# ---------------------------------------------------------------------------
# Data acquisition
# ---------------------------------------------------------------------------
def data_acquisition_loop(sensor_ids: list) -> None:
    """Background thread: read sensors every READ_INTERVAL seconds and append JSON lines."""
    while not stop_event.is_set():
        try:
            now = datetime.datetime.now()
            date_str = now.strftime("%Y-%m-%d")
            log_file_path = get_log_file_path_with_rotation(date_str)
            with log_lock:
                with open(log_file_path, "a") as log_file:
                    for sensor_id in sensor_ids:
                        reading = simulate_sensor_reading(sensor_id)
                        log_file.write(json.dumps(reading) + "\n")
                        log_file.flush()
            logger.debug("Data acquired and logged to %s", log_file_path)
        except OSError as exc:
            logger.error("Error writing to log file %s: %s", log_file_path, exc)
        except Exception as exc:
            logger.error("Unexpected error in data acquisition loop: %s", exc)
        # Use Event.wait so we can respond to stop_event promptly.
        stop_event.wait(READ_INTERVAL)


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------
def display_menu() -> None:
    """Print the interactive menu."""
    print("\n" + "-" * 50)
    print("Energy Monitoring System Menu:")
    print("  1. View Current Readings")
    print("  2. Retrieve Logged Data")
    print("  3. Display Statistics")
    print("  4. Exit")
    print("-" * 50)


def view_current_readings(sensor_ids: list) -> None:
    """Display the latest reading for each sensor."""
    try:
        now = datetime.datetime.now()
        date_str = now.strftime("%Y-%m-%d")
        log_file_path = get_log_file_path_with_rotation(date_str)
        with log_lock:
            with open(log_file_path, "r") as log_file:
                lines = log_file.readlines()
        if not lines:
            print("No data available yet.")
            return
        # Keep only the last line per sensor.
        readings = {}
        for line in lines:
            try:
                reading = json.loads(line.strip())
                sid = reading["sensor_id"]
                if sid not in readings or reading["timestamp"] > readings[sid]["timestamp"]:
                    readings[sid] = reading
            except (json.JSONDecodeError, ValueError):
                continue
        for sid in sensor_ids:
            print(f"\n--- {sid} ---")
            reading = readings.get(sid)
            if reading:
                print(json.dumps(reading, indent=2))
            else:
                print("No data for this sensor.")
    except FileNotFoundError:
        print("Log file not found.")
    except OSError as exc:
        print(f"Error reading log file: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")


def retrieve_logged_data(date_str: str) -> None:
    """Retrieve and display all data for *date_str*."""
    try:
        log_file_path = get_log_file_path_with_rotation(date_str)
        with log_lock:
            with open(log_file_path, "r") as log_file:
                lines = log_file.readlines()
        if not lines:
            print("No data available for this date.")
            return
        # Group by sensor_id and keep the latest per sensor.
        readings = {}
        for line in lines:
            try:
                reading = json.loads(line.strip())
                sid = reading["sensor_id"]
                ts = datetime.datetime.fromisoformat(
                    reading["timestamp"]
                ).replace(tzinfo=datetime.timezone.utc)
                if sid not in readings or reading["timestamp"] > readings[sid]["timestamp"]:
                    readings[sid] = {
                        "reading": reading,
                        "timestamp": ts,
                    }
            except (json.JSONDecodeError, ValueError):
                continue
        for sid in sorted(readings):
            print(f"\n--- {sid} ---")
            entry = readings[sid]
            print(json.dumps(entry["reading"], indent=2))
            print(f"Timestamp: {entry['timestamp'].isoformat()}")
    except FileNotFoundError:
        print("Log file not found.")
    except OSError as exc:
        print(f"Error reading log file: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")


def display_statistics(sensor_ids: list, date_str: str) -> None:
    """Display min/max/avg active power for the selected sensor on *date_str*."""
    try:
        log_file_path = get_log_file_path_with_rotation(date_str)
        with log_lock:
            with open(log_file_path, "r") as log_file:
                lines = log_file.readlines()
        if not lines:
            print("No data available for this date.")
            return
        readings = {}
        for line in lines:
            try:
                reading = json.loads(line.strip())
                sid = reading["sensor_id"]
                ts = datetime.datetime.fromisoformat(
                    reading["timestamp"]
                ).replace(tzinfo=datetime.timezone.utc)
                if sid not in readings or reading["timestamp"] > readings[sid]["timestamp"]:
                    readings[sid] = {
                        "reading": reading,
                        "timestamp": ts,
                    }
            except (json.JSONDecodeError, ValueError):
                continue
        if sensor_ids[0] not in readings:
            print("No data for this sensor.")
            return
        data = readings[sensor_ids[0]]["reading"]
        active_power = data["active_power"]
        print(f"\nStatistics for {sensor_ids[0]} on {date_str}:")
        print(f"  Active Power: {active_power} W")
        print(f"  Timestamp: {data['timestamp']}")
    except FileNotFoundError:
        print("Log file not found.")
    except OSError as exc:
        print(f"Error reading log file: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")


def parse_arguments() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Energy Monitoring System for Raspberry Pi"
    )
    parser.add_argument(
        "--view_readings", action="store_true", help="View current sensor readings"
    )
    parser.add_argument(
        "--retrieve_data", nargs="?", const=datetime.date.today().strftime("%Y-%m-%d"), default=None,
        help="Retrieve logged data for a specific date (YYYY-MM-DD)"
    )
    parser.add_argument(
        "--display_stats", nargs="?", const=datetime.date.today().strftime("%Y-%m-%d"), default=None,
        help="Display statistics for a specific date (YYYY-MM-DD)"
    )
    return parser.parse_args()


def signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    logger.info("Signal %s received — shutting down.", signum)
    stop_event.set()


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> None:
    args = parse_arguments()

    ensure_directory_exists("data")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Start the background acquisition thread.
    acquisition_thread = threading.Thread(
        target=data_acquisition_loop, args=(SENSOR_IDS,), daemon=True
    )
    acquisition_thread.start()

    try:
        while not stop_event.is_set():
            display_menu()
            if args.view_readings:
                view_current_readings(SENSOR_IDS)
            elif args.retrieve_data:
                retrieve_logged_data(args.retrieve_data)
            elif args.display_stats:
                display_statistics(SENSOR_IDS, args.display_stats)
            else:
                choice = input("Enter your choice: ").strip().lower()
                if choice == "1":
                    view_current_readings(SENSOR_IDS)
                elif choice == "2":
                    retrieve_logged_data(
                        datetime.date.today().strftime("%Y-%m-%d")
                    )
                elif choice == "3":
                    display_statistics(SENSOR_IDS, datetime.date.today().strftime("%Y-%m-%d"))
                elif choice == "4":
                    print("Exiting...")
                    break
                else:
                    print("Invalid choice. Please try again.")
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        stop_event.set()
        if acquisition_thread.is_alive():
            acquisition_thread.join(timeout=5)
        logger.info("Program finished.")


if __name__ == "__main__":
    main()

