#!/usr/bin/env python3
"""
Predictive maintenance vibration trend tracker for urban monitoring.
Reads a SW-420 digital vibration sensor on GPIO17 (BCM) and simulates amplitudes
based on the digital state. Maintains a running average and prints a health
recommendation. Includes robust error handling and clean resource release.
"""

import time
import random
import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: pip install RPi.GPIO")
    sys.exit(1)

# Configuration
VIBRATION_PIN = 17
SAMPLE_COUNT = 6
SAMPLE_INTERVAL = 0.3  # seconds
HIGH_THRESHOLD = 7.5

# Global flag for graceful shutdown
_running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def setup_gpio():
    """Configure the GPIO pin for the vibration sensor with pull-up."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VIBRATION_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        raise RuntimeError(f"GPIO setup failed: {e}")


def read_vibration_state():
    """Read the digital state of the vibration sensor.

    Returns:
        bool: True if vibration detected (pin LOW), False otherwise (pin HIGH).
    """
    try:
        return GPIO.input(VIBRATION_PIN) == GPIO.LOW
    except Exception as e:
        raise RuntimeError(f"Failed to read GPIO pin: {e}")


def simulate_amplitude():
    """Simulate a vibration amplitude based on sensor state.

    Returns:
        float: Simulated amplitude (6.0–9.0 when vibration detected, 3.0–5.0 idle).
    """
    if read_vibration_state():
        return round(random.uniform(6.0, 9.0), 1)
    else:
        return round(random.uniform(3.0, 5.0), 1)


def main():
    """Main loop: collect samples, compute average, print recommendation."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        setup_gpio()
        print("Vibration trend tracker started. Press Ctrl+C to stop.")

        sample_sums = [0.0] * SAMPLE_COUNT
        sample_indices = list(range(SAMPLE_COUNT))

        while _running:
            for i in sample_indices:
                if not _running:
                    break
                try:
                    amplitude = simulate_amplitude()
                    sample_sums[i] += amplitude
                    print(f"Sample {i+1}/{SAMPLE_COUNT}: amplitude = {amplitude}")
                except RuntimeError as e:
                    print(f"Read error: {e}")
                    continue

            if _running:
                avg_amplitude = sum(sample_sums) / len(sample_sums)
                print(f"\nAverage amplitude over {SAMPLE_COUNT} samples: {avg_amplitude:.1f}")
                if avg_amplitude > HIGH_THRESHOLD:
                    print("Maintenance recommended: wear trend is high")
                else:
                    print("Component healthy: no action needed")

            # Wait for next sample interval, but allow early exit
            for _ in range(int(SAMPLE_INTERVAL * 10)):
                if not _running:
                    break
                time.sleep(0.1)

    except RuntimeError as e:
        print(f"Runtime error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Clean up GPIO resources
        try:
            GPIO.cleanup()
            print("GPIO cleanup completed.")
        except Exception as e:
            print(f"GPIO cleanup error: {e}")
        print("Vibration trend tracker stopped.")


if __name__ == "__main__":
    main()

