        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def _handle_sigint(signum, frame):
    """Graceful shutdown on Ctrl+C."""
    global _running
    _running = False

def turn_on_leds():
    """Turn on both LEDs simultaneously."""
    try:
        GPIO.output(LED1_PIN, GPIO.HIGH)
        GPIO.output(LED2_PIN, GPIO.HIGH)
    except Exception as e:
        print(f"Error turning on LEDs: {e}", file=sys.stderr)
        raise

def turn_off_leds():
    """Turn off both LEDs simultaneously."""
    try:
        GPIO.output(LED1_PIN, GPIO.LOW)
        GPIO.output(LED2_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Error turning off LEDs: {e}", file=sys.stderr)
        raise

def toggle_leds_cycle(num_cycles=5):
    """Toggle LEDs on for 1 second, off for 1 second, repeating num_cycles times."""
    global _running
    _running = True
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED1_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(LED2_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO initialization failed: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        for cycle in range(1, num_cycles + 1):
            if not _running:
                break
            try:
                turn_on_leds()
                print(f"Cycle {cycle}/{num_cycles}: LEDs ON")
                time.sleep(1)
                if not _running:
                    break
                turn_off_leds()
                print(f"Cycle {cycle}/{num_cycles}: LEDs OFF")
                time.sleep(1)
            except Exception as e:
                print(f"Error during cycle {cycle}: {e}", file=sys.stderr)
                break
    finally:
        _cleanup()

if __name__ == "__main__":
