import time
import logging
import signal
import sys
import board
import busio
import adafruit_vl53l0x
import RPi.GPIO as GPIO

# Constants
MOTION_SENSOR_PIN = 17
BASELINE_DISTANCE_OFFSET = 50
SIMULATED_DISTANCE = 155
DEBOUNCE_TIME = 3
MAX_INIT_RETRIES = 3
INIT_RETRY_DELAY = 2
LOG_FILE = "bird_feeder.log"

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received. Stopping...")

def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        logging.info("I2C bus initialized successfully.")
        return i2c
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        return None

def initialize_vl53l0x(i2c_bus):
    try:
        vl53 = adafruit_vl53l0x.VL53L0X(i2c_bus)
        vl53.start_ranging()
        logging.info("VL53L0X sensor initialized successfully.")
        return vl53
    except Exception as e:
        logging.error(f"Failed to initialize VL53L0X sensor: {e}")
        return None

def initialize_motion_sensor(pin):
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logging.info("Motion sensor initialized successfully.")
        return GPIO.input(pin)
    except Exception as e:
        logging.error(f"Failed to initialize motion sensor: {e}")
        return None

def get_distance(vl53):
    try:
        distance = vl53.range
        if distance is None:
            logging.warning("VL53L0X returned None distance.")
            return None
        return distance
    except Exception as e:
        logging.error(f"Error reading distance: {e}")
        return None

def simulate_distance():
    return SIMULATED_DISTANCE

def establish_baseline(vl53):
    if vl53 is None:
        logging.error("VL53L0X not initialized. Cannot establish baseline.")
        return None
    for attempt in range(MAX_INIT_RETRIES):
        distance = get_distance(vl53)
        if distance is not None:
            logging.info(f"Baseline distance established: {distance} mm")
            return distance
        logging.warning(f"Attempt {attempt + 1}/{MAX_INIT_RETRIES} failed to establish baseline.")
        if attempt < MAX_INIT_RETRIES - 1:
            time.sleep(INIT_RETRY_DELAY)
    logging.error("Failed to establish baseline after multiple attempts.")
    return None

def detect_bird(vl53, baseline_distance):
    if vl53 is None:
        logging.error("VL53L0X not initialized. Cannot detect bird.")
        return
    motion_detected = False
    try:
        motion_detected = GPIO.input(MOTION_SENSOR_PIN)
    except Exception as e:
        logging.error(f"Error reading motion sensor: {e}")
        return
    if motion_detected:
        distance = simulate_distance()
        if distance is not None:
            threshold = baseline_distance - BASELINE_DISTANCE_OFFSET
            logging.info(f"Bird detected! Distance: {distance} mm, Threshold: {threshold} mm")
        else:
            logging.warning("Simulated distance is None. Skipping detection.")
    else:
        logging.debug("No motion detected.")

