    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        logging.error("Exiting due to I2C initialization failure.")
        return

    vl53 = initialize_vl53l0x(i2c_bus)
    if vl53 is None:
        logging.error("Exiting due to VL53L0X initialization failure.")
        return

    motion_sensor = initialize_motion_sensor(MOTION_SENSOR_PIN)
    if motion_sensor is None:
        logging.error("Exiting due to motion sensor initialization failure.")
        return

    baseline_distance = establish_baseline(vl53)
    if baseline_distance is None:
        logging.error("Exiting due to baseline establishment failure.")
        return

    last_detection_time = 0
    try:
        while running:
            current_time = time.time()
            if current_time - last_detection_time >= DEBOUNCE_TIME:
                detect_bird(vl53, baseline_distance)
                last_detection_time = current_time
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        try:
            vl53.stop_ranging()
            logging.info("VL53L0X ranging stopped.")
        except Exception as e:
            logging.error(f"Error stopping VL53L0X: {e}")
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

