import smbus
import time
import signal
import sys

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
LIS3DH_ADDR = 0x6A
WHO_AM_I_REG = 0x0F
WHO_AM_I_EXPECTED = 0x12

LED_PIN = 21
BUZZER_PIN = 20

X_THRESHOLD_LOW = 0.3   # g
X_THRESHOLD_HIGH = 0.7  # g
SAMPLE_INTERVAL = 0.1    # seconds
DISPLAY_INTERVAL = 1.0   # seconds

# --- Globals (for cleanup in signal handler) ---------------------------------
led_pin = None
buzzer_pin = None
i2c_bus = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global running
    running = False


def cleanup():
    """Turn off outputs and close the I2C bus."""
    global led_pin, buzzer_pin, i2c_bus
    if led_pin is not None:
        try:
            import RPi.GPIO as GPIO
            GPIO.output(led_pin, GPIO.LOW)
        except Exception:
            pass
    if buzzer_pin is not None:
        try:
            import RPi.GPIO as GPIO
            GPIO.output(buzzer_pin, GPIO.LOW)
        except Exception:
            pass
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass
    print("Resources released. Exiting.")


def init_gpio():
    """Initialize GPIO pins for LED and buzzer using RPi.GPIO."""
    global led_pin, buzzer_pin
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(led_pin, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(buzzer_pin, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO initialization failed: {e}")
        cleanup()
        sys.exit(1)


def init_i2c():
    """Initialize the I2C bus and verify the LIS3DH device identity."""
    global i2c_bus
    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
    except Exception as e:
        print(f"I2C bus initialization failed: {e}")
        cleanup()
        sys.exit(1)

    try:
        who_am_i = i2c_bus.read_byte_data(LIS3DH_ADDR, WHO_AM_I_REG)
    except Exception as e:
        print(f"Failed to read WHO_AM_I register: {e}")
        cleanup()
        sys.exit(1)

    if who_am_i != WHO_AM_I_EXPECTED:
        print(
            f"WHO_AM_I mismatch: got 0x{who_am_i:02X}, "
            f"expected 0x{WHO_AM_I_EXPECTED:02X}. "
            f"Device not detected."
        )
        cleanup()
        sys.exit(1)


def read_acceleration_x():
    """Read the X-axis acceleration from the LIS3DH and return a signed 16-bit value in g."""
    try:
        data = i2c_bus.read_i2c_block_data(LIS3DH_ADDR, 0x28, 2)
    except Exception as e:
        print(f"I2C read error: {e}")
        return None

    if len(data) < 2:
        print("I2C read returned insufficient data.")
        return None

    raw = (data[0] << 8) | data[1]
    if raw >= 0x8000:
        raw -= 0x10000
    return raw * 0.004  # sensitivity for ±2g range (default)


def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_gpio()
    init_i2c()

    last_display = 0.0
    last_led_state = None
    last_buzzer_state = None

    try:
        while running:
            now = time.monotonic()

            if now - last_display >= DISPLAY_INTERVAL:
                accel_x = read_acceleration_x()
                if accel_x is not None:
                    print(f"X-axis acceleration: {accel_x:.3f} g")
                last_display = now

            if now - last_display < SAMPLE_INTERVAL:
                time.sleep(SAMPLE_INTERVAL)
                continue

            if accel_x is not None:
                abs_x = abs(accel_x)

                if abs_x > X_THRESHOLD_HIGH:
                    if last_buzzer_state is None:
                        try:
                            import RPi.GPIO as GPIO
                            GPIO.output(buzzer_pin, GPIO.HIGH)
                        except Exception as e:
                            print(f"Buzzer on error: {e}")
                        last_buzzer_state = True
                    elif not last_buzzer_state:
                        try:
                            import RPi.GPIO as GPIO
                            GPIO.output(buzzer_pin, GPIO.LOW)
                        except Exception as e:
                            print(f"Buzzer off error: {e}")
                        last_buzzer_state = False

                elif abs_x > X_THRESHOLD_LOW:
                    if last_led_state is None:
                        try:
                            import RPi.GPIO as GPIO
                            GPIO.output(led_pin, GPIO.HIGH)
                        except Exception as e:
                            print(f"LED on error: {e}")
                        last_led_state = True
                    elif not last_led_state:
                        try:
                            import RPi.GPIO as GPIO
                            GPIO.output(led_pin, GPIO.LOW)
                        except Exception as e:
                            print(f"LED off error: {e}")
                        last_led_state = False

                else:
                    if last_led_state is not None:
                        try:
                            import RPi.GPIO as GPIO
                            GPIO.output(led_pin, GPIO.LOW)
                        except Exception as e:
                            print(f"LED off error: {e}")
                        last_led_state = None

            time.sleep(0.001)  # short yield to avoid busy-spin

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

