# Program: Plant Watering System Simulation
# Hardware: Raspberry Pi 3 B+, LED (any color)
# Wiring: LED anode -> 330 ohm resistor -> BCM pin 17 (physical pin 11)
#         LED cathode -> GND (physical pin 9 or similar)

import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: sudo apt install python3-rpi.gpio")
    sys.exit(1)

LED_PIN = 17
MOISTURE_LEVEL = 60
DRY_THRESHOLD = 30
READING_INTERVAL = 2  # seconds

_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def setup_gpio():
    """Initialize GPIO and set up the LED pin as an output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)

def cleanup_gpio():
    """Safely turn off the LED and release GPIO resources."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception:
        pass

def simulate_moisture_level():
    """Simulate a decreasing moisture level. Returns the new level or None on error."""
    global MOISTURE_LEVEL
    try:
        MOISTURE_LEVEL -= 3
        if MOISTURE_LEVEL < 0:
            MOISTURE_LEVEL = 0
        return MOISTURE_LEVEL
    except Exception as e:
        print(f"Error simulating moisture level: {e}")
        return None

def control_led(moisture_level):
    """Control the LED based on the moisture level."""
    try:
        if moisture_level < DRY_THRESHOLD:
            GPIO.output(LED_PIN, GPIO.HIGH)
            print("LED ON: Soil is too dry!")
        else:
            GPIO.output(LED_PIN, GPIO.LOW)
            print("LED OFF: Soil is moist enough")
    except Exception as e:
        print(f"Error controlling LED: {e}")

def main():
    """Main loop for the plant watering system simulation."""
    global _running

    setup_gpio()

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        while _running:
            moisture = simulate_moisture_level()
            if moisture is not None:
                print(f"Moisture Level: {moisture}")
                control_led(moisture)
            time.sleep(READING_INTERVAL)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()
        print("GPIO cleanup completed. Program exiting.")

if __name__ == "__main__":
    main()

