import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: sudo apt install python3-rpi.gpio")
    sys.exit(1)

LED_PIN = 17
CYCLES = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def simulate_light_level():
    return random.randint(0, 100)

def control_led(light_level):
    if light_level < 50:
        GPIO.output(LED_PIN, GPIO.HIGH)
        print("LED ON: Light level too low")
    else:
        GPIO.output(LED_PIN, GPIO.LOW)
        print("LED OFF: Sufficient ambient light")

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)

    try:
        for cycle in range(1, CYCLES + 1):
            if not _running:
                print("\nInterrupted by user. Exiting gracefully...")
                break

            light_level = simulate_light_level()
            print(f"Cycle {cycle}/{CYCLES}: Light Level: {light_level}%")
            control_led(light_level)

            if cycle < CYCLES and _running:
                time.sleep(DELAY_SECONDS)

        if _running:
            print("LED control sequence completed.")

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        try:
            GPIO.output(LED_PIN, GPIO.LOW)
        except Exception:
            pass
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

