import RPi.GPIO as GPIO
import time
import datetime
import sys

PIR_PIN = 4
FEED_INTERVAL = 60  # seconds between feeds

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

def is_feeding_time(now):
    """Return True if now is between 07:00–08:00 or 18:00–19:00 (24-hour format)."""
    return (7 <= now.hour < 8) or (18 <= now.hour < 20)

def feeder_initiate(now):
    print(f"Feeding initiated at {now.strftime('%Y-%m-%d %H:%M:%S')}")

def main():
    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

    last_feed_time = 0.0
    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"Error reading GPIO: {e}")
                time.sleep(1)
                continue

            if motion_detected:
                now = datetime.datetime.now()
                if is_feeding_time(now) and (now - last_feed_time).total_seconds() >= FEED_INTERVAL:
                    feeder_initiate(now)
                    last_feed_time = now
                else:
                    print(f"Motion detected at {now.strftime('%Y-%m-%d %H:%M:%S')} "
                          f"but not feeding time or recently fed.")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program…")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

