#!/usr/bin/python3
"""
Raspberry Pi DC Motor HAT driver using Adafruit CircuitPython libraries.

Provides a DCMotor class for single-motor control with configurable speed,
direction, and PWM frequency.  Includes robust error handling, signal-based
cleanup, and atexit-based motor release.
"""

import atexit
import logging
import signal
import sys
import time

import board
import busio
from adafruit_motorkit import MotorKit

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
DEFAULT_PWM_FREQUENCY = 60  # Hz – typical for hobby servos / DC motors
MIN_DUTY_CYCLE = -255
MAX_DUTY_CYCLE = 255

# ---------------------------------------------------------------------------
# DCMotorHATExtra
# ---------------------------------------------------------------------------
class DCMotorHATExtra:
    """Thin wrapper around Adafruit MotorKit that exposes the underlying
    PCA9685 instance for direct register-level access (if needed)."""

    def __init__(self, i2c, address=0x7F):
        self.i2c = i2c
        self.address = address
        self._pwm_devices = {}
        self._initialize_motors()

    def _initialize_motors(self):
        """Initialise all four motors; log and continue if one fails."""
        for motor_num in range(1, 5):
            try:
                self.get_pwm_freq(motor_num)
            except Exception as exc:
                logger.warning(
                    "Failed to initialise motor %d: %s", motor_num, exc
                )
            else:
                self._pwm_devices[motor_num] = self.i2c.get_pwm_device(motor_num)

    def get_pwm_device(self, motor_num):
        """Return the PCA9685 PWM device for *motor_num*."""
        if not 1 <= motor_num <= 4:
            raise ValueError(f"Invalid motor number: {motor_num}")
        return self._pwm_devices.get(motor_num)

    def get_pwm_freq(self, motor_num):
        """Return the current PWM frequency for *motor_num* (Hz)."""
        device = self.get_pwm_device(motor_num)
        if device is None:
            raise RuntimeError(f"Motor {motor_num} not initialised")
        return device.frequency

    def set_pwm_freq(self, motor_num, freq_hz):
        """Set the PWM frequency for *motor_num* (Hz)."""
        device = self.get_pwm_device(motor_num)
        if device is None:
            raise RuntimeError(f"Motor {motor_num} not initialised")
        device.frequency = freq_hz

    def set_dc(self, motor_num, duty_cycle):
        """Set the duty cycle for *motor_num* (0-255).  Positive = forward,
        negative = backward, 0 = stop."""
        device = self.get_pwm_device(motor_num)
        if device is None:
            raise RuntimeError(f"Motor {motor_num} not initialised")
        device.duty_cycle = duty_cycle

    def close(self):
        """Release all motors (stop them)."""
        for motor_num in range(1, 5):
            try:
                self.set_dc(motor_num, 0)
            except Exception as exc:
                logger.warning("Error stopping motor %d: %s", motor_num, exc)


# ---------------------------------------------------------------------------
# DCMotor
# ---------------------------------------------------------------------------
class DCMotor:
    """Single-motor driver using a DCMotorHATExtra instance."""

    def __init__(self, hat, motor_num, frequency=DEFAULT_PWM_FREQUENCY, invert=False):
        if not 1 <= motor_num <= 4:
            raise ValueError(f"Invalid motor number: {motor_num}")
        self.hat = hat
        self.motor_num = motor_num
        self.frequency = frequency
        self.invert = invert
        self.last_duty_cycle = 0
        self._closed = False

        try:
            self.hat.set_pwm_freq(self.motor_num, self.frequency)
        except Exception as exc:
            logger.error("Failed to set PWM frequency for motor %d: %s", self.motor_num, exc)
            raise

        # Ensure motor starts in a stopped state
        self.stop()

    def set_dc(self, duty_cycle):
        """Set the duty cycle.  Clamps to [-255, 255]."""
        if self._closed:
            return

        clamped = max(MIN_DUTY_CYCLE, min(duty_cycle, MAX_DUTY_CYCLE))
        if clamped == self.last_duty_cycle:
            return

        direction = 1 if (clamped > 0) == (self.invert ^ (clamped > 0)) else -1
        self.last_duty_cycle = clamped
        try:
            self.hat.set_dc(self.motor_num, clamped * direction)
        except Exception as exc:
            logger.error(
                "Failed to set duty cycle for motor %d: %s", self.motor_num, exc
            )
            raise

    def get_status(self):
        """Return (motor_num, frequency, invert, last_duty_cycle)."""
        return (
            self.motor_num,
            self.frequency,
            self.invert,
            self.last_duty_cycle,
        )

    def stop(self):
        """Stop the motor (duty cycle 0)."""
        if self._closed:
            return
        try:
            self.hat.set_dc(self.motor_num, 0)
        except Exception as exc:
            logger.warning("Failed to stop motor %d: %s", self.motor_num, exc)
        finally:
            self.last_duty_cycle = 0

    def close(self):
        """Release this motor (stop it)."""
        if self._closed:
            return
        self.stop()
        self._closed = True


# ---------------------------------------------------------------------------
# MotorKit wrapper
# ---------------------------------------------------------------------------
class MotorKitWrapper:
    """Wraps the Adafruit MotorKit with a DCMotorHATExtra and per-motor
instances."""

    def __init__(self, i2c_bus=1, address=0x7F):
        self.i2c = None
        self.hat = None
        self._motors = {}

        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            self.hat = MotorKit(i2c=self.i2c, address=address)
            self._motors = {
                m.motor_num: DCMotor(self.hat, m.motor_num)
                for m in self.hat.motors
            }
        except Exception as exc:
            logger.error("Failed to initialise MotorKit on I2C bus %d: %s", i2c_bus, exc)
            self.close()
            raise

    def get_motor(self, motor_num):
        """Return the DCMotor instance for *motor_num*."""
        if not 1 <= motor_num <= 4:
            raise ValueError(f"Invalid motor number: {motor_num}")
        return self._motors.get(motor_num)

    def close(self):
        """Release all motors and close the I2C bus."""
        for motor_num in range(1, 5):
            try:
                self.get_motor(motor_num).close()
            except Exception as exc:
                logger.warning("Error closing motor %d: %s", motor_num, exc)
        if self.i2c is not None:
            try:
                self.i2c.deinit()
            except Exception:
                pass
            self.i2c = None


# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
_motor_kit = None


def _signal_handler(signum, frame):
    logger.info("Signal %d received – shutting down.", signum)
    if _motor_kit is not None:
        _motor_kit.close()
    sys.exit(0)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    global _motor_kit

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _motor_kit = MotorKitWrapper(i2c_bus=1, address=0x7F)
        motor1 = _motor_kit.get_motor(1)

        logger.info("Ramping motor 1 forward...")
        for dc in range(0, 256, 5):
            motor1.set_dc(dc)
            time.sleep(0.02)

        logger.info("Ramping motor 1 backward...")
        for dc in range(0, -256, -5):
            motor1.set_dc(dc)
            time.sleep(0.02)

        logger.info("Stopping motor 1.")
        motor1.stop()

    except Exception as exc:
        logger.error("Runtime error: %s", exc)
    finally:
        if _motor_kit is not None:
            _motor_kit.close()


if __name__ == "__main__":
    atexit.register(MotorKitWrapper.close)
    main()

