import signal
import sys
import time
import logging

from gpiozero import Device, OutputDevice
from gpiozero.pins.native import NativeFactory

try:
    from angular_servo_driver import AngularServo
except ImportError:
    AngularServo = None

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("robotic_arm")

BASE_PIN = 17
SHOULDER_PIN = 27
GRIPPER_PIN = 22
PWM_FREQ = 50
MIN_PULSE = 0.5 / 1000
MAX_PULSE = 2.5 / 1000
SETTLE_DELAY = 0.4

_running = True


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


class RoboticArm:
    def __init__(self, base_pin, shoulder_pin, gripper_pin, frequency=PWM_FREQ):
        if AngularServo is None:
            raise RuntimeError("angular_servo_driver not installed")
        self.base = AngularServo(
            base_pin, min_pulse_width=MIN_PULSE, max_pulse_width=MAX_PULSE,
            frame_rate=frequency, initial_angle=None
        )
        self.shoulder = AngularServo(
            shoulder_pin, min_pulse_width=MIN_PULSE, max_pulse_width=MAX_PULSE,
            frame_rate=frequency, initial_angle=None
        )
        self.gripper = AngularServo(
            gripper_pin, min_pulse_width=MIN_PULSE, max_pulse_width=MAX_PULSE,
            frame_rate=frequency, initial_angle=None
        )
        self.joints = [self.base, self.shoulder, self.gripper]
        self._released = False

    def move_joint(self, joint_index, target_angle):
        if not 0 <= joint_index < len(self.joints):
            raise ValueError(f"joint_index {joint_index} out of range [0, {len(self.joints) - 1}]")
        if self._released:
            raise RuntimeError("Arm has been released – cannot move joints")
        try:
            self.joints[joint_index].angle = target_angle
        except Exception as exc:
            raise RuntimeError(f"Failed to move joint {joint_index}: {exc}") from exc
        time.sleep(SETTLE_DELAY)

    def go_to_pose(self, base_angle, shoulder_angle, gripper_angle):
        if not all(0 <= a <= 90 for a in (base_angle, shoulder_angle, gripper_angle)):
            raise ValueError("All angles must be in [-90, 90].")
        log.info("Moving to pose (%.1f, %.1f, %.1f)", base_angle, shoulder_angle, gripper_angle)
        self.move_joint(0, base_angle)
        self.move_joint(1, shoulder_angle)
        self.move_joint(2, gripper_angle)

    def release(self):
        if self._released:
            return
        self._released = True
        for j in self.joints:
            try:
                j.angle = None
            except Exception:
                pass
        log.info("Arm released – all joints detached.")

    def close(self):
        for j in self.joints:
            try:
                j.close()
            except Exception:
                pass
        self.release()


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    arm = None
    try:
        arm = RoboticArm(BASE_PIN, SHOULDER_PIN, GRIPPER_PIN)
        poses = [(0, 0, 0), (45, -30, 20), (-45, 30, -20)]
        for pose in poses:
            if not _running:
                break
            arm.go_to_pose(*pose)
        if _running:
            arm.go_to_pose(0, 0, 0)
    except ValueError as exc:
        log.error("Invalid parameter: %s", exc)
    except RuntimeError as exc:
        log.error("Runtime error: %s", exc)
    except Exception as exc:
        log.error("Unexpected error: %s", exc)
    finally:
        if arm is not None:
            arm.close()


if __name__ == "__main__":
    main()

