#!/usr/bin/env python3
"""
Soil Moisture Monitoring and Irrigation Control for Raspberry Pi Zero W.

Monitors soil moisture via an Adafruit Seesaw sensor (I2C address 0x70) and
controls a 12V water pump relay on GPIO17 (BCM).

Hardware:
  - Raspberry Pi Zero W
  - Adafruit Seesaw Soil Moisture Sensor (I2C address 0x70)
  - 12V DC Water Pump + 100kΩ pull-down resistor on relay IN

Wiring:
  - Sensor SDA -> GPIO2 (I2C bus 1)
  - Sensor SCL -> GPIO3 (I2C bus 1)
  - Sensor VCC -> 3.3V
  - Sensor GND -> GND
  - Relay IN   -> GPIO17 (BCM)
  - Relay VCC -> 5V (or 3.3V if logic-level compatible)
  - Relay GND -> GND
"""

import signal
import sys
import time

import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# --- Configuration -----------------------------------------------------------
PUMP_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10
SENSOR_I2C_ADDRESS = 0x70

# --- Globals for cleanup -----------------------------------------------------
_running = True
_i2c_bus = None
_sensor = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def initialize_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus: {exc}", file=sys.stderr)
        return None


def initialize_sensor(i2c_bus):
    """Initialize the Seesaw soil moisture sensor; return sensor or None."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=SENSOR_I2C_ADDRESS)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize Seesaw sensor at 0x{SENSOR_I2C_ADDRESS:02X}: {exc}",
              file=sys.stderr)
        return None


def initialize_gpio(pin):
    """Configure the GPIO pin for the pump relay; return True on success."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as exc:
        print(f"[ERROR] Failed to initialize GPIO{pin}: {exc}", file=sys.stderr)
        return False


def read_soil_moisture(sensor):
    """Read soil moisture from the sensor; return int or None on error."""
    try:
        return sensor.moisture_read()
    except Exception as exc:
        print(f"[WARN] Sensor read error: {exc}", file=sys.stderr)
        return None


def control_pump(pin, moisture_level, threshold):
    """Control the pump based on moisture level; print status."""
    try:
        if moisture_level is None:
            print("[WARN] Moisture reading unavailable; pump remains off.")
            return

        if moisture_level < threshold:
            GPIO.output(pin, GPIO.HIGH)
            print(f"Moisture: {moisture_level}  |  Pump: ON")
        else:
            GPIO.output(pin, GPIO.LOW)
            print(f"Moisture: {moisture_level}  |  Pump: OFF")
    except Exception as exc:
        print(f"[ERROR] Failed to control pump: {exc}", file=sys.stderr)


def cleanup():
    """Release all hardware resources and ensure the pump is off."""
    global _sensor, _i2c_bus

    if _sensor is not None:
        try:
            _sensor.deinit()
        except Exception:
            pass
        _sensor = None

    if _i2c_bus is not None:
        try:
            _i2c_bus.deinit()
        except Exception:
            pass
        _i2c_bus = None

    try:
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
    except Exception:
        pass

    try:
        GPIO.cleanup()
    except Exception:
        pass


def main():
    """Main loop: monitor moisture and control the pump every 10 s."""
    global _running, _i2c_bus, _sensor

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _i2c_bus = initialize_i2c()
    if _i2c_bus is None:
        cleanup()
        sys.exit(1)

    _sensor = initialize_sensor(_i2c_bus)
    if _sensor is None:
        cleanup()
        sys.exit(1)

    if not initialize_gpio(PUMP_GPIO_PIN):
        cleanup()
        sys.exit(1)

    print("Soil moisture monitoring started. Press Ctrl+C to exit.")

    try:
        while _running:
            moisture = read_soil_moisture(_sensor)
            control_pump(PUMP_GPIO_PIN, moisture, MOISTURE_THRESHOLD)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as exc:
        print(f"[ERROR] Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        cleanup()
        print("Program terminated. Pump ensured OFF. GPIO cleaned up.")


if __name__ == "__main__":
    main()

