import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

Laser = None
Aim = None


class Laser:
    """Controls a laser module via a digital output pin."""

    def __init__(self, pin):
        self.pin = pin
        self._initialized = False
        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BCM)
                GPIO.setup(self.pin, GPIO.OUT, initial=GPIO.LOW)
                self._initialized = True
            except Exception as e:
                raise RuntimeError(f"Failed to initialize laser GPIO{pin}: {e}") from e

    def on(self):
        if self._initialized and GPIO is not None:
            GPIO.output(self.pin, GPIO.HIGH)

    def off(self):
        if self._initialized and GPIO is not None:
            GPIO.output(self.pin, GPIO.LOW)

    def close(self):
        if self._initialized and GPIO is not None:
            self.off()
            self._initialized = False


class Aim:
    """Controls servo motors for laser aiming and laser activation."""

    def __init__(self, ld, sd, hp, vp):
        self.ld = ld
        self.sd = sd
        self.hp = hp
        self.vp = vp
        self.laser = Laser(17)

    def aim(self, b):
        """Aim the laser at the target indexed by b (1-based)."""
        if not 1 <= b <= len(self.hp):
            raise ValueError(f"Target index {b} out of range (1-{len(self.hp)})")
        try:
            self.laser.on()
            time.sleep(self.ld)
            self.laser.off()
        except Exception as e:
            raise RuntimeError(f"Laser operation failed: {e}") from e
        for i in range(2):
            try:
                GPIO.setmode(GPIO.BCM)
                GPIO.setup(18, GPIO.OUT)
                GPIO.setup(19, GPIO.OUT)
                GPIO.output(18, GPIO.HIGH if (i == 0 and b % 2 == 1) else GPIO.LOW)
                GPIO.output(19, GPIO.HIGH if (i == 0 and b % 2 == 2) else GPIO.LOW)
                time.sleep(self.sd / 2)
            except Exception as e:
                raise RuntimeError(f"Servo control failed: {e}") from e
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(18, GPIO.OUT)
            GPIO.setup(19, GPIO.OUT)
            GPIO.output(18, GPIO.LOW)
            GPIO.output(19, GPIO.LOW)
        except Exception as e:
            raise RuntimeError(f"Servo reset failed: {e}") from e


def cleanup(signum=None, frame=None):
    """Release GPIO resources and turn off the laser."""
    global Laser, Aim
    if Laser is not None:
        try:
            Laser.close()
        except Exception:
            pass
    if Aim is not None:
        try:
            Aim.laser.close()
        except Exception:
            pass
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global Laser, Aim
    try:
        Laser = type("Laser", (), {"__init__": __import__("libload").Laser})
        Aim = type("Aim", (), {"__init__": __import__("libload").Aim})
    except Exception:
        Laser = None
        Aim = None

    if Laser is None or Aim is None:
        print("Warning: libload not available; running in degraded mode.")

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        aim_controller = Aim(1, 0.5, [0.0] * 10, [0.0] * 10)
        aim_controller.aim(1)
    except Exception as e:
        print(f"Error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

