import time
import signal
import sys
import logging

try:
    import board
    import busio
    from adafruit_pca9685 import PCA9685
except ImportError:
    print("Missing required libraries. Install with:")
    print("  pip install adafruit-circuitpython-pca9685 adafruit-circuitpython-busdevice")
    print("  sudo apt-get install i2c-tools")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

BASE_CHANNEL = 0
DROP_CHANNEL = 1
SEEK_CHANNEL = 2
GRAB_CHANNEL = 4

PCA9685_ADDR = 0x60

DEFAULT_MOVE_STEP = 5
DEFAULT_MOVE_DELAY = 0.04
DEFAULT_DROP_STEP = 2
DEFAULT_DROP_DELAY = 0.01

_pca = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    logger.info("Signal received, shutting down...")


def _validate_channel(channel):
    if not isinstance(channel, int) or not (0 <= channel <= 15):
        raise ValueError(f"Invalid channel {channel}; must be 0-15.")


def _validate_angle(angle):
    if not isinstance(angle, (int, float)) or not (0 <= angle <= 180):
        raise ValueError(f"Invalid angle {angle}; must be 0-180.")


def _validate_step(step):
    if not isinstance(step, int) or step <= 0:
        raise ValueError(f"Invalid step size {step}; must be a positive integer.")


def _validate_delay(delay):
    if not isinstance(delay, (int, float)) or delay < 0:
        raise ValueError(f"Invalid delay {delay}; must be >= 0.")


def _validate_drop_angle(drop_angle):
    if not isinstance(drop_angle, (int, float)) or not (0 <= drop_angle <= 180):
        raise ValueError(f"Invalid drop angle {drop_angle}; must be 0-180.")


def library_api_call(channels=16, i2c_bus=None, address=PCA9685_ADDR):
    """
    Controls the PCA9685 servo motor via a functional API.

    Args:
        channels (int): Number of servo channels (default: 16).
        i2c_bus: An I2C bus object (default: None, auto-detected).
        address (int): I2C address of the PCA9685 (default: 0x60).
    """
    global _pca
    if i2c_bus is None:
        i2c_bus = busio.I2C(board.SCL, board.SDA)

    try:
        _pca = PCA9685(i2c_bus, address=address)
    except Exception as e:
        logger.error(f"Failed to initialize PCA9685 at 0x{address:02X}: {e}")
        raise

    try:
        _pca.channels.duty_cycle.max_value = 65535
        _pca.channels.duty_cycle.resolution = 16384
    except Exception as e:
        logger.warning(f"Could not set PCA9685 resolution: {e}")

    def _set_pwm(channel, on, off):
        _validate_channel(channel)
        _validate_step(on)
        _validate_step(off)
        try:
            _pca.channels[channel].duty_cycle = int((on * 65535) + (off * 32767))
        except Exception as e:
            logger.error(f"I2C write error on channel {channel}: {e}")
            raise

    def _move_servo(channel, angle, step=DEFAULT_MOVE_STEP, delay=DEFAULT_MOVE_DELAY):
        _validate_channel(channel)
        _validate_angle(angle)
        _validate_step(step)
        _validate_delay(delay)
        try:
            current = _pca.channels[channel].duty_cycle >> 16
            target = int((angle * 65535) / 180)
            step_size = step if target - current >= step else step
            if target - current > 0:
                for i in range(0, target, step_size):
                    _set_pwm(channel, i, i)
                    time.sleep(delay)
            else:
                for i in range(target, 0, -step_size):
                    _set_pwm(channel, i, i)
                    time.sleep(delay)
            _set_pwm(channel, target, 0)
        except Exception as e:
            logger.error(f"Error moving servo on channel {channel} to angle {angle}: {e}")
            raise

    def _set_servo(channel, angle):
        _move_servo(channel, angle, step=DEFAULT_MOVE_STEP, delay=DEFAULT_MOVE_DELAY)

    def _move_with_delay(channel, angle, step=DEFAULT_DROP_STEP, delay=DEFAULT_DROP_DELAY):
        _validate_channel(channel)
        _validate_angle(angle)
        _validate_step(step)
        _validate_delay(delay)
        try:
            current = _pca.channels[channel].duty_cycle >> 16
            target = int((angle * 65535) / 180)
            if target - current > 0:
                for i in range(current, target, step):
                    _set_pwm(channel, i, i)
                    time.sleep(delay)
            else:
                for i in range(target, current, -step):
                    _set_pwm(channel, i, i)
                    time.sleep(delay)
            _set_pwm(channel, target, 0)
        except Exception as e:
            logger.error(f"Error moving servo on channel {channel} to angle {angle}: {e}")
            raise

    def _drop_object(channel, angle, step=DEFAULT_DROP_STEP, delay=DEFAULT_DROP_DELAY):
        _validate_channel(channel)
        _validate_drop_angle(angle)
        _validate_step(step)
        _validate_delay(delay)
        try:
            current = _pca.channels[channel].duty_cycle >> 16
            target = int((angle * 65535) / 180)
            if target - current > 0:
                for i in range(current, target, step):
                    _set_pwm(channel, i, i)
                    time.sleep(delay)
            else:
                for i in range(target, current, -step):
                    _set_pwm(channel, i, i)
                    time.sleep(delay)
            _set_pwm(channel, target, 0)
        except Exception as e:
            logger.error(f"Error dropping object on channel {channel} to angle {angle}: {e}")
            raise

    def _release_object(channel, angle, step=DEFAULT_DROP_STEP, delay=DEFAULT_DROP_DELAY):
        _validate_channel(channel)
        _validate_drop_angle(angle)
        _validate_step(step)
        _validate_delay(delay)
        try:
            current = _pca.channels[channel].duty_cycle >> 16
            target = int((angle * 65535) / 180)
            if target - current > 0:
                for i in range(current, target, step):
                    _set_pwm(channel, i, i)
                    time.sleep(delay)
            else:
                for i in range(target, current, -step):
                    _set_pwm(channel, i, i)
                    time.sleep(delay)
            _set_pwm(channel, target, 0)
        except Exception as e:
            logger.error(f"Error releasing object on channel {channel} to angle {angle}: {e}")
            raise

    def _seek(angle):
        _move_servo(SEEK_CHANNEL, angle, step=DEFAULT_MOVE_STEP, delay=DEFAULT_MOVE_DELAY)

    def _deseek(angle):
        _move_servo(SEEK_CHANNEL, angle, step=DEFAULT_MOVE_STEP, delay=DEFAULT_MOVE_DELAY)

    def _drop(angle):
        _move_servo(DROP_CHANNEL, angle, step=DEFAULT_DROP_STEP, delay=DEFAULT_DROP_DELAY)

    def _pick(angle):
        _move_servo(DROP_CHANNEL, angle, step=DEFAULT_MOVE_STEP, delay=DEFAULT_MOVE_DELAY)

    def _grab(angle):
        _move_servo(GRAB_CHANNEL, angle, step=DEFAULT_MOVE_STEP, delay=DEFAULT_MOVE_DELAY)

    def _release(angle):
        _move_servo(GRAB_CHANNEL, angle, step=DEFAULT_MOVE_STEP, delay=DEFAULT_MOVE_DELAY)

    def _collect_object(seek_angle):
        _seek(seek_angle)
        _grab(90)
        _drop(160)
        _pick(100)
        _deseek(90)

    def _drop_object(drop_angle):
        _drop_object(DROP_CHANNEL, drop_angle, step=DEFAULT_DROP_STEP, delay=DEFAULT_DROP_DELAY)
        _release_object(GRAB_CHANNEL, 120, step=DEFAULT_DROP_STEP, delay=DEFAULT_DROP_DELAY)
        _pick(100)

    def _get_pos_x(x_center):
        return int((x_center / 320) * 180)

    def _get_pos_y(y_center):
        return int((y_center / 320) * 180)

    def _cleanup():
        logger.info("Cleaning up PCA9685...")
        try:
            if _pca is not None:
                for ch in range(channels):
