        api['collect_object'](pos_y)
        api['drop_object'](drop_angle)
        api['pick'](100)
        api['deseek'](90)
        api['cleanup']()
    except Exception as e:
        logger.error(f"Error during object collection: {e}")
        if api is not None:
            api['cleanup']()


def main():
    signal.signal(signal.SIGINT, _signal_handler)
