import time

import board
import busio
from adafruit_seesaw.seesaw import Seesaw
from adafruit_seesaw.exception import SeesawError

PUMP_GPIO_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

_running = True
_pump_off = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def initialize_i2c():
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        return None


def initialize_soil_sensor(i2c_bus):
    try:
        return Seesaw(i2c_bus)
    except SeesawError as exc:
        print(f"Seesaw initialization error (check wiring/address 0x70): {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"Unexpected error initializing soil sensor: {exc}", file=sys.stderr)
        return None


def read_soil_moisture(sensor):
    try:
        return sensor.moisture_read()
    except Exception as exc:
        print(f"Error reading soil moisture: {exc}", file=sys.stderr)
        return None


def control_water_pump(pump_pin, moisture_level, dry_threshold):
    global _pump_off
    if moisture_level is None:
        return "UNKNOWN"
    if moisture_level < dry_threshold:
        if not _pump_off:
            try:
                pump_pin.value = 1
            except Exception as exc:
                print(f"Error turning pump ON: {exc}", file=sys.stderr)
            _pump_off = False
            return "ON"
    else:
        if _pump_off:
            try:
                pump_pin.value = 0
            except Exception as exc:
                print(f"Error turning pump OFF: {exc}", file=sys.stderr)
            _pump_off = True
        return "OFF"


def main():
    global _pump_off

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    sensor = initialize_soil_sensor(i2c_bus)
    if sensor is None:
        sys.exit(1)

    try:
        pump_pin = busio.DigitalInOut(PUMP_GPIO_PIN)
        pump_pin.value = 0
        _pump_off = True
    except Exception as exc:
        print(f"Error initializing pump GPIO {PUMP_GPIO_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            moisture = read_soil_moisture(sensor)
            pump_status = control_water_pump(pump_pin, moisture, DRY_SOIL_THRESHOLD)
            if moisture is not None:
                print(f"Soil Moisture: {moisture}, Pump: {pump_status}")
            else:
                print(f"Soil Moisture: ERROR, Pump: {pump_status}")
            for _ in range(READ_INTERVAL_SECONDS):
                if not _running:
                    break
                time.sleep(1)
    finally:
        try:
            pump_pin.value = 0
            _pump_off = True
        except Exception:
            pass
        try:
            pump_pin.deinit()
        except Exception:
            pass
        try:
            sensor.deinit()
        except Exception:
            pass
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

