import time
import signal
import logging
import smbus2
from ina219 import INA219, DeviceRangeError

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

I2C_BUS = 1
INA219_ADDRESS = 0x40
SUPPLY_VOLTAGE = 5.0
SHUNT_RESISTOR_BATTERY = 0.005
SHUNT_RESISTOR_SUPPLY = 0.00725
CALIBRATION = 4096
READ_INTERVAL = 5

running = True

def signal_handler(signum, frame):
    global running
    running = False

def initialize_ina219(bus, address, shunt, supply_voltage, calibration):
    try:
        ina = INA219(shunt, supply_voltage, busnum=I2C_BUS, address=address)
        ina.configure()
        ina.calibration = calibration
        ina.wake_up()
        logging.info(f"INA219 at 0x{address:02X} initialized (shunt={shunt}, supply={supply_voltage}V, calibration={calibration})")
        return ina
    except Exception as e:
        logging.warning(f"Failed to initialize INA219 at 0x{address:02X}: {e}")
        return None

def read_ina219_data(ina):
    try:
        current = ina.current()
        power = ina.power()
        return current, power
    except DeviceRangeError:
        logging.warning("Device Range Error reading INA219 data.")
        return None, None
    except Exception as e:
        logging.warning(f"Error reading INA219 data: {e}")
        return None, None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
        ina_supply = initialize_ina219(bus, INA219_ADDRESS, SHUNT_RESISTOR_SUPPLY, SUPPLY_VOLTAGE, CALIBRATION)
        ina_battery = initialize_ina219(bus, INA219_ADDRESS, SHUNT_RESISTOR_BATTERY, SUPPLY_VOLTAGE, CALIBRATION)

        if ina_supply is None or ina_battery is None:
            logging.error("One or more INA219 sensors failed to initialize. Exiting.")
            return

        while running:
            supply_current, supply_power = read_ina219_data(ina_supply)
            battery_current, battery_power = read_ina219_data(ina_battery)

            if supply_current is not None and supply_power is not None:
                logging.info(f"Supply: Current={supply_current:.3f} mA, Power={supply_power:.3f} mW")
            else:
                logging.warning("Supply data unavailable.")

            if battery_current is not None and battery_power is not None:
                logging.info(f"Battery: Current={battery_current:.3f} mA, Power={battery_power:.3f} mW")
            else:
                logging.warning("Battery data unavailable.")

            for _ in range(READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
                logging.info("I2C bus closed.")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

