import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_TIMEOUT = 1.0
LOOP_DELAY = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(ALARM_PIN, GPIO.OUT, initial=GPIO.LOW)

def read_radiation_level(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print("Error: Non-numeric data received from sensor.")
        return None
    except UnicodeDecodeError:
        print("Error: Non-ASCII data received from sensor.")
        return None
    except serial.SerialException as e:
        print(f"Serial I/O error during read: {e}")
        return None

def check_radiation_level(radiation_level, alarm_active):
    if radiation_level is None:
        return alarm_active
    if radiation_level > RADIATION_THRESHOLD:
        GPIO.output(ALARM_PIN, GPIO.HIGH)
        if not alarm_active:
            print("Radiation level exceeded threshold! Alarm triggered.")
        return True
    else:
        GPIO.output(ALARM_PIN, GPIO.LOW)
        if alarm_active:
            print("Radiation level returned to normal.")
        return False

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)

    initialize_gpio()

    alarm_active = False
    try:
        while _running:
            radiation = read_radiation_level(serial_connection)
            if radiation is not None:
                alarm_active = check_radiation_level(radiation, alarm_active)
            time.sleep(LOOP_DELAY)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if serial_connection.is_open:
            serial_connection.close()
        GPIO.cleanup()
        print("Program terminated.")

if __name__ == "__main__":
    main()

