import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_flow_rate(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    data = raw.decode('ascii', errors='replace').strip()
    if not data:
        return None
    try:
        return float(data)
    except ValueError:
        print(f"Invalid data received (not a float): {data!r}", file=sys.stderr)
        return None

def log_flow_rate(flow_rate, log_file):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    line = f"{timestamp} - Flow Rate: {flow_rate:.2f} L/min\n"
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(line)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while _running:
            flow_rate = read_flow_rate(ser)
            if flow_rate is not None:
                print(f"Flow Rate: {flow_rate:.2f} L/min")
                log_flow_rate(flow_rate, LOG_FILE)
            time.sleep(1)

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

