import serial
import serial.tools.list_ports
import time
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'


def log_access_event(tag_id: str) -> None:
    """Append a timestamped access event to the log file and print to console."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(log_entry)
            logfile.flush()
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)
    print(f'Access granted for RFID Tag: {tag_id}')


def main() -> None:
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'Opened {SERIAL_PORT} @ {BAUD_RATE} baud. Waiting for RFID tags...')

        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f'Serial read error: {e}', file=sys.stderr)
                break

            if not raw:
                continue

            try:
                tag_id = raw.decode('ascii', errors='replace').strip()
            except Exception as e:
                print(f'Decode error: {e}', file=sys.stderr)
                continue

            if tag_id:
                log_access_event(tag_id)

    except serial.SerialException as e:
        print(f'Error opening serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print('\nExiting program...')
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print('Serial port closed.')


if __name__ == '__main__':
    main()

