    global _running
    _running = False

def log_power_consumption(ser):
    global _running
    while _running:
        try:
            raw = ser.readline()
        except serial.SerialException as e:
            print(f"Serial read error: {e}", file=sys.stderr)
            break
        if not raw:
            continue
        line = raw.decode("ascii", errors="replace").strip()
        if not line:
            continue
        try:
            power_usage = float(line)
        except ValueError:
            print(f"Invalid data received: {line!r}", file=sys.stderr)
            continue
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        log_entry = f"{timestamp} - Power: {power_usage} W\n"
        try:
            with open(LOG_FILE, "a") as logfile:
                logfile.write(log_entry)
        except OSError as e:
            print(f"Failed to write to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            log_power_consumption(ser)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"OS error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

