# ---------------------------------------------------------------------------
# Serial-instrument helper
# ---------------------------------------------------------------------------
class SerialInstrument:
    """Thin SCPI-over-UART wrapper with robust error handling."""

    def __init__(self, port: str, baudrate: int, timeout: float):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None
        self._open()

    def _open(self):
        try:
            self.ser = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
        except serial.SerialException as exc:
            raise RuntimeError(f"Cannot open serial port {self.port}: {exc}") from exc

    def send_and_receive(self, command: str) -> str:
        """Send a command, wait 0.1 s, and return the decoded response."""
        if self.ser is None or not self.ser.is_open:
            raise RuntimeError("Serial port is not open")
        try:
            self.ser.reset_input_buffer()
            self.ser.write(command.encode('ascii'))
            self.ser.flush()
            time.sleep(0.1)
            raw = self.ser.read(4096)
            if not raw:
                return ""
            return raw.decode('ascii', errors='replace').strip()
        except serial.SerialException as exc:
            raise RuntimeError(f"Serial communication error: {exc}") from exc

    def close(self):
        if self.ser is not None and self.ser.is_open:
            try:
                self.ser.close()
            except Exception:
                pass


# ---------------------------------------------------------------------------
# In-memory data store
# ---------------------------------------------------------------------------
class DataStore:
    def __init__(self, items: list):
        self.items = items

    def get_all(self):
        return self.items

    def get_item(self, item_id: int):
        return next((item for item in self.items if item['id'] == item_id), None)

    def update_item(self, item_id: int, name: str, done: bool):
        for i, data in enumerate(self.items):
            if data['id'] == item_id:
                self.items[i]['name'] = name
                self.items[i]['done'] = done
                return
        raise ValueError(f"Item with id {item_id} not found")

    def add_item(self, name: str, done: bool = False):
        new_id = (self.items[-1]['id'] + 1) if self.items else 1
        new_item = {'id': new_id, 'name': name, 'done': done}
        self.items.append(new_item)
        return new_item


