import bluetooth
import time
import sys

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_CHANNEL = 1

def send_command(sock, command):
    """Send a command prefixed with 'X' and terminated with a newline over the Bluetooth socket."""
    try:
        sock.sendall(f"X{command}\n".encode("utf-8"))
    except bluetooth.BluetoothError as e:
        raise RuntimeError(f"Failed to send command: {e}") from e

def main():
    sock = None
    try:
        sock = bluetooth.BluetoothSocket(bluetooth.RFCOMM)
        sock.connect(BLUETOOTH_DEVICE, BLUETOOTH_CHANNEL)
        print(f"Connected to {BLUETOOTH_DEVICE}")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.strip().lower() == "exit":
                print("Exit command received.")
                break

            try:
                send_command(sock, user_command)
                time.sleep(0.1)
            except RuntimeError as e:
                print(f"Error: {e}", file=sys.stderr)
                break

    except bluetooth.BluetoothError as e:
        print(f"Bluetooth error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if sock is not None:
            try:
                sock.close()
                print("Bluetooth connection closed.")
            except Exception as e:
                print(f"Error closing socket: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

